import type { Step3Spec } from './types';

const evidenceNote = 'AI-authored synthetic candidate, medically unreviewed. Source discovery/access checked 2026-10-30; page access or indexed text does not verify every assertion. A qualified reviewer must independently verify diagnosis, management currency, answer uniqueness and every distractor before approval. No clinical or rights approval is claimed.';
const stroke = [{label:'AHA/ASA Adult Stroke Rehabilitation and Recovery (2016; indexed, direct page returned403)',url:'https://www.ahajournals.org/doi/full/10.1161/STR.0000000000000098'}];
const seizure = [{label:'NINDS Epilepsy and Seizures (indexed source; full-page access not established)',url:'https://www.ninds.nih.gov/health-information/disorders/epilepsy-and-seizures'}];
const neuropathy = [{label:'NINDS Peripheral Neuropathy (indexed source; full-page access not established)',url:'https://www.ninds.nih.gov/health-information/disorders/peripheral-neuropathy'}];
const thiamin = [{label:'NIH ODS Thiamin: Health Professional Fact Sheet (page accessed 2026-10-30)',url:'https://ods.od.nih.gov/factsheets/Thiamin-HealthProfessional/'}];
const copper = [{label:'NIH ODS Copper: Health Professional Fact Sheet (page accessed 2026-10-30)',url:'https://ods.od.nih.gov/factsheets/Copper-HealthProfessional/'}];
const b12 = [{label:'NIH ODS Vitamin B12: Health Professional Fact Sheet (page accessed 2026-10-30)',url:'https://ods.od.nih.gov/factsheets/VitaminB12-HealthProfessional/'}];
const botulism = [{label:'CDC Clinical Guidelines for Diagnosis and Treatment of Botulism (2021; indexed source)',url:'https://www.cdc.gov/mmwr/volumes/70/rr/rr7002a1.htm'}];
const migraine = [{label:'AAN/AHS Pharmacologic Migraine Prevention (2026; indexed, direct page returned403)',url:'https://www.neurology.org/doi/full/10.1212/WNL.0000000000214881'}];
const myelitis = [{label:'NINDS Transverse Myelitis (indexed source; full-page access not established)',url:'https://www.ninds.nih.gov/health-information/disorders/transverse-myelitis'}];
const encephalitis = [{label:'NIH Meningitis and Encephalitis (indexed overview; treatment detail requires independent verification)',url:'https://health.nih.gov/health-topics-a-z/meningitis-and-encephalitis'}];
const rls = [{label:'AASM Treatment of Restless Legs Syndrome and Periodic Limb Movement Disorder (2025; indexed guideline)',url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC11701286/'}];

export const specs: Step3Spec[] = [
{code:'op-s3-0301',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Stroke nutrition safety',subtopic:'Screening before oral intake',concept:'preserved alertness does not establish swallow safety after stroke',task:'management',setting:'hospital',service:'stroke rehabilitation',ageGroup:'older-adult',nutrition:true,difficulty:3,difficultyRationale:'Separates neurological improvement from airway-protection assessment.',stem:'A 73-year-old woman is admitted after a pontine infarct. She is alert, follows commands, and can lift all four limbs. Her speech remains mildly slurred, but she denies trouble swallowing. A family member brings soup while the nurse prepares oral aspirin. No swallowing assessment has been documented. Oxygen saturation is 97% on room air. What should occur before she receives anything by mouth?',choices:[['Perform a validated swallowing screen by trained staff','Alertness and limb strength do not exclude pharyngeal dysfunction; screening should precede food, fluids, and oral medications after acute stroke.'],['Allow small sips because she denies dysphagia','Patients may have impaired awareness or silent aspiration; a symptom report alone cannot establish safe swallowing after a brainstem infarct.'],['Give prophylactic antibiotics and proceed with lunch','Antibiotics do not restore airway protection or prevent aspiration events, and routine prophylaxis is not a substitute for swallowing assessment.'],['Start thickened liquids without any assessment','Texture changes should follow individualized evaluation; empirically thickening all liquids can still permit aspiration and may reduce hydration or intake.']],explanation:'Brainstem stroke can disrupt coordinated swallowing despite preserved consciousness and relatively good limb strength. A validated screen performed by trained personnel identifies patients who need a formal dysphagia assessment before oral intake. Food, drinks, and oral drugs all pose aspiration risk. Failure of a screen should trigger an alternative medication and hydration plan plus specialist evaluation, rather than prolonged unsupported fasting. Neither normal oxygen saturation nor absence of reported choking proves that aspiration is absent; aspiration can be silent.',objective:'Screen swallowing before oral intake after acute stroke even when alertness and limb strength appear reassuring.',takeaways:['Swallowing safety requires assessment separate from the limb examination.','A failed screen requires a hydration and nutrition plan.'],references:stroke,evidenceNote,concerns:['The cited US rehabilitation guideline is from 2016; reviewer must confirm current acute-stroke screening workflow.']},
{code:'op-s3-0302',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Poststroke feeding access',subtopic:'Short-term enteral nutrition',concept:'early recovering dysphagia favors temporary nasogastric support',task:'management',setting:'hospital',service:'stroke rehabilitation',ageGroup:'adult',nutrition:true,difficulty:3,difficultyRationale:'Weighs expected swallowing recovery against nutritional need and procedure burden.',stem:'Five days after an ischemic stroke, a 59-year-old man remains unable to swallow safely on specialist assessment. He is awake, participates in therapy, and has a functioning gastrointestinal tract. The rehabilitation team expects swallowing to improve during the next two weeks. He has received insufficient calories despite intravenous maintenance fluids. There is no facial trauma or gastrointestinal obstruction. Which feeding strategy is most appropriate now?',choices:[['Provide temporary nasogastric enteral feeding with reassessment','A functioning gut and likely short duration of unsafe swallowing favor temporary enteral access while recovery and nutritional adequacy are reassessed.'],['Continue maintenance saline alone until swallowing returns','Maintenance fluids do not provide sufficient protein or energy; waiting without nutrition exposes this recovering patient to avoidable nutritional deterioration.'],['Place a permanent gastrostomy immediately in every stroke patient','Gastrostomy may suit prolonged dysphagia, but an invasive long-term route is premature when improvement is expected within a short interval.'],['Begin total parenteral nutrition despite available enteral access','Parenteral nutrition introduces catheter and metabolic risks and is generally unnecessary when the gastrointestinal tract can provide adequate enteral nutrition.']],explanation:'Unsafe swallowing does not require withholding nutrition when the gastrointestinal tract works. Temporary nasogastric feeding supports energy, protein, fluids, and appropriate medications during early recovery, with ongoing swallowing therapy and reassessment. Gastrostomy can be considered when prolonged inability to eat is anticipated, taking prognosis and patient preferences into account. Feeding tubes do not eliminate aspiration of oral secretions or reflux, so positioning, oral care, and monitoring remain important. The decision tests the expected duration and usable route, rather than assuming intravenous fluids constitute nutritional support.',objective:'Choose temporary enteral access for early poststroke dysphagia when the gut functions and recovery is expected soon.',takeaways:['Intravenous maintenance fluids are not complete nutrition.','Reassess swallowing and feeding goals over time.'],references:stroke,evidenceNote,concerns:['Confirm contemporary US guidance on gastrostomy timing and local nasogastric-placement contraindications.']},
{code:'op-s3-0303',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Cerebral venous thrombosis',subtopic:'Postpartum progressive headache',concept:'postpartum seizure with hemorrhagic nonarterial infarct suggests venous occlusion',task:'diagnosis',setting:'emergency',service:'emergency neurology',ageGroup:'adult',nutrition:false,difficulty:4,difficultyRationale:'Integrates postpartum thrombosis risk, progressive symptoms and infarct distribution.',stem:'A 31-year-old woman presents nine days after delivery with a steadily worsening headache and a new focal seizure involving her right hand. Blood pressure is 124/76 mm Hg; she has no fever or proteinuria. Examination reveals mild right arm weakness and optic disc swelling. CT shows a small left frontal hemorrhagic lesion extending across an arterial boundary. Which study best evaluates the leading diagnosis?',choices:[['MR venography of the cerebral venous system','Progressive postpartum headache, papilledema, focal seizure, and a hemorrhagic lesion outside a single arterial territory suggest cerebral venous thrombosis.'],['Routine outpatient electroencephalography as the sole investigation','EEG may characterize seizures but does not evaluate the underlying venous obstruction responsible for raised pressure and this hemorrhagic infarct pattern.'],['Carotid ultrasonography without intracranial venous imaging','Carotid disease causes arterial ischemic patterns and does not adequately investigate dural sinus thrombosis or explain raised intracranial pressure here.'],['Lumbar puncture before further imaging','Papilledema, focal deficit, and an intracranial hemorrhagic lesion require imaging-based evaluation before considering lumbar puncture for alternative diagnoses.']],explanation:'Pregnancy-associated hypercoagulability can persist postpartum and predispose to cerebral venous sinus thrombosis. Venous outflow obstruction raises intracranial pressure and can cause hemorrhagic infarction that does not respect arterial territories. MR venography, or an appropriate CT venographic protocol when indicated, directly evaluates the venous system. Normal blood pressure and absent proteinuria make a hypertensive pregnancy-related syndrome less persuasive, although postpartum headache still requires a broad assessment. The seizure is a consequence to treat, not an adequate explanation for the evolving headache and imaging abnormality.',objective:'Investigate suspected postpartum cerebral venous thrombosis with dedicated venous imaging when symptoms and hemorrhage distribution are nonarterial.',takeaways:['Venous infarcts can be hemorrhagic.','Routine arterial studies do not replace venography.'],references:[{label:'AHA Diagnosis and Management of Cerebral Venous Thrombosis scientific statement (2024; exact claim review pending)',url:'https://www.ahajournals.org/doi/10.1161/STR.0000000000000456'}],evidenceNote,concerns:['Direct AHA statement access returned403; bibliographic identity and every diagnostic claim require independent confirmation.']},
{code:'op-s3-0304',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Persistent status epilepticus',subtopic:'Therapy after adequate benzodiazepine',concept:'ongoing convulsion after adequate benzodiazepine needs urgent second-line antiseizure loading',task:'management',setting:'emergency',service:'emergency critical care',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Recognizes failure of the initial treatment stage despite normal glucose.',stem:'A 44-year-old man with epilepsy has continuous generalized convulsions for eight minutes. Oxygen, suction, monitoring, and intravenous access are established. Bedside glucose is 112 mg/dL. An adequate weight-based dose of intravenous lorazepam is given and repeated according to protocol, but convulsions continue. Blood pressure is 136/84 mm Hg. Which action is most appropriate while the team prepares for possible airway escalation?',choices:[['Load an intravenous second-line antiseizure drug such as levetiracetam','Persistent convulsive status after adequate benzodiazepine treatment requires rapid escalation to a longer-acting intravenous antiseizure agent with continued airway monitoring.'],['Wait thirty minutes for a routine EEG before further medication','Visible ongoing generalized convulsions establish the emergency; delaying treatment for diagnostic recording prolongs seizures and increases physiological and neuronal injury risk.'],['Give oral maintenance tablets and observe for absorption','Oral absorption is too slow and unsafe during convulsions, and a maintenance dose does not provide the rapid loading needed.'],['Give intravenous dextrose as the only next seizure treatment','Dextrose treats hypoglycemic seizures, but the measured glucose is normal; it does not replace second-line antiseizure loading for ongoing benzodiazepine-resistant convulsions.']],explanation:'Convulsive status epilepticus is treated as a time-sensitive emergency. Benzodiazepines are initial therapy, but persistent seizures after adequate dosing require prompt intravenous second-line loading rather than repeated delays. Levetiracetam is one accepted option; other choices depend on contraindications and protocol. Airway support, temperature and metabolic assessment, trigger investigation, and readiness for refractory-status treatment proceed concurrently. EEG is important when clinical convulsions stop without recovery or when refractory status is suspected, but it should not delay treatment of unmistakable ongoing generalized convulsions.',objective:'Escalate persistent convulsive status promptly after adequate initial benzodiazepine therapy.',takeaways:['Treat the seizure while investigating its trigger.','Use a rapid intravenous loading strategy when initial therapy fails.'],references:seizure,evidenceNote,concerns:['Verify current second-line status protocol and equivalent alternatives; source overview does not establish dosing.']},
{code:'op-s3-0305',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Nonconvulsive status',subtopic:'Failure to regain consciousness',concept:'subtle recurring motor signs after apparent seizure termination require urgent EEG',task:'diagnosis',setting:'hospital',service:'neurocritical care',ageGroup:'older-adult',nutrition:false,difficulty:3,difficultyRationale:'Distinguishes ongoing electrical seizures from an assumed postictal period.',stem:'A 70-year-old man is treated for a prolonged focal-to-bilateral convulsion. Visible shaking stops after medication, but forty minutes later he still does not follow commands. Oxygenation, blood pressure, glucose, sodium, and temperature are normal. CT shows no acute hemorrhage. The nurse notices repeated brief left eyelid twitching and gaze deviation. Which investigation should be obtained urgently to explain his persistent impaired responsiveness?',choices:[['Continuous or urgent electroencephalographic monitoring','Persistent impaired consciousness with recurring subtle motor signs can represent ongoing electrical seizures despite cessation of generalized visible convulsions.'],['Repeat structural CT as the sole evaluation before considering EEG','Structural imaging may be repeated if new findings warrant it, but a recent unrevealing CT cannot identify ongoing electrical seizures causing the recurring stereotyped signs.'],['Perform lumbar puncture before considering electrical seizure monitoring','CSF studies may be appropriate for a suspected infectious trigger, but no infectious features are provided and they do not identify ongoing electrical status.'],['Observe as an uncomplicated postictal state without further investigation','Postictal recovery varies, but assuming that explanation without reassessment risks missing nonconvulsive status, especially with persistent stereotyped twitching and gaze deviation.']],explanation:'Stopping visible convulsions does not guarantee that cerebral seizure activity has ended. Nonconvulsive status can produce persistent coma, confusion, or small repetitive movements and is confirmed by EEG interpreted in the clinical context. Medication sedation and a postictal state remain alternatives, but normal bedside metabolic results do not distinguish them from ongoing electrical seizures. Urgent monitoring can identify a treatable cause and guide therapy. The recurrent stereotyped focal signs make passive observation particularly unsafe, even though the initial convulsion has apparently resolved.',objective:'Use urgent EEG to evaluate suspected nonconvulsive status after apparent termination of convulsive seizures.',takeaways:['Clinical motor cessation does not prove electrical seizure cessation.','Reassess delayed recovery rather than labeling it automatically postictal.'],references:seizure,evidenceNote,concerns:['Reviewer should confirm the monitoring indication without implying one universal postictal time cutoff.']},
{code:'op-s3-0306',category:'neurological',subject:'Pharmacology',system:'Nervous System',topic:'Antiseizure drug encephalopathy',subtopic:'Valproate and ammonia',concept:'valproate associated ammonia elevation can cause encephalopathy without hepatic failure',task:'diagnosis',setting:'hospital',service:'neurology consultation',ageGroup:'adult',nutrition:true,difficulty:4,difficultyRationale:'Integrates medication change, poor intake and ammonia despite normal hepatic tests.',stem:'A 36-year-old woman taking valproate for generalized epilepsy develops vomiting, lethargy, and slowed responses after a dose increase. She has eaten little for a week because of nausea. Examination shows asterixis without focal weakness. Glucose and sodium are normal, liver aminotransferases and bilirubin are normal, and serum ammonia is markedly elevated. EEG shows generalized slowing without seizures. What best explains this deterioration?',choices:[['Valproate-associated hyperammonemic encephalopathy','Valproate can disrupt ammonia handling, sometimes involving carnitine depletion; encephalopathy may occur despite normal hepatic biochemical tests and a therapeutic drug concentration.'],['Acute hepatic failure proven by the ammonia result','Ammonia elevation alone does not prove hepatic failure; the medication exposure and absence of reported hepatic injury favor a drug-associated process.'],['Nonconvulsive status established by generalized EEG slowing','Generalized slowing indicates diffuse dysfunction and is not equivalent to an ictal pattern; the described EEG provides no evidence of ongoing seizures.'],['Isolated dietary protein excess requiring permanent protein elimination','The patient has poor intake rather than protein excess, and permanent protein elimination could worsen malnutrition without addressing the medication-associated disturbance.']],explanation:'Valproate-associated hyperammonemic encephalopathy should be considered when a patient develops cognitive slowing, vomiting, or reduced consciousness during treatment. Normal aminotransferases do not exclude it. Effects on urea-cycle metabolism and carnitine availability can contribute, and nutritional depletion increases concern. Management requires urgent clinical assessment, interruption of the offending drug when appropriate, seizure coverage, and consideration of levocarnitine with specialist or toxicology input. The question asks for the unifying diagnosis, not a fixed antidote dose; an underlying urea-cycle disorder may need investigation in severe or recurrent cases.',objective:'Recognize valproate-related hyperammonemic encephalopathy despite normal liver tests, particularly with nutritional depletion.',takeaways:['Ammonia elevation does not by itself diagnose hepatic failure.','Review drug and nutritional contributors to encephalopathy.'],references:[{label:'DailyMed official valproic acid labeling; product-specific label and hyperammonemia warnings require verification',url:'https://dailymed.nlm.nih.gov/dailymed/search.cfm?query=valproic+acid'}],evidenceNote,concerns:['Search portal is not a fixed product label; reviewer must attach exact current labeling and verify carnitine indications.']},
{code:'op-s3-0307',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Postbariatric encephalopathy',subtopic:'Urgent thiamine replacement',concept:'prolonged vomiting after bariatric surgery can cause acute thiamine neurological injury',task:'management',setting:'emergency',service:'emergency nutrition neurology',ageGroup:'adult',nutrition:true,difficulty:3,difficultyRationale:'Connects a nonalcohol-related nutritional exposure to a treatable neurological emergency.',stem:'A 29-year-old woman underwent gastric bypass seven weeks ago and has vomited almost daily for three weeks. She now needs support to walk and cannot follow a conversation. Examination shows horizontal nystagmus and impaired abduction of both eyes. Glucose is 91 mg/dL, and CT shows no hemorrhage. She does not drink alcohol. Which intervention should begin immediately while additional evaluation proceeds?',choices:[['Administer parenteral thiamine','Prolonged vomiting after bariatric surgery can rapidly deplete thiamine, and the ocular, gait, and cognitive findings warrant immediate parenteral treatment.'],['Wait for a serum thiamine level before treatment','Laboratory confirmation can be delayed or unreliable and should not postpone treatment when suspected thiamine-related neurological injury may become irreversible.'],['Give folate alone and arrange routine clinic follow-up','Folate addresses a different nutritional pathway and does not treat this acute ocular, cerebellar, and cognitive syndrome requiring urgent monitored care.'],['Exclude a vitamin disorder because alcohol use is absent','Thiamine depletion also occurs with vomiting, malabsorption, starvation, and bariatric surgery; alcohol exposure is neither required nor sufficient for diagnosis.']],explanation:'The clinical pattern suggests Wernicke encephalopathy caused by thiamine depletion after prolonged postoperative vomiting. Alcohol use is not required. Prompt parenteral replacement is appropriate because oral absorption and intake may be inadequate and neurological injury can become permanent. Magnesium and other nutritional or electrolyte deficiencies should also be assessed, and the cause of vomiting investigated. If hypoglycemia were present, emergency glucose should not be delayed; thiamine should be given promptly alongside treatment. A normal CT does not exclude this metabolic neurological condition.',objective:'Treat suspected Wernicke encephalopathy promptly in a vomiting postbariatric patient regardless of alcohol history.',takeaways:['Bariatric vomiting is a thiamine-risk history.','Do not delay emergency glucose for thiamine when hypoglycemia is present.'],references:thiamin,evidenceNote,concerns:['Parenteral regimen and magnesium replacement need current local specialist guidance; no dose is specified.']},
{code:'op-s3-0308',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Nutritional myelopathy',subtopic:'Zinc-associated copper depletion',concept:'excess zinc can cause copper-deficient myeloneuropathy with cytopenias',task:'diagnosis',setting:'ambulatory',service:'longitudinal neurology',ageGroup:'older-adult',nutrition:true,difficulty:4,difficultyRationale:'Integrates supplements, posterior-column dysfunction and unexplained cytopenias.',stem:'A 68-year-old man develops progressive imbalance and hand tingling over six months. Vibration and position sense are reduced in his feet, and knee reflexes are brisk. Hemoglobin is 9.8 g/dL and the neutrophil count is low. Vitamin B12 and methylmalonic acid are normal. He has taken high-dose zinc tablets daily for two years to prevent colds. Which additional measurement most directly evaluates the suspected cause?',choices:[['Serum copper with ceruloplasmin','Excess zinc impairs copper absorption, and copper depletion can combine a posterior-column myeloneuropathy with anemia and neutropenia resembling other neurological deficiencies.'],['Serum iron as the only additional nutritional investigation','Iron deficiency can cause anemia but does not adequately explain combined myelopathy and neutropenia in the setting of sustained excessive zinc exposure.'],['Serum calcium to establish an acute tetany syndrome','Acute hypocalcemia causes neuromuscular irritability rather than this slowly progressive sensory ataxia with cytopenias and a specific competing mineral exposure.'],['Serum folate to prove all neurological deficiency syndromes','Folate deficiency can cause macrocytic anemia but does not typically explain this posterior-column syndrome, and it cannot substitute for evaluating copper.']],explanation:'Copper deficiency is an important acquired mimic of subacute combined degeneration. Prolonged high zinc intake can reduce intestinal copper absorption, and neurological findings may coexist with anemia and neutropenia. Normal B12 and methylmalonic acid make B12 deficiency less likely in this vignette without excluding every alternative diagnosis. Serum copper and ceruloplasmin help evaluate the suspected depletion, although both require interpretation in context. Stopping unnecessary zinc and replacing copper under supervision can arrest progression; neurological recovery may be incomplete, making timely recognition important.',objective:'Investigate copper deficiency when chronic zinc exposure accompanies sensory myelopathy and cytopenias.',takeaways:['Ask specifically about over-the-counter mineral products.','Nutritional myelopathy may accompany marrow abnormalities.'],references:copper,evidenceNote,concerns:['Verify zinc exposure interpretation, copper biomarkers and replacement approach; biomarker limitations remain important.']},
{code:'op-s3-0309',category:'neurological',subject:'Pharmacology',system:'Nervous System',topic:'Supplement neurotoxicity',subtopic:'Pyridoxine excess',concept:'multiple supplements can produce cumulative pyridoxine sensory toxicity',task:'management',setting:'ambulatory',service:'primary care neurology',ageGroup:'adult',nutrition:true,difficulty:3,difficultyRationale:'Requires medication reconciliation rather than reflexively adding a vitamin.',stem:'A 47-year-old woman has gradually worsening burning feet and imbalance. Glucose testing, kidney function, B12, and thyroid studies are normal. She takes an energy powder, a magnesium product, and a B-complex tablet; review shows that all contain pyridoxine and her combined intake is markedly above the recommended daily amount. Examination reveals distal sensory loss without weakness. What is the most appropriate next step?',choices:[['Stop excessive pyridoxine exposure and reassess the neuropathy','Cumulative vitamin B6 exposure from several products can cause sensory neuropathy; removing the suspected excess is appropriate while evaluating other causes.'],['Double the B-complex dose to regenerate peripheral nerves','More pyridoxine can worsen a toxicity-related neuropathy, and an unselected vitamin escalation ignores the excessive exposure already identified during reconciliation.'],['Reassure her that water-soluble vitamins cannot cause toxicity','Water solubility does not guarantee safety at supplemental doses; pyridoxine is a recognized cause of sensory neurological injury with excess exposure.'],['Start immunosuppression solely on the basis of burning pain','Burning pain is nonspecific and does not establish immune neuropathy; an identifiable potentially toxic supplement exposure should be addressed first.']],explanation:'Supplement reconciliation must include the total amount of each ingredient across products. Pyridoxine excess can produce predominantly sensory neuropathy and imbalance; taking several apparently different supplements can create an unrecognized cumulative dose. The appropriate action is to remove unnecessary excessive exposure, assess severity, and follow neurological function while continuing an appropriate differential evaluation. Recovery may be gradual and incomplete. This case does not establish a single universal toxic threshold because susceptibility and duration vary, and regional regulatory intake limits are not identical.',objective:'Recognize cumulative pyridoxine exposure as a reversible contributor to sensory neuropathy and stop the excess.',takeaways:['Count ingredients across all supplements.','Water-soluble does not mean harmless at high intake.'],references:[{label:'Australian TGA safety update: Peripheral neuropathy with supplementary vitamin B6 (indexed regulatory source)',url:'https://www.tga.gov.au/news/safety-updates/peripheral-neuropathy-supplementary-vitamin-b6-pyridoxine'}],evidenceNote,concerns:['Australian regulatory source does not define US intake policy; exact dose-response and recovery claims need review.']},
{code:'op-s3-0310',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Metformin and B12',subtopic:'Risk-based nutritional evaluation',concept:'long-term metformin neuropathy should prompt B12 assessment rather than automatic attribution to diabetes',task:'diagnosis',setting:'ambulatory',service:'diabetes longitudinal care',ageGroup:'older-adult',nutrition:true,difficulty:3,difficultyRationale:'Distinguishes a treatable nutritional contributor from diagnostic anchoring on diabetes.',stem:'A 66-year-old woman with type 2 diabetes treated with metformin for twelve years reports new numbness and difficulty walking in the dark. Her glycated hemoglobin has remained near 6.7%, and she has no retinopathy. Examination shows reduced vibration in the feet. Hemoglobin is 11.1 g/dL with a mean corpuscular volume of 104 fL. She eats a varied diet. Which test is most appropriate next?',choices:[['Serum vitamin B12, with a functional marker if the result is indeterminate','Long-term metformin exposure, macrocytosis, and sensory dysfunction justify evaluating a potentially treatable B12 deficiency even when dietary intake appears adequate.'],['No testing because diabetes fully explains every sensory complaint','Diabetes is common but does not eliminate additional causes; macrocytosis and prolonged metformin exposure specifically warrant evaluation for a nutritional contributor.'],['Serum albumin alone to exclude all micronutrient deficiencies','Albumin reflects multiple nonnutritional influences and can be normal despite B12 deficiency; it does not evaluate this specific neurological and hematological pattern.'],['A fasting insulin level to determine the nerve lesion location','Insulin concentration does not establish the cause or localization of this sensory deficit and would not investigate the associated macrocytosis.']],explanation:'Metformin can reduce B12 absorption during long-term treatment. New sensory symptoms accompanied by macrocytosis should therefore prompt B12 evaluation rather than automatic attribution to diabetic neuropathy. A borderline serum value may require methylmalonic acid or another appropriate functional assessment, interpreted with renal function. A varied diet does not exclude impaired absorption. If clinically significant neurological deficiency is suspected, evaluation and treatment should proceed promptly rather than waiting for advanced anemia. The aim is to identify an additional modifiable contributor while maintaining appropriate diabetes care.',objective:'Assess B12 status in long-term metformin users with new neuropathic symptoms or macrocytosis.',takeaways:['Dietary adequacy does not exclude impaired absorption.','Diabetes and nutritional neuropathy can coexist.'],references:b12,evidenceNote,concerns:['Overlaps B12 domain with existing bank but tests metformin-associated evaluation rather than nitrous oxide or immediate replacement; semantic review required.']},
{code:'op-s3-0311',category:'neurological',subject:'Biochemistry',system:'Nervous System',topic:'Thiamine-dependent energy metabolism',subtopic:'Lactate during nutritional depletion',concept:'thiamine depletion limits pyruvate oxidation and promotes lactate formation',task:'foundational-science',setting:'hospital',service:'nutrition neurology',ageGroup:'adult',nutrition:true,difficulty:3,difficultyRationale:'Links nutritional history to oxidative metabolism rather than assuming tissue hypoxia.',stem:'A 42-year-old man with severe food insecurity has eaten mainly sweetened tea and crackers for two months. He presents with confusion and gait instability. Lactate remains elevated despite restoration of normal blood pressure, oxygenation, and intravascular volume; cultures reveal no infection. Neurological findings improve after parenteral thiamine. Impaired activity of which enzyme most directly explains the diversion of pyruvate toward lactate before treatment?',choices:[['Pyruvate dehydrogenase','Thiamine pyrophosphate is a required cofactor for this complex, so deficiency reduces entry of pyruvate carbon into oxidative acetyl-CoA metabolism.'],['Lactate dehydrogenase','This enzyme converts pyruvate to lactate and remains available during thiamine depletion; its increased flux is the consequence rather than the deficient step.'],['Glucose-6-phosphatase','This gluconeogenic enzyme releases free glucose and is not the thiamine-dependent mitochondrial link between glycolytic pyruvate and acetyl-CoA formation.'],['Alpha-ketoglutarate dehydrogenase','This enzyme also requires thiamine, but it acts within the citric acid cycle rather than directly converting pyruvate into acetyl-CoA at the specified branch point.']],explanation:'Thiamine pyrophosphate participates in several reactions, including the pyruvate dehydrogenase complex. Without adequate cofactor, pyruvate is less effectively converted to acetyl-CoA and is diverted toward lactate regeneration of NAD+. Consequently, nutritional deficiency can contribute to elevated lactate even when oxygen delivery and circulation have been corrected. The dietary history and neurological response support this mechanism, but elevated lactate still demands evaluation for sepsis, ischemia, medication effects, and other causes. Thiamine treatment does not remove the need to identify the broader cause of malnutrition.',objective:'Connect thiamine depletion with impaired pyruvate oxidation and a potentially nonhypoxic contribution to lactate elevation.',takeaways:['Lactate elevation has causes beyond tissue hypoxia.','Micronutrient replacement complements evaluation of nutritional deprivation.'],references:thiamin,evidenceNote,concerns:['Reviewer should verify biochemical specificity and avoid treating thiamine response as a standalone diagnostic test.']},
{code:'op-s3-0312',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Fat-soluble vitamin neuropathy',subtopic:'Vitamin E during fat malabsorption',concept:'chronic fat malabsorption can cause vitamin E associated sensory ataxia',task:'diagnosis',setting:'ambulatory',service:'gastroenterology neurology',ageGroup:'adult',nutrition:true,difficulty:3,difficultyRationale:'Combines malabsorption and neurological localization with exclusion of B12 depletion.',stem:'A 38-year-old man with long-standing pancreatic insufficiency reports worsening balance and difficulty using stairs in dim light. He often skips pancreatic enzymes because of cost and has bulky oily stools. Examination shows absent ankle reflexes, impaired vibration, and limb dysmetria. Vitamin B12 and methylmalonic acid are normal. Which deficiency should be investigated as a potentially treatable contributor to his neurological symptoms?',choices:[['Vitamin E','Fat malabsorption can reduce vitamin E uptake, and depletion may cause peripheral neuropathy, impaired proprioception, and ataxia resembling inherited neurological disorders.'],['Vitamin C','Vitamin C deficiency chiefly causes connective-tissue manifestations such as gingival bleeding and bruising rather than the combined sensory and coordination deficits described.'],['Vitamin K','Vitamin K deficiency may accompany fat malabsorption but principally impairs coagulation; it does not usually produce this progressive sensory ataxia syndrome.'],['Folate','Folate depletion can contribute to macrocytic anemia, but it does not characteristically cause this posterior-column and peripheral neurological phenotype with chronic fat malabsorption.']],explanation:'Vitamin E is absorbed with fat, making chronic pancreatic insufficiency and inadequate enzyme treatment important risk factors for depletion. Deficiency can affect peripheral nerves and sensory pathways, producing areflexia, loss of position or vibration sense, and ataxia. Testing and replacement require interpretation alongside lipid status and the underlying malabsorptive disease. Improving access to pancreatic enzyme treatment addresses an ongoing cause rather than merely replacing one vitamin. The neurological pattern also warrants consideration of B12, copper, hereditary ataxias, and other causes when the course or response is atypical.',objective:'Consider vitamin E depletion in sensory ataxia associated with chronic fat malabsorption.',takeaways:['Address the cause of malabsorption alongside replacement.','A normal B12 result does not exclude other nutritional neurological disease.'],references:[{label:'NIH ODS Vitamin E: Health Professional Fact Sheet (indexed source)',url:'https://ods.od.nih.gov/factsheets/VitaminE-HealthProfessional/'}],evidenceNote,concerns:['Vitamin E assay interpretation and replacement formulation in malabsorption require specialist verification.']},
{code:'op-s3-0313',category:'neurological',subject:'Pharmacology',system:'Nervous System',topic:'Levodopa and meal composition',subtopic:'Amino-acid competition',concept:'large neutral dietary amino acids can interfere with levodopa availability',task:'foundational-science',setting:'ambulatory',service:'movement disorders',ageGroup:'older-adult',nutrition:true,difficulty:3,difficultyRationale:'Interprets a reproducible meal-drug interaction without proposing protein deprivation.',stem:'A 71-year-old man with Parkinson disease takes carbidopa-levodopa on a stable schedule. His morning dose works predictably, but the lunch dose often has little effect since he began drinking a large protein supplement with lunch. His weight is low and the dietitian wants to preserve total daily protein intake. Which mechanism best explains the meal-associated decline in response?',choices:[['Competition between levodopa and large neutral amino acids for transport','Levodopa shares transport pathways with dietary amino acids, so a large protein load can reduce or delay its clinical availability in susceptible patients.'],['Irreversible destruction of dopamine receptors by dietary protein','Dietary protein does not irreversibly destroy dopamine receptors; this reproducible timing pattern is more consistent with a transport or absorption interaction.'],['Chelation of levodopa by dietary glucose','The reported change involves a protein supplement, and glucose chelation does not explain competition at amino-acid transport pathways relevant to levodopa.'],['Complete conversion of carbidopa into dietary amino acids','Carbidopa inhibits peripheral decarboxylation; it is not consumed by conversion into amino acids when a patient eats a protein-rich meal.']],explanation:'Levodopa resembles a large neutral amino acid and can compete with dietary amino acids during intestinal and blood-brain transport. A protein-associated fluctuation is therefore plausible when symptoms correlate reproducibly with a large supplement. Management can include individualized medication timing or redistribution of protein across the day, while maintaining adequate overall nutrition. This is particularly important in an underweight patient; indiscriminate protein restriction would be harmful. Other explanations for fluctuations, including gastric emptying, adherence, and progression, still require review before attributing every off period to meals.',objective:'Explain protein-associated levodopa fluctuations without recommending nutritionally unsafe global protein restriction.',takeaways:['Meal composition can influence drug response.','Preserve total nutritional adequacy when adjusting timing.'],references:[{label:'NINDS Parkinson disease overview; interaction-specific evidence still needs verification',url:'https://www.ninds.nih.gov/health-information/disorders/parkinsons-disease'}],evidenceNote,concerns:['Direct NINDS page access returned403; attach authoritative medication-specific evidence for the levodopa-protein interaction before approval.']},
{code:'op-s3-0314',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Restless legs and iron',subtopic:'Iron depletion without anemia',concept:'low iron stores can merit replacement in clinically typical restless legs without anemia',task:'management',setting:'ambulatory',service:'sleep medicine',ageGroup:'adult',nutrition:true,difficulty:3,difficultyRationale:'Separates iron-store assessment from the presence of anemia.',stem:'A 46-year-old woman reports an evening urge to move her legs that begins while sitting and improves when she walks. There is no weakness, sensory loss, or leg swelling. She has heavy menstrual bleeding and eats little iron-rich food. Hemoglobin is 12.6 g/dL, ferritin is 14 ng/mL, and transferrin saturation is low. Which component should be included in the initial management plan?',choices:[['Replace depleted iron stores and evaluate the source of iron loss','Typical restless legs with clearly depleted iron stores warrants iron repletion and investigation of ongoing loss even when hemoglobin remains normal.'],['Withhold iron because the hemoglobin is within the laboratory range','Iron depletion can precede anemia, and iron-store assessment is relevant to restless legs rather than being determined solely by hemoglobin concentration.'],['Prescribe escalating dopamine agonists without addressing iron depletion','Symptom drugs do not correct the demonstrated deficiency, and some dopaminergic strategies carry augmentation risks that require consideration in current guidance.'],['Recommend strict bed rest whenever symptoms occur','Symptoms characteristically improve with movement; bed rest does not replace evaluation and treatment of the iron depletion or other provoking factors.']],explanation:'The timing, urge to move, worsening at rest, and relief with activity support restless legs syndrome. Markedly low ferritin and transferrin saturation identify a modifiable contributor even before overt anemia appears. Replacement should be individualized to tolerance, absorption, degree of depletion, and contemporary guidance, while menstrual blood loss and dietary adequacy are evaluated. Medication review and aggravating factors also matter. This question uses unequivocally low stores and avoids relying on a disputed borderline cutoff; iron treatment should still be monitored rather than continued indefinitely without reassessment.',objective:'Include iron repletion and evaluation of iron loss in restless legs syndrome with clearly depleted stores despite normal hemoglobin.',takeaways:['Normal hemoglobin does not establish iron sufficiency.','Investigate why stores are depleted.'],references:rls,evidenceNote,concerns:['Confirm current AASM route-of-replacement recommendations and monitoring before clinical use.']},
{code:'op-s3-0315',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Foodborne descending paralysis',subtopic:'Immediate botulism treatment',concept:'suspected foodborne botulism needs antitoxin consultation without waiting for laboratory confirmation',task:'management',setting:'emergency',service:'emergency critical care',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Prioritizes time-sensitive treatment over a delayed confirmatory assay.',stem:'A 52-year-old man develops diplopia, dry mouth, dysarthria, and symmetric descending weakness after sharing home-preserved vegetables. His spouse has similar symptoms. He is afebrile and alert, with dilated poorly reactive pupils and no sensory loss. Respiratory strength is declining, and airway support is being arranged. What additional action should occur immediately while diagnostic specimens are collected?',choices:[['Contact public health for emergency botulism consultation and antitoxin','The exposure cluster and cranial-to-descending paralysis are highly concerning for botulism; early antitoxin can limit further toxin-mediated injury and should not await confirmation.'],['Wait for a stool toxin result before requesting antitoxin','Laboratory confirmation may take time, while unbound toxin can continue causing paralysis; delaying consultation sacrifices the opportunity for earlier neutralization.'],['Give a cholinesterase inhibitor as definitive treatment','This does not neutralize circulating botulinum toxin and is not definitive therapy for foodborne botulism with progressive respiratory weakness.'],['Administer high-dose corticosteroids as the only disease-specific therapy','Corticosteroids do not neutralize the toxin and are not a substitute for prompt antitoxin assessment, respiratory support, and public-health involvement.']],explanation:'Foodborne botulism produces an acute afebrile syndrome of cranial neuropathies followed by symmetric descending weakness, often with autonomic signs and preserved sensation. Multiple affected diners strengthen the exposure link. Respiratory stabilization is essential, and emergency consultation through public-health channels facilitates antitoxin assessment. Antitoxin neutralizes circulating toxin but does not reverse toxin already bound to nerve terminals, explaining why treatment should not wait for laboratory proof. Specimen collection remains important, but logistics should be coordinated so they do not delay needed treatment.',objective:'Arrange emergency antitoxin consultation for clinically suspected foodborne botulism without waiting for confirmatory toxin testing.',takeaways:['Antitoxin prevents additional injury rather than instantly reversing established paralysis.','Support ventilation and involve public health promptly.'],references:botulism,evidenceNote,concerns:['Confirm current US antitoxin access pathway; infant botulism requires a different product and pathway.']},
{code:'op-s3-0316',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Acute tick-associated paralysis',subtopic:'Exposure-based diagnosis',concept:'rapid areflexic weakness with attached tick and improvement after removal suggests tick paralysis',task:'diagnosis',setting:'emergency',service:'pediatric emergency neurology',ageGroup:'pediatric',nutrition:false,difficulty:3,difficultyRationale:'Uses exposure and recovery trajectory to distinguish an acute weakness differential.',stem:'A previously healthy 7-year-old girl develops an unsteady gait and progressive leg weakness during a camping trip. She is afebrile, alert, and has absent leg reflexes without sensory loss. Careful scalp examination finds an engorged attached tick. The tick is removed, respiratory strength is monitored, and substantial improvement begins over the next day. Which diagnosis best explains the complete course?',choices:[['Tick paralysis','A toxin-associated paralysis can cause acute areflexic weakness during tick attachment and improve after removal, fitting the exposure and recovery trajectory.'],['Chronic inflammatory demyelinating polyneuropathy','A chronic immune neuropathy usually evolves over a longer interval and would not be expected to improve promptly simply after tick removal.'],['Acute transverse myelitis','A spinal cord syndrome generally includes a sensory level, autonomic dysfunction, or evolving upper motor signs rather than this exposure-linked rapidly reversible pattern.'],['Duchenne muscular dystrophy','Duchenne disease causes progressive childhood muscle weakness over years and does not produce sudden areflexic paralysis with rapid recovery after an exposure ends.']],explanation:'Tick paralysis belongs in the differential of acute flaccid weakness, particularly after outdoor exposure. A meticulous skin and scalp examination can identify an attached tick that is easy to miss. Improvement after removal supports the diagnosis, although speed and severity vary by tick species and region; respiratory deterioration can still occur and monitoring is needed. Guillain-Barre syndrome and other neurological emergencies should remain under consideration when recovery is not as expected. The decisive clue is the exposure-linked course rather than areflexia alone.',objective:'Recognize tick paralysis from an attached tick and exposure-linked recovery while preserving respiratory monitoring.',takeaways:['Examine the scalp in acute flaccid weakness after camping.','Tick species and geography influence the course.'],references:[{label:'CDC MMWR Tick Paralysis, Colorado 2006; historical source requiring geographic review',url:'https://www.cdc.gov/mmwr/preview/mmwrhtml/mm5534a1.htm'}],evidenceNote,concerns:['CDC2006 report accessed; species and geographic differences and individual recovery intervals still require review.']},
{code:'op-s3-0317',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Guillain-Barre immunotherapy',subtopic:'Nonambulatory disease',concept:'functionally significant GBS requires effective immunotherapy rather than corticosteroid monotherapy',task:'management',setting:'hospital',service:'neuromuscular critical care',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Tests disease-specific treatment after the diagnosis and respiratory plan are already established.',stem:'A 40-year-old man has confirmed Guillain-Barre syndrome after a diarrheal illness. Within four days he progresses from walking unaided to being unable to stand. He is admitted for respiratory and autonomic monitoring; renal function and hemodynamics are stable. The team discusses disease-modifying therapy. Which treatment is an accepted option for this degree of rapidly progressive functional impairment?',choices:[['Intravenous immunoglobulin','IVIG is an accepted disease-specific treatment for significant acute Guillain-Barre syndrome; plasma exchange is another effective option selected according to clinical circumstances.'],['Oral prednisone as the sole disease-modifying treatment','Corticosteroid monotherapy has not shown the expected benefit in Guillain-Barre syndrome and should not replace established immunotherapy for rapidly progressive nonambulatory disease.'],['Levodopa to restore peripheral motor transmission','Levodopa treats selected central dopaminergic motor disorders and does not address the acute immune-mediated peripheral nerve injury causing this patient\'s weakness.'],['Observation without immunotherapy until weakness has lasted months','Waiting for a chronic course misses the early treatment opportunity in rapidly progressive disease and exposes the patient to additional disability and respiratory risk.']],explanation:'The question begins after diagnostic confirmation and focuses on treatment rather than recognition of the classic syndrome. Rapid progression to inability to walk is a strong reason to initiate accepted immunotherapy, commonly IVIG or plasma exchange. These are alternatives, not automatically a combined sequence. Respiratory mechanics, bulbar function, autonomic instability, thrombosis prevention, pain, and rehabilitation require ongoing attention regardless of treatment choice. Corticosteroids should not be extrapolated from other inflammatory neurological disorders as effective monotherapy for Guillain-Barre syndrome.',objective:'Select established immunotherapy for rapidly progressive nonambulatory Guillain-Barre syndrome rather than corticosteroid monotherapy.',takeaways:['IVIG and plasma exchange are accepted alternatives.','Immunotherapy does not replace respiratory or autonomic monitoring.'],references:[{label:'NINDS Guillain-Barre Syndrome (indexed source; direct page returned HTTP 403)',url:'https://www.ninds.nih.gov/health-information/disorders/guillain-barre-syndrome'}],evidenceNote,concerns:['Direct source access returned403; verify current treatment timing, IVIG contraindications and alternatives with a professional guideline.']},
{code:'op-s3-0318',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Presynaptic junction disease',subtopic:'Lambert-Eaton and malignancy',concept:'facilitating proximal weakness with autonomic symptoms should prompt malignancy evaluation',task:'diagnosis',setting:'ambulatory',service:'neuromuscular oncology',ageGroup:'older-adult',nutrition:false,difficulty:3,difficultyRationale:'Integrates examination facilitation and autonomic symptoms with cancer risk.',stem:'A 64-year-old man with a long smoking history has difficulty rising from a chair and persistent dry mouth. Knee reflexes are initially absent but become detectable after repeated quadriceps contraction. Sensation is normal. Nerve stimulation shows a marked increment in compound muscle action potential after exercise. Which associated condition should be actively investigated as part of his evaluation?',choices:[['Small-cell lung carcinoma','A presynaptic Lambert-Eaton pattern can be paraneoplastic, particularly with small-cell lung carcinoma, making malignancy evaluation important in this high-risk patient.'],['Thymoma as the characteristic association of every junction disorder','Thymoma is associated with myasthenia gravis; the facilitating reflexes, autonomic features, and incremental response here instead indicate a presynaptic syndrome.'],['Colon adenocarcinoma as the established explanation for this electrophysiology','Routine age-appropriate colorectal care remains relevant, but this specific neuromuscular syndrome and smoking history particularly raise concern for small-cell lung carcinoma.'],['Renal cell carcinoma as the characteristic paraneoplastic association','Renal tumors can produce paraneoplastic effects, but the specific presynaptic junction syndrome described is particularly associated with small-cell lung carcinoma rather than renal cell carcinoma.']],explanation:'Lambert-Eaton myasthenic syndrome results from impaired presynaptic transmitter release, often involving antibodies against voltage-gated calcium channels. Proximal weakness, autonomic symptoms, reduced reflexes, and facilitation after activity distinguish it from many postsynaptic or neuropathic disorders. The syndrome can precede discovery of an underlying malignancy, especially small-cell lung carcinoma. Investigation should follow a specialist-directed strategy and may need reassessment if an initial screen is negative. This question does not assume every affected patient has cancer; it identifies an association important enough to investigate.',objective:'Investigate small-cell lung carcinoma when a clinical and electrophysiological Lambert-Eaton pattern is identified.',takeaways:['Facilitation helps distinguish presynaptic junction disease.','Paraneoplastic symptoms can precede tumor detection.'],references:[{label:'NHS Lambert-Eaton myasthenic syndrome (indexed public health source)',url:'https://www.nhs.uk/conditions/lambert-eaton-myasthenic-syndrome/'}],evidenceNote,concerns:['Attach a current US professional guideline for malignancy-screening modality and follow-up interval.']},
{code:'op-s3-0319',category:'neurological',subject:'Pharmacology',system:'Nervous System',topic:'Myasthenia medication safety',subtopic:'Magnesium and transmitter release',concept:'magnesium can worsen neuromuscular weakness by reducing acetylcholine release',task:'foundational-science',setting:'hospital',service:'perioperative medicine',ageGroup:'adult',nutrition:false,difficulty:4,difficultyRationale:'Explains a drug effect in a patient with reduced junctional reserve.',stem:'A 55-year-old woman with established myasthenia gravis undergoes abdominal surgery. She had mild residual diplopia before surgery. After receiving intravenous magnesium for an electrolyte abnormality, she develops increased ptosis and weak cough. Oxygen and ventilatory assessment are initiated, and the team reviews potentially aggravating medications. Which effect of magnesium most directly contributes to worsening neuromuscular transmission in this susceptible patient?',choices:[['Reduction of presynaptic calcium-dependent acetylcholine release','Magnesium can impair calcium-dependent transmitter release, reducing the safety margin of neuromuscular transmission that is already compromised in myasthenia gravis.'],['Irreversible inhibition of acetylcholinesterase in the synaptic cleft','Magnesium is not an irreversible acetylcholinesterase inhibitor; the relevant aggravating effect is reduced transmitter release rather than prolonged acetylcholine persistence.'],['Irreversible binding of magnesium to postsynaptic acetylcholine receptors','The relevant effect is inhibition of calcium-dependent transmitter release, not an irreversible postsynaptic receptor-binding mechanism that permanently prevents acetylcholine action at the end plate.'],['Increased acetylcholine vesicle exocytosis at the motor terminal','Increased release would not explain the reduced junctional reserve described; magnesium instead can reduce calcium-dependent presynaptic release and worsen transmission in myasthenia.']],explanation:'Patients with myasthenia have reduced postsynaptic neuromuscular reserve. Magnesium can further weaken transmission by interfering with presynaptic calcium-dependent acetylcholine release, and clinically necessary replacement should therefore be individualized and monitored. New bulbar or respiratory weakness requires urgent assessment regardless of pulse oximetry, which can remain normal early in hypoventilation. Perioperative illness, anesthetic drugs, and other medications are additional possible contributors. The mechanistic question does not imply that every magnesium exposure is prohibited or that this temporal association alone proves causality.',objective:'Explain why magnesium can worsen weakness in patients with compromised neuromuscular junction reserve.',takeaways:['Review perioperative drugs when myasthenic weakness worsens.','Respiratory mechanics matter before oxygen saturation falls.'],references:[{label:'NINDS Myasthenia Gravis (direct page returned HTTP403; medication-specific confirmation required)',url:'https://www.ninds.nih.gov/health-information/disorders/myasthenia-gravis'}],evidenceNote,concerns:['Medication-specific risk and replacement strategy need authoritative current labeling or specialty guidance; broad overview is insufficient.']},
{code:'op-s3-0320',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'ALS nutritional planning',subtopic:'Progressive dysphagia and weight loss',concept:'ALS weight loss warrants early shared discussion of enteral support rather than waiting for a crisis',task:'management',setting:'ambulatory',service:'multidisciplinary ALS care',ageGroup:'adult',nutrition:true,difficulty:4,difficultyRationale:'Balances nutritional decline, procedural respiratory risk and patient preferences.',stem:'A 58-year-old woman with amyotrophic lateral sclerosis has lost 8% of her weight in three months. Meals now take ninety minutes, and she often stops because chewing is exhausting. Dietitian-guided supplements have not restored intake. Her respiratory function has begun to decline, but she communicates clearly and wants to continue disease-directed supportive care. What is the most appropriate next step in nutritional planning?',choices:[['Discuss gastrostomy benefits, burdens, timing, and alternatives now with the multidisciplinary team','Persistent nutritional decline despite oral strategies warrants timely shared planning, including assessment of respiratory and procedural risks before a feeding emergency develops.'],['Wait until she cannot communicate before discussing tube feeding','Delaying removes opportunities for informed participation and may increase procedural complexity as respiratory impairment and nutritional depletion progress.'],['Promise that gastrostomy will prevent all aspiration and reverse ALS','A feeding tube can support intake but does not cure motor neuron degeneration or eliminate aspiration from secretions and reflux.'],['Require tube placement regardless of her goals because weight has fallen','Nutritional risk supports a recommendation and informed discussion, not overriding a capable patient\'s values or treating the procedure as compulsory.']],explanation:'ALS-related bulbar dysfunction and meal fatigue can cause significant weight loss before complete loss of oral intake. When optimized oral strategies fail, a timely multidisciplinary discussion of enteral access helps align nutritional support with the patient\'s goals and assess procedural risk while respiratory function remains adequate enough for planning. Gastrostomy may supplement rather than automatically replace every oral pleasure, depending on swallowing safety. It does not abolish aspiration risk or reverse ALS. The central decision is early informed planning, not a rigid universal lung-function threshold or forced intervention.',objective:'Initiate shared enteral-feeding planning when ALS causes persistent weight loss despite optimized oral intake.',takeaways:['Plan before severe respiratory decline complicates procedures.','Tube feeding supports nutrition but does not eliminate aspiration or cure ALS.'],references:[{label:'AAN ALS quality measurement set (2012; indexed professional document)',url:'https://www.aan.com/siteassets/home-page/policy-and-guidelines/quality/quality-measures/12alsmeasurementset_pg.pdf'}],evidenceNote,concerns:['Historical AAN document requires current evidence review, especially procedural timing, respiratory support and survival claims.']},
{code:'op-s3-0321',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Stroke reperfusion pathways',subtopic:'Large-vessel occlusion with anticoagulant exposure',concept:'a contraindication to intravenous thrombolysis does not automatically exclude thrombectomy assessment',task:'management',setting:'emergency',service:'acute stroke',ageGroup:'older-adult',nutrition:false,difficulty:4,difficultyRationale:'Separates two reperfusion modalities when a drug exposure limits one.',stem:'A 76-year-old man arrives ninety minutes after sudden aphasia and right hemiplegia. CT excludes hemorrhage, and CT angiography shows a proximal left middle cerebral artery occlusion. Imaging shows a small established infarct. He took apixaban two hours earlier, and the local stroke protocol does not permit intravenous thrombolysis with his current anticoagulant exposure. What should the team do next?',choices:[['Arrange immediate endovascular thrombectomy assessment','A proximal occlusion with limited established injury warrants urgent thrombectomy evaluation; inability to receive intravenous thrombolysis does not automatically eliminate endovascular treatment.'],['Exclude every reperfusion procedure because apixaban was taken','Intravenous thrombolysis and mechanical thrombectomy have different selection issues; anticoagulant exposure alone should not end assessment for a treatable large-vessel occlusion.'],['Delay vascular treatment until an outpatient anticoagulation appointment','Large-vessel ischemic stroke is time-sensitive, and outpatient review cannot substitute for urgent assessment of reperfusion options and organized stroke care.'],['Give additional apixaban to dissolve the intracranial clot immediately','Apixaban is not an acute clot-dissolving therapy, and extra dosing does not replace mechanical reperfusion assessment while potentially increasing bleeding risk.']],explanation:'The stem establishes a disabling proximal arterial occlusion, early presentation, and a relatively small established infarct. These findings justify immediate evaluation by an endovascular stroke team. Intravenous thrombolysis eligibility and thrombectomy eligibility must be assessed separately; a contraindication to the former does not automatically prohibit the latter. Exact thrombectomy selection depends on imaging, vessel anatomy, baseline function, timing, and contemporary protocols. Additional anticoagulant dosing is not a substitute for reperfusion. Transfer logistics should be coordinated promptly if the presenting center lacks endovascular capability.',objective:'Continue urgent thrombectomy assessment for a suitable large-vessel stroke even when recent anticoagulation precludes intravenous thrombolysis under the applicable protocol.',takeaways:['Assess reperfusion modalities separately.','Do not let one exclusion end all acute stroke treatment pathways.'],references:[{label:'AHA/ASA Early Management of Acute Ischemic Stroke guideline resource; exact current selection guidance requires verification',url:'https://professional.heart.org/en/guidelines-and-statements'}],evidenceNote,concerns:['Broad guideline directory is insufficient final evidence; attach current acute-stroke guideline and anticoagulant-specific selection protocol.']},
{code:'op-s3-0322',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Cervical artery dissection',subtopic:'Painful partial Horner syndrome',concept:'new unilateral neck pain and partial Horner syndrome after neck strain suggests carotid dissection',task:'diagnosis',setting:'emergency',service:'vascular neurology',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Connects local sympathetic signs and pain before a completed stroke.',stem:'A 39-year-old man develops left-sided neck pain after a vigorous climbing session. The next morning his spouse notices a smaller left pupil and mild left eyelid droop. Sweating is preserved, extraocular movements are intact, and strength is normal. He has never had these findings before. Which diagnosis most urgently needs evaluation with appropriate head and neck vascular imaging?',choices:[['Internal carotid artery dissection','Painful partial Horner syndrome can result from injury to sympathetic fibers adjacent to the internal carotid artery and may precede ischemic neurological deficits.'],['Uncomplicated trapezius strain explaining the entire presentation','Muscle strain may cause neck pain but does not account for a new ipsilateral pupillary abnormality and ptosis requiring vascular evaluation.'],['Posterior communicating artery aneurysm causing a complete third nerve palsy','A compressive third nerve palsy more typically produces a dilated pupil and extraocular movement deficits, whereas this pupil is smaller and movements are intact.'],['Myasthenia gravis limited to the eyelid','Myasthenia can cause ptosis but does not typically produce a small pupil or a painful neck syndrome involving sympathetic pathway dysfunction.']],explanation:'The sympathetic fibers accompanying the internal carotid artery can be affected by dissection, producing ipsilateral ptosis and miosis, sometimes without facial anhidrosis. New unilateral neck or head pain makes the combination particularly concerning even before a focal ischemic deficit appears. Dedicated vascular imaging evaluates the arterial wall and lumen. The absence of weakness does not make this benign. Neck muscle pain and ocular disorders remain alternatives, but neither explains all findings as coherently. Management after confirmation depends on vascular anatomy, ischemic symptoms, and specialist review.',objective:'Recognize painful partial Horner syndrome as a possible carotid dissection requiring urgent vascular evaluation.',takeaways:['Dissection may present before stroke.','A small pupil helps distinguish Horner syndrome from a compressive third nerve palsy.'],references:[{label:'AHA Treatment and Outcomes of Cervical Artery Dissection in Adults (2024; indexed statement)',url:'https://www.ahajournals.org/doi/10.1161/STR.0000000000000457'}],evidenceNote,concerns:['Confirm imaging protocol and avoid implying that every isolated Horner syndrome has this cause.']},
{code:'op-s3-0323',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Spinal epidural infection',subtopic:'Afebrile high-risk presentation',concept:'progressive neurological deficit with back pain during bacteremia warrants urgent spinal MRI',task:'diagnosis',setting:'hospital',service:'infectious disease neurosurgery',ageGroup:'adult',nutrition:false,difficulty:4,difficultyRationale:'Avoids exclusion of an evolving spinal emergency because fever is absent after antibiotics.',stem:'A 57-year-old man receiving antibiotics for Staphylococcus aureus bacteremia develops severe focal thoracic back pain. He is now afebrile. Over six hours, his legs become weak and he develops urinary retention. Examination reveals reduced pin sensation below the umbilicus and brisk knee reflexes. Plain spinal radiographs show degenerative changes only. Which investigation is most appropriate urgently?',choices:[['Contrast-enhanced MRI of the relevant spine with urgent specialist involvement','Bacteremia, severe focal spinal pain, and an evolving cord syndrome raise concern for epidural infection with compression, which requires urgent MRI and specialist assessment.'],['Repeat plain radiographs in several weeks','Plain films do not adequately assess epidural soft tissue or cord compression, and waiting risks permanent injury during an evolving neurological emergency.'],['Outpatient nerve conduction testing of both legs','Peripheral testing cannot rapidly assess a thoracic compressive lesion, and a sensory level with urinary retention points toward a spinal cord process.'],['No further investigation because antibiotics eliminated the fever','Antibiotics can suppress fever without excluding a focal collection or mechanical compression; new neurological deficits require urgent reassessment despite apparent systemic improvement.']],explanation:'Spinal epidural infection can progress to cord compression, and the complete triad of fever, back pain, and neurological deficit is not required. Existing bacteremia and focal pain markedly increase concern; evolving weakness, a sensory level, and bladder dysfunction establish urgency. MRI evaluates the epidural space, vertebrae, and neural structures more effectively than plain radiographs. Antibiotic management and neurosurgical evaluation should proceed urgently according to stability and imaging findings. This is distinct from routine mechanical back pain and should not be deferred because fever has improved.',objective:'Obtain urgent spinal MRI for a progressive cord syndrome during bacteremia even when the patient is afebrile and radiographs are unrevealing.',takeaways:['Absence of the classic triad does not exclude spinal epidural infection.','Treat new cord dysfunction as time-sensitive.'],references:[{label:'IDSA Native Vertebral Osteomyelitis in Adults guideline (2015; specialty guidance requiring currency review)',url:'https://www.idsociety.org/practice-guideline/vertebral-osteomyelitis/'}],evidenceNote,concerns:['IDSA2015 guideline page accessed; confirm currency and scope because vertebral infection guidance does not cover every epidural abscess scenario.']},
{code:'op-s3-0324',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Spinal cord ischemia',subtopic:'Anterior cord vascular territory',concept:'anterior spinal ischemia can spare dorsal-column modalities after aortic surgery',task:'foundational-science',setting:'hospital',service:'vascular surgery neurology',ageGroup:'older-adult',nutrition:false,difficulty:3,difficultyRationale:'Uses selective sensory preservation to map postoperative spinal ischemia.',stem:'After repair of a thoracoabdominal aortic aneurysm, a 69-year-old man awakens with bilateral leg paralysis. Pain and temperature sensation are absent below the lower chest, but toe position and vibration remain detectable. His arms and cranial nerve examination are normal. Urgent imaging is arranged to evaluate a spinal complication. Which vascular territory best fits the selective neurological pattern?',choices:[['Anterior spinal artery territory','The anterior cord includes corticospinal and spinothalamic pathways, while dorsal-column function may be relatively preserved when posterior spinal circulation remains intact.'],['Posterior spinal artery territory alone','An isolated posterior territory lesion would primarily impair position and vibration sense, which are specifically preserved in this postoperative sensory pattern.'],['Bilateral posterior cerebral artery territories','Posterior cerebral ischemia affects cerebral structures, often including vision, and does not explain a thoracic sensory level with selective spinal modality loss.'],['A single common fibular nerve territory','One peripheral nerve lesion cannot explain bilateral paralysis, a truncal sensory level, and selective loss of pain and temperature across both legs.']],explanation:'Aortic procedures can compromise blood supply to the spinal cord. Weakness together with loss of pain and temperature below a level, while vibration and position sense remain relatively spared, localizes to the anterior cord. Corticospinal and spinothalamic pathways are affected, whereas dorsal columns are supplied mainly by posterior spinal circulation. Actual infarct patterns can be incomplete or mixed, so this physiological localization is not a substitute for urgent postoperative evaluation and treatment. Peripheral nerve injury and cerebral stroke do not match the sensory level or modality pattern.',objective:'Localize postoperative weakness with pain-temperature loss and preserved proprioception to the anterior spinal circulation.',takeaways:['Selective sensory modalities help localize cord injury.','Postaortic neurological deficits need urgent assessment.'],references:[{label:'NINDS Spinal Cord Infarction overview; direct page and detailed vascular claims require review',url:'https://www.ninds.nih.gov/health-information/disorders/spinal-cord-infarction'}],evidenceNote,concerns:['Direct NINDS page access returned403; verify spinal vascular pattern and current postoperative rescue protocols separately.']},
{code:'op-s3-0325',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Cerebellar hemorrhage escalation',subtopic:'Obstructive hydrocephalus',concept:'declining consciousness with posterior fossa hemorrhage and ventricular obstruction requires urgent neurosurgical evaluation',task:'management',setting:'emergency',service:'neurocritical care neurosurgery',ageGroup:'older-adult',nutrition:false,difficulty:4,difficultyRationale:'Integrates posterior-fossa anatomy and deterioration rather than treating hemorrhage size alone.',stem:'A 67-year-old woman presents with abrupt vomiting, severe occipital pain, and inability to stand. CT reveals a cerebellar hemorrhage compressing the fourth ventricle with enlarging lateral ventricles. She was independently alert before symptom onset. During monitoring she becomes progressively somnolent. Blood pressure treatment and airway preparation are underway. Which additional action has the highest priority?',choices:[['Obtain immediate neurosurgical evaluation for decompression and management of hydrocephalus','Posterior fossa hemorrhage with obstructed cerebrospinal fluid flow and declining consciousness can rapidly cause fatal compression and requires urgent neurosurgical assessment.'],['Arrange routine outpatient balance rehabilitation before consultation','Rehabilitation is relevant after stabilization but cannot treat acute posterior fossa mass effect or an obstructed ventricular system causing deteriorating consciousness.'],['Administer an oral vestibular suppressant and observe overnight','Symptom suppression does not relieve mechanical compression, and oral treatment is unsafe in a progressively somnolent patient with an evolving neurological emergency.'],['Perform lumbar puncture to lower pressure before specialist review','A posterior fossa mass with hydrocephalus makes lumbar cerebrospinal fluid removal hazardous because it can worsen pressure gradients and precipitate herniation.']],explanation:'The posterior fossa has limited space, and cerebellar hemorrhage can compress the brainstem or obstruct the fourth ventricle. Deteriorating consciousness and hydrocephalus are urgent warning signs requiring neurosurgical evaluation rather than symptom treatment alone. Airway and physiological stabilization continue concurrently. Definitive decisions may involve hematoma evacuation, decompression, and cerebrospinal fluid diversion under specialist judgment. Lumbar puncture does not safely address an obstructed cranial compartment. The question intentionally emphasizes the combination of deterioration and obstructive anatomy rather than asserting a universal size-only surgical rule.',objective:'Escalate cerebellar hemorrhage with obstructive hydrocephalus and declining consciousness to urgent neurosurgical care.',takeaways:['Posterior fossa lesions can deteriorate quickly.','Do not perform lumbar puncture to treat mass-related obstructive hydrocephalus.'],references:[{label:'AHA/ASA Spontaneous Intracerebral Hemorrhage guideline (2022; exact surgical recommendations need verification)',url:'https://www.ahajournals.org/doi/10.1161/STR.0000000000000407'}],evidenceNote,concerns:['Direct AHA guideline access returned403; surgical selection and ventricular-drain strategy require specialist claim review.']},
{code:'op-s3-0326',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Delayed ischemia after subarachnoid hemorrhage',subtopic:'New focal deficit after initial stabilization',concept:'new deficit days after aneurysm treatment suggests delayed cerebral ischemia',task:'diagnosis',setting:'hospital',service:'neurocritical care',ageGroup:'adult',nutrition:false,difficulty:4,difficultyRationale:'Uses interval, imaging and normal metabolic values to evaluate a secondary deterioration.',stem:'Seven days after aneurysmal subarachnoid hemorrhage treated by coiling, a 48-year-old woman develops new expressive language difficulty and right arm drift. Earlier examinations had been stable, and she has received no new sedatives. Glucose, sodium, temperature, and oxygenation are normal. Repeat CT shows no new blood and no hydrocephalus. Which complication is the leading concern requiring urgent vascular and perfusion assessment?',choices:[['Delayed cerebral ischemia associated with posthemorrhagic vascular dysfunction','A new focal deficit several days after subarachnoid hemorrhage without rebleeding or hydrocephalus raises concern for delayed ischemia, often associated with vasospasm.'],['A remote stable peripheral neuropathy','A peripheral neuropathy does not explain newly impaired language together with unilateral arm drift emerging during the recognized delayed complication period.'],['Normal recovery from coiling requiring no reassessment','A new focal neurological change after previous stability is not an expected harmless milestone and requires urgent evaluation for treatable intracranial complications.'],['Hyponatremic encephalopathy established by the time interval alone','The sodium is normal, and a focal language-motor syndrome should not be attributed to a metabolic complication without supporting laboratory evidence.']],explanation:'Delayed cerebral ischemia is a major complication after aneurysmal subarachnoid hemorrhage and can appear after the initial bleeding has been secured. The deficit may reflect vascular narrowing and additional microcirculatory mechanisms; angiographic vasospasm and clinical ischemia are related but not identical concepts. New focal symptoms warrant urgent reassessment while excluding rebleeding, hydrocephalus, seizures, metabolic derangements, and infection. Normal CT for new hemorrhage does not exclude ischemia. Specialized monitoring and management depend on neurological examination, hemodynamics, and vascular or perfusion findings.',objective:'Suspect delayed cerebral ischemia when a new focal deficit develops days after stabilized aneurysmal subarachnoid hemorrhage.',takeaways:['Securing the aneurysm does not eliminate delayed complications.','Angiographic vasospasm and clinical ischemia are not interchangeable.'],references:[{label:'AHA/ASA Aneurysmal Subarachnoid Hemorrhage guideline (2023; exact claims require review)',url:'https://www.ahajournals.org/doi/10.1161/STR.0000000000000436'}],evidenceNote,concerns:['Direct AHA guideline access returned403; verify bibliographic identity and current terminology; no specific hemodynamic intervention is prescribed.']},
{code:'op-s3-0327',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Painful third nerve palsy',subtopic:'Compressive aneurysm assessment',concept:'acute pupil-involving third nerve palsy requires urgent intracranial vascular evaluation',task:'management',setting:'emergency',service:'neuro-ophthalmology emergency',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Distinguishes a compressive warning pattern from routine microvascular observation.',stem:'A 54-year-old woman develops sudden left retro-orbital pain and double vision. The left eyelid is drooped, the eye rests down and outward, and the left pupil is larger and reacts sluggishly to light. She has diabetes, but her previous eye examinations were normal. Strength and speech are intact. What is the most appropriate next action?',choices:[['Arrange urgent intracranial vascular imaging and specialist evaluation','A new painful pupil-involving third nerve palsy raises concern for an aneurysmal compressive lesion and requires urgent evaluation despite coexisting diabetes.'],['Attribute the deficit to diabetes and reassess in three months','Diabetes increases microvascular palsy risk but does not safely explain away an acute painful pupil-involving pattern that may signal a compressive aneurysm.'],['Treat dry eye alone and continue normal activity','Ocular surface irritation does not produce third-nerve muscle weakness with ptosis and a dilated poorly reactive pupil in this neurological pattern.'],['Schedule nonurgent orbital imaging six weeks later','An orbital study might address selected causes of ocular dysfunction, but delayed local imaging does not adequately evaluate the urgent possibility of an intracranial compressive aneurysm.']],explanation:'The third nerve controls eyelid elevation, most extraocular movements, and parasympathetic pupillary constriction. Compression, particularly from an adjacent aneurysm, can affect the superficial pupillary fibers and produce a painful dilated-pupil palsy. Diabetes does not remove the need for urgent imaging in this presentation. Although pupil findings alone cannot perfectly distinguish all etiologies, the clinical combination warrants emergency vascular assessment. The intact limb examination is reassuring only about those functions; it does not exclude a local intracranial lesion with risk of rupture.',objective:'Urgently investigate a new painful pupil-involving third nerve palsy for an intracranial compressive vascular lesion.',takeaways:['A focal cranial neuropathy can be a vascular emergency.','Diabetes is a risk factor, not a reason to bypass evaluation.'],references:[{label:'NINDS Cerebral Aneurysms overview; exact cranial-nerve triage claims need verification',url:'https://www.ninds.nih.gov/health-information/disorders/cerebral-aneurysms'}],evidenceNote,concerns:['Direct NINDS page access returned403; verify imaging selection and contemporary evaluation of all acquired third nerve palsies.']},
{code:'op-s3-0328',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Facial palsy corneal protection',subtopic:'Incomplete eye closure',concept:'exposure prevention is immediately necessary when peripheral facial palsy prevents eyelid closure',task:'management',setting:'ambulatory',service:'primary care neurology',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Prioritizes a preventable complication while etiologic treatment is arranged.',stem:'A 33-year-old man is diagnosed with an acute isolated peripheral facial nerve palsy after appropriate examination. He cannot wrinkle his right forehead or fully close the right eye. There is no limb weakness, vesicular rash, hearing loss, or corneal injury yet. Etiology-directed medication has been discussed. Which additional measure is important immediately to prevent a foreseeable complication?',choices:[['Institute eye lubrication and a safe eyelid-protection plan','Incomplete closure exposes the cornea to drying and injury, so lubrication and appropriate protection are needed while facial motor function recovers.'],['Wait for corneal pain before offering any eye care','Exposure injury can develop before severe symptoms prompt return, and prevention is appropriate once impaired eyelid closure is established on examination.'],['Use topical anesthetic eye drops repeatedly at home','Repeated anesthetic use can harm the cornea and mask injury; it does not provide the protective lubrication and closure support needed.'],['Prescribe only facial strengthening exercises without ocular precautions','Exercises do not immediately restore reliable eyelid closure, so relying on them alone leaves the exposed cornea vulnerable during the recovery period.']],explanation:'The facial nerve supplies the orbicularis oculi, and weakness can prevent complete eyelid closure. The resulting exposure risks corneal drying, abrasion, and more serious injury. Lubricating drops, appropriate nighttime ointment or closure protection, education, and reassessment are practical preventive measures, with eye specialist input when indicated. The exact plan should avoid pressure or taping techniques that injure the eye. This question does not assume every facial palsy is idiopathic; red flags and the cause still require assessment independently of immediate corneal protection.',objective:'Protect the cornea immediately when facial nerve palsy prevents full eye closure.',takeaways:['Treat foreseeable complications while evaluating the cause.','Incomplete closure needs a concrete eye-protection plan.'],references:[{label:'AAO-HNSF Clinical Practice Guideline: Bell palsy; source access and currency review required',url:'https://www.entnet.org/quality-practice/quality-products/clinical-practice-guidelines/bells-palsy/'}],evidenceNote,concerns:['AAO-HNS guideline page accessed and identifies2013 publication; verify currency and exact eye-protection instructions.']},
{code:'op-s3-0329',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Otologic facial neuropathy',subtopic:'Ramsay Hunt syndrome',concept:'facial weakness with auricular vesicles and otalgia suggests zoster oticus',task:'diagnosis',setting:'ambulatory',service:'neurology otolaryngology',ageGroup:'older-adult',nutrition:false,difficulty:3,difficultyRationale:'Uses associated ear findings to avoid labeling all peripheral facial palsy idiopathic.',stem:'A 63-year-old woman presents with severe right ear pain followed by weakness of the entire right side of her face. She also notices reduced hearing and spinning dizziness. Examination shows grouped vesicles within the external auditory canal and on the right auricle. There is no limb weakness or language disturbance. Which diagnosis best accounts for the full pattern?',choices:[['Ramsay Hunt syndrome due to varicella-zoster reactivation','Painful auricular vesicles with ipsilateral peripheral facial paralysis and possible auditory or vestibular involvement form a characteristic zoster-associated cranial neuropathy syndrome.'],['Idiopathic Bell palsy with no need to consider another cause','Although both cause peripheral facial weakness, the painful vesicular eruption and auditory or vestibular features point toward a specific infectious cause rather than idiopathic palsy.'],['Unilateral trigeminal neuralgia','Trigeminal neuralgia produces brief triggered facial pain, not a vesicular ear eruption with weakness of both upper and lower facial muscles.'],['Isolated eustachian tube dysfunction','Middle-ear pressure dysfunction can affect hearing but does not explain grouped vesicles, severe neuropathic pain, and a peripheral facial motor deficit.']],explanation:'Ramsay Hunt syndrome refers to zoster-associated facial paralysis, often accompanied by painful vesicles in the external ear or oral region. Nearby cranial nerve involvement can produce hearing or balance symptoms. The clinical combination distinguishes it from idiopathic facial palsy and should prompt timely specialist-guided treatment and corneal protection. Vesicles may not always be obvious early, so their absence does not universally exclude zoster. In this vignette they provide a decisive etiologic clue. New focal neurological signs elsewhere would require additional evaluation rather than attribution to this diagnosis.',objective:'Distinguish zoster-associated facial palsy from idiopathic palsy using otalgia, auricular vesicles, and auditory or vestibular involvement.',takeaways:['Examine the ear canal in peripheral facial palsy.','Protect the cornea regardless of palsy etiology.'],references:[{label:'NINDS Ramsay Hunt Syndrome overview; direct source access pending',url:'https://www.ninds.nih.gov/health-information/disorders/ramsay-hunt-syndrome'}],evidenceNote,concerns:['Direct NINDS page access returned403; reviewer must validate the reference, treatment evidence and diagnostic distinctions.']},
{code:'op-s3-0330',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Cluster headache rescue',subtopic:'Rapid nonoral abortive therapy',concept:'short severe autonomic headache attacks require a rapid rescue route',task:'management',setting:'emergency',service:'headache medicine',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Matches treatment speed and route to a brief disabling attack pattern.',stem:'A 35-year-old man with an established diagnosis of episodic cluster headache presents during a typical attack. He paces the room with severe unilateral orbital pain, tearing, and nasal congestion. The attack began fifteen minutes ago; prior attacks last about forty-five minutes. Neurological examination is unchanged, and there are no new red flags or pulmonary contraindications. Which treatment is appropriate for rapid relief?',choices:[['High-flow oxygen through a nonrebreather mask','High-flow oxygen is an accepted rapid abortive treatment for cluster attacks and avoids the delay associated with absorption of oral preventive medication.'],['Oral verapamil as the sole immediate rescue treatment','Verapamil is used as a preventive strategy with appropriate monitoring and does not provide the rapid attack termination sought in this presentation.'],['An oral opioid as the preferred first-line cluster treatment','Opioids are not preferred targeted abortive therapy for cluster headache and carry harms without reliably matching the short, rapidly escalating attack pattern.'],['An oral antidepressant with reassessment in six weeks','A delayed-onset preventive medication does not address the current severe brief attack and cannot substitute for an appropriate rapid rescue intervention.']],explanation:'Cluster headache attacks are severe, relatively brief, and often accompanied by ipsilateral autonomic symptoms and restlessness. Acute treatment therefore requires a rapid strategy, such as appropriately delivered high-flow oxygen or a suitable nonoral triptan when not contraindicated. Preventive treatment is a separate decision and may include monitored verapamil. The stem establishes an unchanged diagnosed pattern, so it does not dismiss new secondary headache warning signs. Oxygen delivery method and safety must follow current guidance; low-flow nasal oxygen should not be treated as automatically equivalent.',objective:'Choose a rapid abortive route such as high-flow nonrebreather oxygen for a typical established cluster headache attack.',takeaways:['Acute rescue and prevention have different roles.','Delivery route matters in short severe attacks.'],references:[{label:'NINDS Headache booklet (indexed government publication)',url:'https://www.ninds.nih.gov/sites/default/files/2025-07/NINDS_Headache_Booklet_Digital_508c%20%281%29.pdf'}],evidenceNote,concerns:['Verify current cluster-specific flow, delivery and safety protocol; broad booklet does not establish all implementation details.']},
{code:'op-s3-0331',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Intracranial hypertension evaluation',subtopic:'Papilledema with preserved consciousness',concept:'papilledema and transient visual obscurations require exclusion of secondary raised-pressure causes',task:'diagnosis',setting:'ambulatory',service:'neuro-ophthalmology',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Requires exclusion of secondary causes before assigning an idiopathic label.',stem:'A 27-year-old woman has daily headaches, pulse-synchronous tinnitus, and seconds-long visual dimming when bending forward. Examination shows bilateral optic disc swelling but normal strength and alertness. Visual acuity is preserved between episodes. She recently began a tetracycline antibiotic for acne. Her clinician suspects raised intracranial pressure. Which diagnostic approach is most appropriate before calling this an idiopathic disorder?',choices:[['Obtain appropriate brain and venous imaging and review pressure-raising medications','Imaging excludes structural and venous causes, while the new medication may identify a secondary cause; an idiopathic label requires appropriate exclusion of alternatives.'],['Diagnose migraine solely because the limb examination is normal','A normal limb examination does not explain objective papilledema, and headache with transient visual obscurations requires investigation of raised intracranial pressure.'],['Assume medication exposure proves the cause without imaging','The drug history is important but does not safely exclude a mass, venous thrombosis, or another cause of papilledema and visual risk.'],['Perform no evaluation unless complete blindness occurs','Papilledema can threaten vision before profound loss develops, so deferring investigation until blindness would miss an opportunity to prevent permanent injury.']],explanation:'Papilledema, pulsatile tinnitus, and transient visual obscurations suggest raised intracranial pressure. Idiopathic intracranial hypertension is a diagnosis requiring an appropriate evaluation that excludes mass lesions, venous thrombosis, medication effects, and other secondary causes. Brain and venous imaging generally precede lumbar puncture when clinically indicated. A tetracycline exposure is relevant but does not independently establish causality. Ophthalmic assessment of acuity, fields, and optic nerve status helps quantify urgency. Preserved consciousness and normal limb strength do not remove the risk of progressive visual injury.',objective:'Exclude secondary causes and review medications before labeling a papilledema-associated pressure syndrome idiopathic.',takeaways:['Papilledema needs evaluation even with a normal limb examination.','Medication associations do not replace exclusion of structural and venous causes.'],references:[{label:'NIH National Eye Institute: Idiopathic Intracranial Hypertension (indexed source)',url:'https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases/idiopathic-intracranial-hypertension'}],evidenceNote,concerns:['Confirm contemporary imaging and lumbar-puncture sequence and the exact medication association using specialty guidance.']},
{code:'op-s3-0332',category:'neurological',subject:'Medicine',system:'Nervous System',topic:'Giant cell arteritis visual risk',subtopic:'Treatment before confirmation',concept:'cranial ischemic symptoms in suspected GCA require immediate glucocorticoids rather than biopsy delay',task:'management',setting:'emergency',service:'rheumatology neuro-ophthalmology',ageGroup:'older-adult',nutrition:false,difficulty:3,difficultyRationale:'Balances urgent prevention of visual injury against the need for diagnostic confirmation.',stem:'A 75-year-old woman develops a new temporal headache, scalp tenderness, and jaw fatigue when chewing. Earlier today the vision in her right eye dimmed for several minutes. ESR and C-reactive protein are elevated. There is no fever or meningismus. A temporal artery biopsy can be arranged in four days. What is the most appropriate action now?',choices:[['Begin urgent glucocorticoid treatment and arrange specialist confirmation','The clinical picture includes threatened ocular ischemia, so treatment should begin urgently while diagnostic confirmation and ophthalmic assessment are coordinated.'],['Withhold all treatment until the biopsy report is available','Waiting several days in a patient with transient visual loss risks irreversible ischemic injury and is not justified solely to preserve diagnostic testing.'],['Treat with a triptan and assume a first migraine at this age','New headache with jaw claudication and visual ischemic symptoms in an older adult requires evaluation for arteritis rather than uncritical migraine treatment.'],['Use antibiotics alone because inflammatory markers are elevated','Elevated inflammatory markers are nonspecific; the cranial ischemic pattern supports suspected arteritis, and antibiotics alone do not address this mechanism.']],explanation:'New headache, scalp tenderness, jaw claudication, and transient visual loss in an older adult strongly suggest giant cell arteritis with threatened ocular ischemia. Glucocorticoids should be started urgently rather than waiting for biopsy, with immediate specialist input to determine the appropriate regimen and visual assessment. Biopsy or imaging remains important for confirmation and subsequent management. The case does not make inflammatory markers alone diagnostic; the clinical ischemic features drive urgency. Prompt treatment aims to reduce further visual injury, not guarantee reversal of damage already sustained.',objective:'Start urgent glucocorticoids for suspected giant cell arteritis with visual ischemic symptoms while arranging confirmation.',takeaways:['Threatened vision changes the urgency.','Diagnostic confirmation should proceed without delaying protective treatment.'],references:[{label:'ACR/Vasculitis Foundation Giant Cell Arteritis guideline (2021; indexed professional guideline)',url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC12344528/'}],evidenceNote,concerns:['Route and regimen for threatened vision, biopsy timing, and guideline currency require direct specialist verification.']},
{code:'op-s3-0333',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Migraine aura chronology',subtopic:'Gradual positive symptom spread',concept:'recurrent spreading positive symptoms with sequential sensory involvement favor migraine aura',task:'diagnosis',setting:'ambulatory',service:'headache medicine',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Uses symptom evolution and recurrence rather than headache presence alone.',stem:'A 30-year-old woman reports six similar episodes over two years. A small shimmering arc enlarges across her vision over ten minutes, followed by tingling that gradually spreads from one hand toward her cheek. Each episode resolves completely within forty minutes and is followed by unilateral throbbing headache and photophobia. Examination between episodes is normal. Which diagnosis best fits this established recurrent pattern?',choices:[['Migraine with visual and sensory aura','Gradual spread of positive symptoms, sequential modalities, complete recovery, and a reproducible associated headache favor aura over a sudden maximal negative deficit.'],['Repeated identical embolic strokes without permanent injury','Embolic strokes generally produce abrupt deficits, and this slowly spreading positive sequence with full recovery is more characteristic of aura than repeated infarction.'],['A single persistent optic nerve lesion','An optic nerve lesion does not explain repeated fully resolving expanding visual phenomena followed by spreading hand-face tingling and a stereotyped headache.'],['Isolated peripheral median neuropathy','A median neuropathy cannot account for visual symptoms or facial sensory spread and would not produce this repeated sequential cortical pattern.']],explanation:'The temporal evolution is central: positive visual symptoms enlarge gradually, sensory symptoms spread over minutes, and all manifestations resolve before the usual headache. This supports migraine with aura in an established recurrent pattern. Transient ischemia more often begins abruptly with loss of function, although clinical overlap exists and no single feature rules out vascular disease. A first, changed, prolonged, or otherwise atypical episode warrants reassessment. The stem deliberately supplies repeated unchanged episodes and a normal interval examination; it does not authorize dismissing an acute new focal deficit as migraine.',objective:'Use gradual positive symptom spread and sequential fully reversible modalities to recognize a recurrent migraine aura pattern.',takeaways:['Chronology is more informative than headache alone.','New or changed focal symptoms still require assessment.'],references:migraine,evidenceNote,concerns:['Prevention guideline is not a diagnostic-classification source; attach current headache diagnostic criteria before approval.']},
{code:'op-s3-0334',category:'neurological',subject:'Pharmacology',system:'Nervous System',topic:'Topiramate metabolic effects',subtopic:'Carbonic anhydrase inhibition',concept:'topiramate can promote bicarbonate loss and calcium phosphate stones',task:'foundational-science',setting:'ambulatory',service:'headache pharmacology',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Connects a preventive drug with renal chemistry and a new adverse effect.',stem:'A 41-year-old woman taking topiramate for migraine prevention develops flank pain and passes a calcium phosphate stone. Serum bicarbonate is 18 mEq/L, chloride is elevated, and the anion gap is normal. She has no diarrhea and takes no other relevant medication. Which pharmacological effect most plausibly contributes to the combination of acidosis and stone formation?',choices:[['Renal carbonic anhydrase inhibition','Topiramate can impair renal bicarbonate handling through carbonic anhydrase inhibition and alter urinary chemistry in ways that favor calcium phosphate stones.'],['Complete blockade of renal aldosterone receptors','This is not topiramate\'s relevant mechanism, and the described drug-associated urinary changes are more consistent with carbonic anhydrase inhibition.'],['Direct destruction of all glomerular filtration units','Widespread irreversible glomerular destruction is not required to explain a normal-gap acidosis and new stone associated with topiramate exposure.'],['Selective inhibition of intestinal pancreatic lipase','A lipase-inhibiting drug produces a different gastrointestinal adverse-effect pattern and does not explain topiramate-associated renal bicarbonate loss and alkaline stone risk.']],explanation:'Topiramate inhibits carbonic anhydrase and can cause a hyperchloremic metabolic acidosis through altered renal bicarbonate handling. Associated urinary changes, including reduced citrate and increased pH, can favor calcium phosphate stones. These effects are clinically relevant when selecting migraine prevention and monitoring tolerability. The drug should be reviewed with the prescriber; treatment decisions depend on severity, alternatives, and any seizure indication, rather than abrupt unplanned withdrawal. The mechanism distinguishes a medication effect from diarrhea-related bicarbonate loss or a high-anion-gap process.',objective:'Connect topiramate-associated normal-anion-gap acidosis and calcium phosphate stones to renal carbonic anhydrase inhibition.',takeaways:['Migraine prevention requires adverse-effect review.','Stone composition and acid-base pattern can reveal a drug mechanism.'],references:[{label:'DailyMed topiramate official labeling search; exact product warning requires confirmation',url:'https://dailymed.nlm.nih.gov/dailymed/search.cfm?query=topiramate'}],evidenceNote,concerns:['Replace search portal with a fixed current official label and verify urinary-chemistry claims.']},
{code:'op-s3-0335',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Episodic audiovestibular syndrome',subtopic:'Meniere pattern',concept:'recurrent vertigo with fluctuating unilateral hearing symptoms suggests Meniere disease',task:'diagnosis',setting:'ambulatory',service:'neuro-otology',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Distinguishes episodic inner-ear disease from positional and central syndromes using hearing history.',stem:'A 49-year-old man has four episodes of spinning vertigo lasting one to three hours over the past six months. During attacks his left ear feels full and rings, and hearing becomes muffled. Hearing partially improves afterward. He has no diplopia, limb weakness, or headache. Audiometry shows left low-frequency sensorineural hearing loss. Which diagnosis best accounts for this pattern?',choices:[['Meniere disease','Recurrent spontaneous vertigo lasting hours with fluctuating unilateral auditory symptoms and documented low-frequency sensorineural hearing loss supports a Meniere pattern.'],['Benign paroxysmal positional vertigo','BPPV typically causes brief position-triggered episodes and does not explain fluctuating unilateral sensorineural hearing loss, tinnitus, and aural fullness over hours.'],['Vestibular neuritis as a single continuous attack','Vestibular neuritis usually causes a more sustained acute vestibular illness without this repeated pattern of fluctuating cochlear symptoms and audiometric hearing loss.'],['An isolated medication-induced distal polyneuropathy','Peripheral nerve dysfunction in the limbs does not account for episodic spinning sensations coupled to unilateral cochlear symptoms and measurable inner-ear hearing loss.']],explanation:'The combination of recurrent spontaneous vertigo, fluctuating hearing, tinnitus, aural fullness, and audiometric sensorineural loss suggests Meniere disease. Episode duration and accompanying cochlear findings help distinguish it from brief positional vertigo and an isolated prolonged vestibular neuritis syndrome. Diagnosis still requires exclusion of alternatives, including retrocochlear pathology when indicated. New focal neurological deficits, inability to walk out of proportion to vertigo, or a changed continuous syndrome would trigger reassessment for a central cause. The question tests pattern integration, not a universal dietary or medication prescription.',objective:'Recognize a Meniere pattern from recurrent hours-long vertigo with fluctuating unilateral cochlear symptoms and audiometric loss.',takeaways:['Ask about hearing during vertigo episodes.','Duration and triggers help distinguish vestibular syndromes.'],references:[{label:'NIDCD Meniere disease overview (page accessed 2026-10-30)',url:'https://www.nidcd.nih.gov/health/menieres-disease'}],evidenceNote,concerns:['Source page accessed, but exact diagnostic duration criteria and exclusion strategy still require review; no dietary sodium target is asserted.']},
{code:'op-s3-0336',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Sudden sensorineural hearing loss',subtopic:'Urgent referral despite normal otoscopy',concept:'sudden unilateral sensorineural hearing loss is time-sensitive even with a normal ear canal',task:'management',setting:'ambulatory',service:'primary care neuro-otology',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Separates an apparently minor ear complaint from time-sensitive inner-ear loss.',stem:'A 56-year-old woman awakens with markedly reduced hearing in her right ear and new tinnitus. There is no ear pain, recent loud-noise exposure, or focal neurological deficit. Otoscopy shows no wax or middle-ear fluid. Bedside testing supports a right sensorineural rather than conductive deficit. Symptoms began eighteen hours ago. What is the most appropriate next step?',choices:[['Arrange urgent audiometric and otolaryngology evaluation for sudden sensorineural hearing loss','A rapid unilateral sensorineural change is time-sensitive and warrants urgent confirmation and treatment consideration even when the canal and tympanic membrane look normal.'],['Wait six weeks because normal otoscopy excludes a serious cause','Normal otoscopy does not assess cochlear or auditory nerve function, and delay can miss a treatment opportunity in sudden sensorineural hearing loss.'],['Treat cerumen impaction despite an empty ear canal','There is no obstructing wax, and the bedside pattern is sensorineural; empiric wax treatment does not address the demonstrated inner-ear deficit.'],['Give routine antihistamines as definitive treatment without follow-up','Antihistamines do not establish the diagnosis or replace urgent hearing assessment and specialist consideration of time-sensitive treatment for this presentation.']],explanation:'Sudden sensorineural hearing loss may present as a blocked or muffled ear despite a normal external and middle-ear examination. The distinction from a conductive cause is essential because prompt audiometry and otolaryngology evaluation can guide time-sensitive treatment and investigation for retrocochlear disease. A normal limb examination does not make the hearing loss trivial; accompanying central signs would additionally warrant emergency stroke evaluation. Treatment choice and steroid route require individualized specialist discussion rather than a universal unsupervised prescription. The key action is urgent escalation rather than watchful waiting.',objective:'Urgently refer suspected sudden sensorineural hearing loss despite normal otoscopy.',takeaways:['Normal otoscopy does not establish normal inner-ear function.','Distinguish conductive from sensorineural loss promptly.'],references:[{label:'NIDCD Sudden Sensorineural Hearing Loss (indexed government source)',url:'https://www.nidcd.nih.gov/health/sudden-deafness'}],evidenceNote,concerns:['Confirm current specialty guidance on timing, steroid options, contraindications and retrocochlear assessment.']},
{code:'op-s3-0337',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Inflammatory spinal cord syndrome',subtopic:'Transverse myelitis after exclusion of compression',concept:'noncompressive intramedullary inflammation with a sensory level supports transverse myelitis',task:'diagnosis',setting:'hospital',service:'neuroimmunology',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Integrates localization, imaging and inflammatory CSF after urgent structural exclusion.',stem:'A 26-year-old man develops bilateral leg weakness and urinary urgency over three days. There is a bandlike sensory level across his chest and brisk knee reflexes. Urgent MRI excludes an epidural collection or mass but shows an enhancing intramedullary thoracic lesion. Cerebrospinal fluid has mild lymphocytic pleocytosis. Which syndrome best describes the neurological process requiring further etiologic evaluation?',choices:[['Acute transverse myelitis','A bilateral spinal cord syndrome with a sensory level, autonomic symptoms, noncompressive intramedullary abnormality, and inflammatory evidence supports an acute inflammatory myelitis syndrome.'],['Isolated distal diabetic polyneuropathy','A distal peripheral neuropathy does not produce a thoracic sensory level, upper motor signs, or an enhancing intramedullary lesion with inflammatory CSF.'],['An uncomplicated functional bladder disorder','The bladder symptom occurs with objective cord findings and imaging abnormalities, so an isolated functional urinary diagnosis cannot explain the presentation.'],['Lumbar disc compression established despite normal structural imaging','The lesion is intramedullary and thoracic, and imaging excluded compression; a lumbar disc explanation does not fit the demonstrated localization or inflammation.']],explanation:'Transverse myelitis describes an inflammatory spinal cord syndrome and is not itself a complete etiologic diagnosis. A sensory level and bilateral motor and autonomic dysfunction localize the process to the cord. MRI first helps exclude urgent compression, then identifies intramedullary disease; CSF can provide supporting inflammatory evidence. Further evaluation considers demyelinating, infectious, systemic autoimmune, and other causes, including antibody-associated disorders when appropriate. The distinction matters because treatment depends on the underlying process and should not be inferred solely from the descriptive syndrome label.',objective:'Identify a noncompressive inflammatory spinal cord syndrome while recognizing that transverse myelitis still requires etiologic evaluation.',takeaways:['Exclude compression urgently.','A syndrome label does not complete the cause-specific evaluation.'],references:myelitis,evidenceNote,concerns:['Exact MRI/CSF criteria and antibody-testing indications require current neuroimmunology review.']},
{code:'op-s3-0338',category:'neurological',subject:'Physiology',system:'Nervous System',topic:'Afferent pupillary defect',subtopic:'Optic neuritis physiology',concept:'unilateral optic nerve injury reduces bilateral pupillary constriction when light enters the affected eye',task:'foundational-science',setting:'ambulatory',service:'neuro-ophthalmology',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Uses a dynamic bilateral response to distinguish afferent from efferent dysfunction.',stem:'A 28-year-old woman has pain with left eye movement, reduced color saturation, and decreased left visual acuity. Both pupils are equal in size. When light is swung from the right eye to the left, both pupils dilate relative to their previous constricted state. Each pupil can constrict normally when the right eye is illuminated. Which abnormality explains the examination?',choices:[['Reduced afferent input from the left optic nerve','The affected eye provides a weaker light signal to the pretectal pathway, so both pupils receive less constricting drive when illumination shifts leftward.'],['Isolated left oculomotor parasympathetic failure','An efferent defect would impair left pupil constriction regardless of which eye is illuminated, contrary to its normal response with right-eye illumination.'],['Complete right optic nerve interruption','Right-eye illumination produces normal bilateral constriction, showing that its afferent input is preserved rather than completely interrupted in this examination.'],['Bilateral irreversible iris sphincter paralysis','Both pupils constrict with right-eye illumination, demonstrating functioning sphincters and excluding bilateral fixed efferent paralysis as the explanation for the asymmetry.']],explanation:'A relative afferent pupillary defect reflects unequal sensory input rather than unequal pupil size. With unilateral optic nerve injury, light in the affected eye produces less bilateral parasympathetic output than light in the healthy eye. Consequently, both pupils appear to dilate when the flashlight swings toward the affected eye. Preserved consensual constriction confirms that the efferent pathways and iris muscles can function. The painful visual loss and color desaturation support optic neuritis, although an afferent defect can also arise from severe asymmetric retinal disease and requires clinical evaluation.',objective:'Explain a relative afferent pupillary defect using preserved bilateral efferent function and reduced unilateral optic nerve input.',takeaways:['Equal pupil size does not exclude an afferent defect.','Compare responses to illumination of each eye.'],references:[{label:'AAO Facing Pupil Abnormalities Without Fear (indexed professional education)',url:'https://www.aao.org/young-ophthalmologists/yo-info/article/yo-need-to-know-facing-pupil-abnormalities-without'}],evidenceNote,concerns:['Original proposed NEI URL returned404 and was replaced with indexed AAO professional education; full physiological claim review remains pending.']},
{code:'op-s3-0339',category:'neurological',subject:'Anatomy',system:'Nervous System',topic:'Central cord sensory dissociation',subtopic:'Syrinx and crossing spinothalamic fibers',concept:'central cervical cavity preferentially injures crossing pain-temperature fibers',task:'foundational-science',setting:'ambulatory',service:'neurosurgery neurology',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Relates a patterned sensory dissociation to a specific spinal crossing.',stem:'A 24-year-old man notices painless burns on both hands and slowly progressive hand weakness. Pinprick and temperature are reduced over the shoulders and upper arms, while vibration and finger position sense remain intact. MRI shows a central fluid-filled cavity in the cervical spinal cord. Which structure is most directly responsible for the early dissociated sensory loss?',choices:[['Pain-temperature axons crossing in the anterior white commissure','A central cervical syrinx can interrupt segmental decussating spinothalamic fibers, producing bilateral pain-temperature loss while initially sparing more posterior sensory pathways.'],['The dorsal columns alone','Dorsal-column injury would impair vibration and position sense, the modalities specifically preserved despite loss of pain and temperature in this examination.'],['The lateral corticospinal tracts alone','Corticospinal injury produces motor findings but does not directly account for the selective bilateral segmental loss of pain and temperature in this patient.'],['Bilateral dorsal root ganglia alone','Ganglion injury would usually affect multiple sensory modalities in the involved territories, rather than selectively interrupt pain-temperature sensation while preserving vibration and position sense.']],explanation:'A syrinx expands near the center of the spinal cord, where second-order pain-temperature fibers cross in the anterior white commissure before ascending contralaterally. Early injury can therefore create bilateral segmental loss of those modalities while dorsal-column vibration and proprioception remain relatively preserved. Extension may involve anterior horn cells and other tracts, explaining evolving hand weakness. MRI identifies the cavity and helps evaluate associated causes such as disturbed cerebrospinal fluid flow. The question tests the selective early pattern rather than claiming all syringomyelia has an identical examination.',objective:'Localize dissociated cape-distribution pain-temperature loss from a cervical syrinx to crossing anterior commissural fibers.',takeaways:['Sensory dissociation can reveal cord anatomy.','Larger syrinxes may produce additional motor and long-tract findings.'],references:[{label:'NINDS Syringomyelia (indexed government source)',url:'https://www.ninds.nih.gov/health-information/disorders/syringomyelia'}],evidenceNote,concerns:['Source overview does not independently verify every tract-level assertion; anatomical claim review required.']},
{code:'op-s3-0340',category:'neurological',subject:'Genetics',system:'Nervous System',topic:'Huntington anticipation',subtopic:'Repeat expansion across generations',concept:'unstable CAG expansion can produce earlier Huntington onset in a subsequent generation',task:'foundational-science',setting:'ambulatory',service:'neurogenetics',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Links family onset differences to an unstable expansion rather than a change in inheritance class.',stem:'A 34-year-old man has progressive chorea and executive dysfunction. His father developed genetically confirmed Huntington disease in his fifties. He has not taken dopamine-blocking drugs. Testing after genetic counseling confirms an expanded HTT allele in the son, with more CAG repeats than his father had. Which mechanism best explains the earlier onset in the son within this family?',choices:[['Expansion of an unstable trinucleotide repeat during transmission','An increase in the pathogenic CAG repeat can contribute to anticipation, in which disease manifests earlier in a subsequent generation despite autosomal dominant inheritance.'],['Conversion from autosomal dominant to mitochondrial inheritance','The HTT expansion remains an autosomal dominant nuclear genetic disorder; earlier onset does not indicate a switch to maternal mitochondrial transmission.'],['Parent-of-origin genomic imprinting as the sole mechanism','Imprinting affects expression according to parental origin, but the demonstrated increase in pathogenic repeat length provides the direct mechanism for anticipation in this family.'],['A stable repeat with onset determined solely by X-chromosome inactivation','HTT is not an X-linked locus, and the repeat is demonstrably larger in the son; X-inactivation does not explain this intergenerational change.']],explanation:'Huntington disease is associated with a pathogenic CAG repeat expansion in HTT. Repeat length can change during transmission, and larger expansions are associated with earlier average onset, a phenomenon called anticipation. This relationship is probabilistic rather than a precise individual clock; repeat count does not determine every aspect of onset or progression. Genetic counseling should address implications for relatives, reproductive decisions, confidentiality, and psychological support. The vignette provides an observed expansion to explain the family difference without treating all intergenerational onset variation as proof of repeat growth.',objective:'Explain Huntington disease anticipation through intergenerational CAG repeat expansion while avoiding deterministic individual predictions.',takeaways:['Anticipation does not change autosomal dominant inheritance.','Repeat length is not an exact onset forecast.'],references:[{label:'MedlinePlus Genetics Huntington disease (page accessed 2026-10-30)',url:'https://medlineplus.gov/genetics/condition/huntingtons-disease/'}],evidenceNote,concerns:['Canonical URL resolved and page accessed; individualized repeat-risk and onset interpretation require genetics review.']},
{code:'op-s3-0341',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Suspected viral encephalitis',subtopic:'Empiric acyclovir while PCR is pending',concept:'temporal encephalitic syndrome warrants treatment before confirmation',task:'management',setting:'emergency',service:'infectious neurology',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Recognizes a time-sensitive treatment decision despite incomplete microbiology.',stem:'A 45-year-old man develops fever, confusion, difficulty naming objects, and a new focal seizure over two days. MRI shows temporal lobe inflammation without a mass requiring surgery. Cerebrospinal fluid is lymphocyte predominant, and herpes simplex PCR is pending. Blood cultures are collected, and other indicated empiric coverage is being addressed. Which additional therapy should not be delayed while awaiting the viral result?',choices:[['Intravenous acyclovir with renal-function-based dosing','The focal temporal encephalitic syndrome raises concern for herpes simplex infection, for which prompt empiric intravenous acyclovir is appropriate before confirmatory results return.'],['Oral amoxicillin as the only antiviral treatment','Amoxicillin has no antiviral activity against herpes simplex and does not substitute for timely intravenous therapy directed at this potentially destructive encephalitis.'],['No treatment because lymphocytes prove a benign self-limited illness','Lymphocytic CSF does not establish a benign course; herpes encephalitis can cause severe injury and requires urgent therapy when clinically suspected.'],['High-dose corticosteroids alone as definitive treatment','Steroids alone do not treat active herpes replication, and empiric immunosuppression should not replace antiviral treatment in a compatible acute infectious syndrome.']],explanation:'Herpes simplex encephalitis can produce fever, altered behavior or language, seizures, and temporal lobe abnormalities. Treatment should begin when the syndrome is suspected rather than waiting for PCR confirmation because delay can worsen neurological outcomes. Intravenous acyclovir requires attention to renal function, hydration, and toxicity monitoring. The differential remains broad, and an early negative test may require reassessment if suspicion remains high. The question does not imply that every lymphocytic CSF syndrome needs identical treatment; the focal temporal clinical and imaging pattern supplies the key context.',objective:'Begin empiric intravenous acyclovir promptly for a compatible temporal encephalitis syndrome while HSV PCR is pending.',takeaways:['Lymphocytic CSF does not guarantee benign illness.','Dose and monitor acyclovir with renal function in mind.'],references:encephalitis,evidenceNote,concerns:['Overview source does not establish regimen or repeat-PCR rules; current infectious-disease guidance must verify those claims.']},
{code:'op-s3-0342',category:'neurological',subject:'Medicine',system:'Nervous System',topic:'Cryptococcal pressure management',subtopic:'Therapeutic cerebrospinal fluid drainage',concept:'symptomatic elevated opening pressure in cryptococcal meningitis requires active pressure management alongside antifungals',task:'management',setting:'hospital',service:'HIV infectious neurology',ageGroup:'adult',nutrition:false,difficulty:4,difficultyRationale:'Separates microbiological treatment from a simultaneously dangerous physiological complication.',stem:'A 37-year-old man with advanced HIV is receiving induction therapy for confirmed cryptococcal meningitis. He develops severe headache and blurred vision. Fundoscopy reveals bilateral papilledema. Brain imaging excludes a focal mass or obstructive lesion. A properly performed lumbar puncture shows an opening pressure of 36 cm H2O. Which intervention should be added to address the immediate symptomatic complication?',choices:[['Therapeutic cerebrospinal fluid drainage with repeated pressure-guided reassessment','Symptomatic raised pressure in cryptococcal meningitis needs active pressure management, commonly therapeutic lumbar drainage when no contraindicating mass or obstruction is present.'],['Wait for the antifungal course to end before treating pressure','Pressure-related injury can progress despite microbiological improvement, so symptomatic elevation should not be ignored while waiting for antifungals alone to work.'],['Use corticosteroids routinely instead of pressure-directed drainage','Routine corticosteroids are not a substitute for indicated cerebrospinal fluid pressure control in cryptococcal meningitis and can introduce additional harms.'],['Prohibit every lumbar puncture solely because the opening pressure is high','Elevated pressure in cryptococcal meningitis is often itself an indication for therapeutic drainage after appropriate assessment, unlike an unassessed obstructing mass lesion.']],explanation:'Cryptococcal meningitis can impair cerebrospinal fluid resorption and produce dangerous intracranial hypertension. Severe symptoms with a markedly elevated opening pressure require pressure-directed treatment in addition to effective antifungals. Therapeutic lumbar punctures and repeated reassessment are commonly used when structural contraindications have been excluded; persistent cases may require specialist-directed drainage procedures. This differs from blindly removing cerebrospinal fluid in a patient with an obstructing intracranial mass. The amount removed, pressure goals, repeat frequency, and need for diversion must follow current guidance and the patient\'s clinical course.',objective:'Treat symptomatic raised intracranial pressure during cryptococcal meningitis rather than relying on antifungals alone.',takeaways:['Microbiological response does not ensure pressure control.','Distinguish resorption-related pressure from mass-related obstruction.'],references:[{label:'WHO Cryptococcal Disease guideline executive summary (2022; indexed government-hosted guideline)',url:'https://www.ncbi.nlm.nih.gov/books/NBK581826/'}],evidenceNote,concerns:['Verify current US HIV recommendations, drainage targets and contraindications; no fixed drainage volume is asserted.']},
{code:'op-s3-0343',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'HIV white-matter disease',subtopic:'Progressive multifocal leukoencephalopathy',concept:'subacute focal deficits with nonmasslike white-matter lesions suggest PML',task:'diagnosis',setting:'hospital',service:'HIV neurology',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Integrates immune status, tempo and lesion behavior to distinguish opportunistic CNS processes.',stem:'A 43-year-old man with untreated HIV and a CD4 count of 46 cells/mm3 develops progressive left-sided clumsiness and difficulty reading over three weeks. He has no fever or headache. MRI shows asymmetric subcortical white-matter lesions with little enhancement and no substantial mass effect. Which diagnosis best fits this pattern and should guide targeted cerebrospinal fluid testing?',choices:[['Progressive multifocal leukoencephalopathy','Subacute progressive focal deficits in severe immunosuppression with nonmasslike white-matter lesions are characteristic of JC-virus-associated demyelinating disease requiring targeted evaluation.'],['Typical toxoplasma abscesses as the best imaging match','Toxoplasmosis more often produces enhancing focal lesions with surrounding edema or mass effect; the predominantly nonenhancing white-matter pattern here favors another process.'],['Acute embolic stroke as the best temporal explanation','An embolic stroke generally begins abruptly, whereas these deficits progress over weeks with multifocal white-matter changes rather than one acute arterial territory.'],['Uncomplicated tension headache','There is no headache syndrome to explain the progressive focal deficits and objective white-matter lesions in a profoundly immunocompromised patient.']],explanation:'PML is caused by JC virus infection of oligodendrocytes and produces multifocal demyelination, usually in substantial immunosuppression. Progressive focal neurological dysfunction over weeks and asymmetric white-matter lesions without major mass effect are important clues. Cerebrospinal fluid JC-virus PCR can support diagnosis, although a negative result does not universally exclude it and further evaluation may be needed. Imaging patterns overlap with other diseases, so clinical correlation is necessary. Restoring immune function is central to management, but the question asks for the leading diagnosis rather than a complete antiretroviral plan.',objective:'Recognize a PML pattern in advanced HIV using subacute progression and nonmasslike asymmetric white-matter lesions.',takeaways:['Tempo and lesion location help narrow opportunistic CNS disease.','A single negative PCR may not settle a high-suspicion case.'],references:[{label:'NIH Adult/Adolescent Opportunistic Infection guideline: PML/JC virus (indexed guideline)',url:'https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-opportunistic-infections/progressive?view=full'}],evidenceNote,concerns:['Confirm current diagnostic sensitivity and atypical enhancement patterns, particularly with immune reconstitution.']},
{code:'op-s3-0344',category:'neurological',subject:'Medicine',system:'Nervous System',topic:'HIV focal encephalitis',subtopic:'Presumptive toxoplasma disease',concept:'advanced HIV with multiple enhancing basal ganglia lesions and prior exposure supports toxoplasma encephalitis',task:'diagnosis',setting:'hospital',service:'infectious neurology',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Combines immune deficit, imaging distribution and serological evidence without treating imaging as definitive.',stem:'A 35-year-old woman with untreated HIV presents with two weeks of headache and new right arm weakness. Her CD4 count is 28 cells/mm3. MRI shows several ring-enhancing lesions in the basal ganglia with surrounding edema. Toxoplasma IgG is positive, and she has not taken prophylaxis. Which diagnosis is the leading presumptive explanation while a specialist-directed diagnostic and treatment plan proceeds?',choices:[['Toxoplasma encephalitis','Severe cellular immunosuppression, prior toxoplasma exposure, and multiple enhancing lesions with focal deficits make reactivated toxoplasma encephalitis a leading presumptive diagnosis.'],['Progressive multifocal leukoencephalopathy as the typical lesion pattern','PML usually involves white matter without prominent ring enhancement or mass effect, making it a less typical explanation for these edema-associated basal ganglia lesions.'],['An uncomplicated primary migraine','Migraine does not explain multiple ring-enhancing intracranial lesions with edema and persistent focal weakness in a patient with advanced immunosuppression.'],['Primary central nervous system lymphoma','Lymphoma remains an important alternative and can have overlapping imaging; the multiple basal ganglia lesions, positive IgG, and absent prophylaxis favor presumptive toxoplasmosis initially.']],explanation:'In advanced HIV, toxoplasma reactivation commonly presents with subacute focal encephalitis and multiple enhancing brain lesions, often involving the basal ganglia. Positive IgG and lack of prophylaxis strengthen the presumptive diagnosis but do not prove it. Primary CNS lymphoma and other infections remain important alternatives, and lack of expected response to an appropriate treatment plan should trigger reassessment and possible tissue diagnosis. The answer is deliberately framed as a leading presumptive explanation rather than a definitive imaging diagnosis. Prompt specialist management is needed because edema and focal injury can progress.',objective:'Identify presumptive toxoplasma encephalitis in advanced HIV while preserving lymphoma and other causes in the differential.',takeaways:['IgG supports prior exposure rather than definitive lesion causation.','Failure to respond should prompt reassessment.'],references:[{label:'NIH Adult/Adolescent OI guideline: Toxoplasma gondii Encephalitis (indexed guideline)',url:'https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-opportunistic-infections/toxoplasmosis'}],evidenceNote,concerns:['Imaging and IgG cannot definitively exclude lymphoma; verify the intended presumptive-diagnosis framing and response-based reassessment strategy.']},
{code:'op-s3-0345',category:'neurological',subject:'Surgery',system:'Nervous System',topic:'Brain abscess and mass effect',subtopic:'Avoiding unsafe lumbar puncture',concept:'suspected focal intracranial abscess with mass effect requires imaging-directed specialist management rather than routine LP',task:'management',setting:'hospital',service:'neurosurgery infectious disease',ageGroup:'adult',nutrition:false,difficulty:4,difficultyRationale:'Balances diagnostic sampling against a pressure-gradient hazard in a focal lesion.',stem:'A 50-year-old man with recent untreated dental infection develops fever, headache, and left arm weakness. MRI reveals a frontal ring-enhancing lesion with restricted diffusion, surrounding edema, and midline shift. He remains awake and protects his airway. Blood cultures are drawn and empiric therapy is being started. A trainee proposes lumbar puncture to identify the organism. What is the most appropriate response?',choices:[['Defer lumbar puncture and obtain urgent neurosurgical input for lesion-directed diagnosis and management','A focal mass with shift creates a dangerous pressure-gradient concern; imaging-directed specialist assessment and possible lesion sampling are preferable to routine lumbar puncture.'],['Perform a large-volume lumbar puncture immediately to reduce swelling','Lumbar drainage in the presence of a focal mass and shift may precipitate herniation and does not appropriately treat the abscess or edema.'],['Stop antibiotics until a routine outpatient puncture can be arranged','A suspected intracranial infection with neurological deficits requires urgent treatment and consultation; outpatient delay is inappropriate for this potentially life-threatening presentation.'],['Assume ring enhancement proves a benign cyst requiring no action','Restricted diffusion, fever, a possible infectious source, neurological deficit, and mass effect demand urgent evaluation; ring enhancement alone does not establish a harmless lesion.']],explanation:'The imaging and clinical context raise concern for a brain abscess with significant mass effect. Lumbar puncture is not the default diagnostic test for a focal intracranial mass and can be hazardous when pressure gradients or herniation risk are present. Blood cultures, imaging, appropriate empiric antimicrobials, and urgent neurosurgical consultation guide management, including whether drainage or biopsy is needed. Restricted diffusion supports an abscess but is not perfectly specific. The question focuses on choosing a safer diagnostic pathway while treatment proceeds rather than delaying everything until an organism is identified.',objective:'Avoid routine lumbar puncture in a suspected brain abscess with mass effect and coordinate urgent lesion-directed specialist management.',takeaways:['Focal mass effect changes procedural safety.','Obtain microbiology through an appropriate route without delaying emergency care.'],references:encephalitis,evidenceNote,concerns:['Broad NIH overview is insufficient for abscess procedural guidance; attach current neurosurgical/infectious-disease guideline before approval.']},
{code:'op-s3-0346',category:'neurological',subject:'Physiology',system:'Nervous System',topic:'Heat-sensitive demyelinated axons',subtopic:'Reversible conduction failure',concept:'temperature elevation can transiently reduce conduction through already demyelinated pathways',task:'foundational-science',setting:'ambulatory',service:'neuroimmunology rehabilitation',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Distinguishes reversible conduction physiology from formation of new inflammatory lesions.',stem:'A 32-year-old woman with stable multiple sclerosis notices blurred vision in a previously affected eye after spending twenty minutes in a hot bath. The visual change resolves fully after she cools down. Vision was normal immediately beforehand. She has no fever, infection symptoms, or new persistent deficit. Which mechanism best explains the transient recurrence of an old neurological symptom?',choices:[['Temperature-dependent conduction failure in previously demyelinated axons','Demyelination reduces conduction reserve, so warming can transiently impair transmission through affected pathways without requiring a newly formed inflammatory lesion.'],['Immediate creation and disappearance of a new demyelinating plaque','A new structural plaque does not ordinarily form and disappear over minutes solely with warming and cooling; reversible conduction physiology better fits this course.'],['Irreversible destruction of all optic nerve axons during the bath','Complete symptom resolution after cooling argues against immediate irreversible destruction of the entire optic nerve as the explanation for this episode.'],['A transient systemic embolus repeatedly occluding the same retinal artery','The reproducible association with warming and full recovery on cooling in a previously demyelinated pathway favor conduction failure rather than a newly assumed embolic event.']],explanation:'Demyelinated axons have a reduced safety margin for impulse propagation. Increased body temperature can transiently worsen transmission in those pathways and reproduce old deficits, often called Uhthoff phenomenon. Recovery with cooling supports a reversible physiological effect rather than proof of new inflammatory disease. Symptoms still require reassessment if they persist, differ from prior deficits, or occur with infection or other red flags. Counseling can include cooling strategies and adapting activity rather than avoiding all exercise. This is a mechanism question, not a declaration that every new symptom in multiple sclerosis is harmless.',objective:'Explain transient heat-triggered recurrence of old MS deficits through reduced conduction reserve in demyelinated axons.',takeaways:['Transient heat effects do not necessarily indicate a new plaque.','Persistent or changed deficits need reassessment.'],references:[{label:'US VA Multiple Sclerosis Centers of Excellence: Keep Cool, MS and Heat Tolerance (indexed government source)',url:'https://www.va.gov/MS/LEARN_ABOUT_MULTIPLE_SCLEROSIS/Keep_Cool_Multiple_Sclerosis_and_Heat_Tolerance.asp'}],evidenceNote,concerns:['Reviewer must verify mechanistic wording and distinguish this objective from existing infection-triggered pseudo-relapse content.']},
{code:'op-s3-0347',category:'neurological',subject:'Geriatrics',system:'Nervous System',topic:'Sleep-related cognitive symptoms',subtopic:'Obstructive sleep apnea evaluation',concept:'sleep fragmentation with witnessed apneas can contribute to cognitive complaints and merits targeted testing',task:'diagnosis',setting:'ambulatory',service:'sleep medicine geriatrics',ageGroup:'older-adult',nutrition:false,difficulty:3,difficultyRationale:'Uses collateral sleep history to identify an additional treatable contributor to cognition.',stem:'A 65-year-old man reports declining concentration and forgetfulness over a year. His spouse says he snores loudly, stops breathing repeatedly during sleep, and falls asleep while watching morning television. He has obesity and resistant hypertension. Examination shows no focal neurological deficit, and daily independence is preserved. Which additional evaluation most directly addresses an important potentially treatable contributor to these symptoms?',choices:[['A structured sleep assessment followed by appropriate sleep apnea testing','Witnessed apneas, loud snoring, and daytime sleepiness warrant evaluation for obstructive sleep apnea, which can contribute to attention and memory symptoms.'],['Diagnose irreversible Alzheimer disease from the memory complaint alone','Memory complaints are nonspecific, and the prominent sleep-related findings justify evaluation for a treatable contributor rather than an unsupported irreversible diagnosis.'],['Prescribe a sedative every night without investigating breathing','Sedation does not evaluate the repeated apneas and may worsen sleep-related respiratory risk or daytime impairment depending on the drug and circumstances.'],['Ignore the spouse\'s observations because the daytime examination is normal','Sleep-disordered breathing occurs during sleep, so a normal awake neurological examination does not invalidate witnessed apneas or the need for targeted assessment.']],explanation:'Obstructive sleep apnea can fragment sleep and contribute to daytime sleepiness, impaired attention, and memory complaints. Loud snoring, witnessed pauses, obesity, and resistant hypertension provide a coherent reason for structured sleep assessment and appropriate diagnostic testing. Other cognitive causes should still be evaluated according to the history; finding sleep apnea does not exclude neurodegeneration or guarantee complete cognitive recovery with treatment. The case emphasizes a modifiable contributor that would be missed by relying only on an awake examination or assigning a dementia label from subjective forgetfulness.',objective:'Investigate sleep apnea as a potentially treatable contributor to cognitive symptoms when collateral history identifies witnessed apneas and daytime sleepiness.',takeaways:['Collateral sleep observations can change a cognitive evaluation.','Treatable contributors and neurodegeneration can coexist.'],references:[{label:'NHLBI Living With Sleep Apnea (indexed government source)',url:'https://www.nhlbi.nih.gov/health/sleep-apnea/living-with'}],evidenceNote,concerns:['Appropriate home versus laboratory testing selection and cognitive-outcome claims need current sleep-medicine review.']},
{code:'op-s3-0348',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Cataplexy recognition',subtopic:'Emotion-triggered atonia with awareness',concept:'brief emotion-triggered weakness with preserved awareness and daytime sleepiness suggests narcolepsy type1',task:'diagnosis',setting:'ambulatory',service:'sleep neurology',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Distinguishes loss of muscle tone from loss of consciousness using witness detail.',stem:'A 23-year-old student has irresistible daytime sleep episodes despite a regular adequate sleep opportunity. When she laughs intensely, her knees buckle and her jaw briefly sags, but she remains aware of conversations and recalls the events. There is no postevent confusion. She sometimes experiences vivid dreamlike images while falling asleep. Which syndrome best fits the combination and warrants specialist sleep evaluation?',choices:[['Narcolepsy with cataplexy','Emotion-triggered brief loss of tone with preserved awareness, combined with excessive daytime sleepiness and sleep-transition phenomena, suggests a narcolepsy syndrome with cataplexy.'],['Generalized tonic-clonic epilepsy as the best description','Preserved awareness, emotion-linked transient atonia, and absence of a convulsive or postictal phase are not the characteristic pattern of generalized tonic-clonic seizures.'],['Orthostatic syncope caused by standing up','The events occur with laughter rather than posture change and preserve awareness; the chronic sleepiness and dream-transition symptoms suggest a different mechanism.'],['Unilateral lumbar radiculopathy','A focal root lesion cannot explain transient jaw and bilateral leg atonia triggered by emotion alongside irresistible sleep episodes and sleep-transition experiences.']],explanation:'Cataplexy is a sudden transient reduction of voluntary muscle tone, often triggered by strong emotion, with preserved consciousness. In the setting of excessive daytime sleepiness, it raises concern for narcolepsy type1. Sleep paralysis and vivid sleep-transition experiences may accompany the syndrome but are not independently diagnostic. Evaluation should confirm adequate sleep opportunity, review medications and other sleep disorders, and use appropriately prepared specialist testing. The vignette distinguishes muscle weakness from loss of consciousness; labeling every collapse as a seizure would obscure that decisive history and lead to an inappropriate workup.',objective:'Recognize cataplexy from emotion-triggered brief atonia with preserved awareness in a patient with excessive daytime sleepiness.',takeaways:['Ask whether awareness is lost during a collapse.','Sleep-transition symptoms support but do not independently establish narcolepsy.'],references:[{label:'NIH Narcolepsy overview (indexed government source)',url:'https://health.nih.gov/health-topics-a-z/narcolepsy'}],evidenceNote,concerns:['Formal sleep-test preparation and diagnostic criteria require current specialty verification; syndrome remains presumptive.']},
{code:'op-s3-0349',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Orthostatic postprocedural headache',subtopic:'Post-dural puncture CSF leak',concept:'new positional headache after dural puncture suggests CSF leakage',task:'diagnosis',setting:'ambulatory',service:'anesthesia neurology',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Uses positional physiology and procedure timing while retaining warning features for alternatives.',stem:'Two days after a diagnostic lumbar puncture, a 34-year-old woman develops a headache that becomes severe within minutes of standing and improves substantially when she lies flat. She has mild neck discomfort but no fever, seizure, confusion, or focal deficit. The puncture site is clean, and no anticoagulants were used. Which diagnosis best explains this new procedure-associated positional headache?',choices:[['Post-dural puncture headache from cerebrospinal fluid leakage','The close timing after dural puncture and reproducible upright worsening with recumbent relief support a pressure-related headache caused by persistent cerebrospinal fluid leakage.'],['Bacterial meningitis established solely by neck discomfort','Meningitis remains a concern with compatible features, but isolated mild neck discomfort with a strongly positional afebrile postprocedural pattern does not establish that diagnosis.'],['Medication-overuse headache after one dose of acetaminophen','A single analgesic exposure does not meet the sustained-use pattern associated with medication-overuse headache and cannot explain the immediate positional relationship.'],['A chronic cluster headache cycle','Cluster attacks have a different autonomic and temporal pattern and are not characteristically created by standing after lumbar puncture with relief on lying flat.']],explanation:'A dural puncture can permit continued cerebrospinal fluid leakage, producing a headache that is worse upright and relieved by lying down. The procedure history and positional pattern are stronger discriminators than the nonspecific neck discomfort. Persistent or disabling symptoms may warrant anesthesia review and consideration of an epidural blood patch after appropriate assessment. Fever, a changed nonpositional headache, neurological deficits, seizures, or altered consciousness require reevaluation for other complications. The diagnosis is not established by timing alone; it is supported by the full compatible clinical course.',objective:'Recognize post-dural puncture headache from a new reproducible orthostatic pattern after lumbar puncture.',takeaways:['Procedure timing and posture are useful headache clues.','New red flags require reassessment rather than automatic attribution to a leak.'],references:[{label:'American Society of Anesthesiologists post-dural puncture headache statement (2021; page accessed 2026-10-30)',url:'https://www.asahq.org/standards-and-practice-parameters/statement-on-post-dural-puncture-headache-management'}],evidenceNote,concerns:['ASA statement page accessed and identifies2021 obstetric committee origin; verify applicability to diagnostic LP, current terminology and blood-patch indications.']},
{code:'op-s3-0350',category:'neurological',subject:'Pharmacology',system:'Nervous System',topic:'Antibiotic-associated neurotoxicity',subtopic:'Cefepime during acute kidney injury',concept:'cefepime accumulation can cause encephalopathy and myoclonus during renal decline',task:'diagnosis',setting:'hospital',service:'hospital medicine neurology',ageGroup:'older-adult',nutrition:false,difficulty:4,difficultyRationale:'Integrates a changing clearance parameter with delayed neurological toxicity during infection improvement.',stem:'A 74-year-old man receives cefepime for pneumonia. By day four his fever and oxygen requirement have improved, but creatinine has risen from 1.0 to 3.1 mg/dL. The original dose has not been adjusted. He develops confusion and multifocal myoclonus. Glucose and sodium are normal, and CT shows no acute lesion. Which diagnosis should be strongly considered during urgent medication review?',choices:[['Cefepime-associated neurotoxicity during reduced renal clearance','Encephalopathy, myoclonus, and seizures are recognized cefepime toxicities, with renal impairment and unadjusted exposure increasing concern in this evolving clinical context.'],['Pneumonia progression proven by any new confusion','Infection can cause delirium, but improving respiratory findings and a new clearance problem make medication toxicity important rather than assuming infection progression.'],['A new inherited Huntington disorder','An inherited progressive choreiform syndrome does not explain abrupt hospital-onset encephalopathy and myoclonus after a renally cleared medication accumulates.'],['An acute migraine aura without headache','The diffuse encephalopathy, multifocal myoclonus, renal deterioration, and drug exposure do not match a typical fully reversible sequential migraine aura pattern.']],explanation:'Cefepime is renally cleared, and acute deterioration in kidney function can increase exposure if dosing is not reassessed. Its neurotoxicity can include altered consciousness, myoclonus, and seizures, including nonconvulsive status. Urgent medication adjustment or replacement, neurological assessment, and EEG when indicated are appropriate components of the response while other causes are evaluated. Toxicity can occasionally occur despite apparently adjusted doses, so a normal prescribing record does not universally exclude it. This case tests the importance of dynamic renal dosing rather than treating the admission creatinine as permanently valid.',objective:'Consider cefepime neurotoxicity when new encephalopathy and myoclonus accompany renal decline during treatment.',takeaways:['Reassess renal dosing as function changes.','Improving infection does not exclude a new drug-related neurological problem.'],references:[{label:'DailyMed official cefepime injection labeling (indexed fixed product label)',url:'https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=be5f8ca6-7232-423a-a2d5-cccb7abe7921'}],evidenceNote,concerns:['Verify current label and product equivalence, renal dosing and EEG indications; no dose or dialysis threshold is specified.']},
{code:'op-s3-0391',category:'behavioral',subject:'Psychiatry',system:'Behavioral Health',topic:'Restrictive intake without body-image drive',subtopic:'ARFID after fear of choking',concept:'fear-driven nutritional restriction without weight-shape preoccupation suggests ARFID',task:'diagnosis',setting:'ambulatory',service:'adolescent medicine psychiatry',ageGroup:'pediatric',nutrition:true,difficulty:3,difficultyRationale:'Distinguishes the motivation for restriction while integrating objective nutritional consequences.',stem:'A 15-year-old boy has lost weight over four months after choking on a piece of meat. He now accepts only a few soft foods and avoids eating with friends. A swallowing evaluation finds no structural or physiological impairment. He wants to regain weight and denies fear of fatness or dissatisfaction with his body. Which diagnosis best explains the persistent restriction and nutritional impairment?',choices:[['Avoidant/restrictive food intake disorder','Restriction driven by fear of an aversive eating consequence, with nutritional and social impairment but no weight-shape drive, supports an avoidant/restrictive intake disorder.'],['Anorexia nervosa','Anorexia typically involves fear of weight gain or behavior preventing it and disturbed weight-related self-evaluation; this patient wants to regain weight and describes choking fear.'],['Bulimia nervosa','Bulimia involves recurrent binge eating and compensatory behaviors; neither is reported, and restriction here is linked to fear of choking rather than binges.'],['A normal transient food preference requiring no assessment','Four months of weight loss and social interference go beyond a harmless preference and require nutritional, medical, and psychological evaluation and support.']],explanation:'ARFID can arise from fear of choking or vomiting, sensory aversion, or low interest in eating. The restriction must lead to meaningful consequences such as nutritional deficiency, weight or growth impairment, reliance on supplements, or psychosocial disruption. Unlike anorexia nervosa, weight-shape preoccupation is not the driving feature. A negative swallowing evaluation supports considering a behavioral cause but does not eliminate the need to monitor medical stability and investigate new symptoms. Treatment planning should address both nutritional restoration and the maintaining fear, with developmentally appropriate family involvement.',objective:'Recognize ARFID when fear of choking drives persistent nutritionally harmful restriction without weight-shape preoccupation.',takeaways:['Assess the motivation for restrictive eating.','Normal swallowing does not make nutritional impairment trivial.'],references:[{label:'NIMH Eating Disorders: What You Need to Know (indexed government source)',url:'https://www.nimh.nih.gov/health/publications/eating-disorders'}],evidenceNote,concerns:['Formal diagnostic exclusions, pediatric growth assessment and treatment planning require qualified review.']},
{code:'op-s3-0392',category:'behavioral',subject:'Psychiatry',system:'Behavioral Health',topic:'Recurrent binge eating assessment',subtopic:'Absence of compensatory behavior',concept:'recurrent distressing loss-of-control binges without regular compensation favor binge-eating disorder',task:'diagnosis',setting:'ambulatory',service:'primary care psychiatry',ageGroup:'adult',nutrition:true,difficulty:3,difficultyRationale:'Separates episode characteristics and compensation rather than using body size as the diagnosis.',stem:'A 32-year-old woman reports eating unusually large amounts within two hours at least twice weekly for five months. During these episodes she feels unable to stop, eats rapidly when not hungry, and feels ashamed afterward. She does not vomit, misuse laxatives, fast, or exercise to compensate. Examination shows no acute medical instability. Which diagnosis is most consistent with the reported eating pattern?',choices:[['Binge-eating disorder','Recurrent objectively large loss-of-control binges with marked distress and no regular compensatory behavior support binge-eating disorder when other diagnostic requirements are met.'],['Bulimia nervosa','Bulimia includes recurrent inappropriate compensatory behaviors, which this history specifically denies; the presence of binges alone does not establish bulimia.'],['Anorexia nervosa, restricting presentation','The history does not describe restrictive low-weight illness or fear-driven prevention of weight gain; the central episodes instead involve recurrent loss-of-control large intake.'],['Ordinary overeating without clinically meaningful impairment','The repeated loss of control, associated features, duration, and marked distress distinguish the described pattern from occasional nondistressing overeating or a large celebratory meal.']],explanation:'Binge-eating disorder involves recurrent binge episodes with loss of control and distress, without the regular compensatory behaviors that characterize bulimia nervosa. Diagnosis depends on the episode pattern and associated impairment, not on a particular body mass index. Assessment should also consider mood, trauma, medications, sleep, metabolic health, and other eating disorders, using nonstigmatizing language. Nutritional care should avoid reinforcing cycles of extreme restriction and bingeing. The stem supplies duration and recurrence consistent with a persistent syndrome but still requires a full clinical assessment before any individual diagnosis or treatment recommendation.',objective:'Distinguish binge-eating disorder from bulimia using the absence of regular compensatory behaviors and the presence of distressing loss-of-control binges.',takeaways:['Body size alone does not diagnose an eating disorder.','Ask specifically about compensatory behaviors.'],references:[{label:'American Psychiatric Association: What are Eating Disorders? (indexed professional source)',url:'https://www.psychiatry.org/patients-families/eating-disorders/what-are-eating-disorders/'}],evidenceNote,concerns:['Formal criteria and differential diagnosis require current diagnostic reference review; avoid equating all overeating with binge-eating disorder.']},
{code:'op-s3-0393',category:'behavioral',subject:'Psychiatry',system:'Behavioral Health',topic:'Medication-induced restlessness',subtopic:'Akathisia after antipsychotic increase',concept:'new subjective restlessness with pacing after antipsychotic escalation suggests akathisia',task:'diagnosis',setting:'ambulatory',service:'psychiatry medication monitoring',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Distinguishes a medication adverse effect from psychotic agitation and anxiety.',stem:'A 26-year-old man with improving psychosis returns one week after an antipsychotic dose increase. He repeatedly stands, shifts his feet, and says, "I feel driven to move from inside." Hallucinations have decreased, sleep need is unchanged, and there is no fever, rigidity, or autonomic instability. Which explanation should be assessed before interpreting the behavior as worsening psychosis and increasing the dose again?',choices:[['Antipsychotic-induced akathisia','Subjective inner restlessness with characteristic motor activity emerging after a dose increase suggests akathisia and should prompt adverse-effect assessment rather than automatic escalation.'],['Neuroleptic malignant syndrome','This syndrome typically includes severe rigidity, hyperthermia, autonomic abnormalities, and altered mental state rather than isolated restless pacing with stable vital signs.'],['Tardive dyskinesia','Tardive dyskinesia causes involuntary repetitive movements, often orofacial, rather than the distressing conscious urge to move shortly after a dose increase.'],['A manic episode established by pacing alone','Pacing alone does not establish mania; unchanged sleep need and improving psychosis with a clear medication-related onset favor an adverse movement effect.']],explanation:'Akathisia combines a subjective sense of inner restlessness with observable movement such as pacing or shifting weight. It often emerges after starting or increasing an antipsychotic and can be mistaken for anxiety, agitation, or worsening psychosis. Further dose escalation may aggravate the problem. Assessment includes timing, other medications, severity, and safety, followed by an individualized medication review and treatment plan. The absence of fever and rigidity argues against neuroleptic malignant syndrome but does not eliminate the need to reassess if new systemic signs develop. Asking about the internal urge is especially useful.',objective:'Recognize akathisia before escalating an antipsychotic for newly developed restless pacing after a dose increase.',takeaways:['Ask about subjective inner restlessness.','Movement adverse effects can mimic psychiatric deterioration.'],references:[{label:'New York State Department of Health: Diagnosis and Management of Medication-Induced Movement Disorders (indexed government source)',url:'https://www.health.ny.gov/diseases/conditions/mimds/diagnosis.htm'}],evidenceNote,concerns:['Verify current treatment choices and adverse-effect differential; no particular adjunctive drug is prescribed.']},
{code:'op-s3-0394',category:'behavioral',subject:'Psychiatry',system:'Behavioral Health',topic:'Catatonia syndrome assessment',subtopic:'Motor signs beyond withdrawal',concept:'mutism with posturing negativism and waxy flexibility suggests catatonia requiring etiologic evaluation',task:'diagnosis',setting:'hospital',service:'consultation liaison psychiatry',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Distinguishes a motor-behavioral syndrome from simple unwillingness to engage.',stem:'A 40-year-old woman with a severe mood episode stops speaking and eating. She remains awake, holds an arm in an imposed position, resists simple instructions without an apparent reason, and occasionally echoes the examiner\'s last word. Temperature and autonomic signs are stable. Which syndrome best organizes these findings and should prompt urgent medical and psychiatric evaluation rather than labeling her uncooperative?',choices:[['Catatonia','Mutism, posturing, negativism, and echo phenomena support a catatonic syndrome, which can accompany psychiatric or medical illness and requires active evaluation and treatment.'],['Uncomplicated depressive low motivation alone','Depression may coexist, but the specific motor signs and echo phenomena indicate more than reduced motivation and should not be dismissed as ordinary withdrawal.'],['Isolated expressive aphasia','A language disorder does not by itself explain sustained imposed postures, negativism, and the broader motor-behavioral pattern; focal neurological causes still require appropriate exclusion.'],['Neuroleptic malignant syndrome proven by mutism','Mutism alone does not establish that syndrome, particularly without the typical fever, rigidity, autonomic instability, or relevant exposure context described in the stem.']],explanation:'Catatonia is a syndrome of abnormal movement and behavior that may occur with mood disorders, psychotic disorders, neurological illness, metabolic disturbances, and medication effects. The combination of mutism, posturing, negativism, and echolalia is more informative than refusal to speak alone. Assessment should include medical causes, hydration, nutrition, thrombosis risk, and other complications. A monitored lorazepam challenge may support diagnosis but is not perfectly specific, and treatment requires an individualized plan. Stable vital signs do not justify ignoring the syndrome or waiting for malignant features before intervening.',objective:'Recognize catatonia from clustered motor-behavioral signs and initiate etiologic and complication assessment.',takeaways:['Catatonia is a syndrome with psychiatric and medical causes.','Do not confuse motor-behavioral signs with deliberate noncooperation.'],references:[{label:'British Association for Psychopharmacology Catatonia consensus guideline (2023; indexed primary guideline)',url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC10101189/'}],evidenceNote,concerns:['Formal criteria, neurological mimics and challenge-test interpretation require specialist review.']},
{code:'op-s3-0395',category:'behavioral',subject:'Pharmacology',system:'Behavioral Health',topic:'Buprenorphine precipitated withdrawal',subtopic:'Partial agonism with high receptor affinity',concept:'buprenorphine can displace a full agonist and abruptly reduce net opioid effect',task:'foundational-science',setting:'ambulatory',service:'addiction medicine',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Explains worsening withdrawal using receptor affinity and intrinsic activity together.',stem:'A 29-year-old man with opioid dependence takes a standard buprenorphine dose shortly after using a full opioid agonist, before objective withdrawal begins. Within minutes he develops abrupt severe sweating, abdominal cramps, yawning, and restlessness. His breathing is adequate, and his pupils have dilated. Which pharmacological property best explains why a medication with opioid agonist activity can trigger this reaction?',choices:[['High receptor affinity with lower intrinsic agonist activity than the displaced opioid','Buprenorphine can displace a full agonist while providing less net receptor activation, causing precipitated withdrawal in a physically dependent patient when initiation timing is unsuitable.'],['Irreversible destruction of opioid receptors by the first dose','The acute reaction reflects receptor occupancy and relative agonist activity, not destruction of receptors or permanent loss of all opioid signaling.'],['Pure full agonism that always increases receptor activation','Buprenorphine is a partial agonist, so displacement of a full agonist can reduce rather than increase net activation in a dependent patient.'],['Competitive antagonism at peripheral muscarinic receptors','Muscarinic blockade does not explain this opioid-dependent withdrawal mechanism, which depends on displacement of a full agonist and reduced net opioid receptor activation.']],explanation:'Buprenorphine has high affinity for opioid receptors but lower intrinsic activity than a full agonist. If started under unsuitable conditions while substantial full-agonist effect persists, it can replace that opioid and abruptly lower net signaling, producing precipitated withdrawal. Standard initiation uses clinical withdrawal assessment, not a fixed clock alone. Fentanyl exposure and alternative low-dose initiation approaches complicate simple timing rules and require individualized experienced care. The mechanism does not make buprenorphine inappropriate for opioid use disorder; it explains why preparation, monitoring, and a plan for managing withdrawal are important.',objective:'Explain precipitated opioid withdrawal through the combination of high-affinity displacement and partial agonist activity.',takeaways:['Affinity and intrinsic activity are distinct.','Standard induction requires clinical assessment rather than a clock alone.'],references:[{label:'SAMHSA Buprenorphine Quick Start Guide (indexed government guidance)',url:'https://www.samhsa.gov/sites/default/files/quick-start-guide.pdf'}],evidenceNote,concerns:['Verify current fentanyl-era initiation guidance and avoid implying that standard withdrawal-based induction is the only acceptable strategy.']},
{code:'op-s3-0396',category:'behavioral',subject:'Psychiatry',system:'Behavioral Health',topic:'Clozapine bowel safety',subtopic:'Symptomatic gastrointestinal hypomotility',concept:'clozapine-associated constipation with pain distention and vomiting requires urgent assessment',task:'management',setting:'emergency',service:'psychiatry medical safety',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Recognizes a potentially life-threatening adverse effect behind a common symptom.',stem:'A 44-year-old man taking clozapine has passed no stool for five days. He now has abdominal distention, worsening pain, and vomiting. He has no history of abdominal operations or hernias. His caregiver says he usually minimizes bowel symptoms. He is passing little flatus and is also taking an anticholinergic medication. What is the most appropriate response to this presentation?',choices:[['Arrange urgent medical assessment for severe hypomotility, ileus, or obstruction and review contributing medications','Pain, distention, vomiting, and prolonged constipation during clozapine therapy require urgent evaluation because hypomotility can progress to dangerous bowel complications.'],['Recommend fiber alone and defer evaluation for a month','Fiber advice alone is inadequate when red flags suggest ileus or obstruction, and bulk intake may be inappropriate before the acute process is assessed.'],['Increase the anticholinergic medication to reduce abdominal discomfort','Additional anticholinergic exposure can worsen bowel motility and does not address possible obstruction or another serious complication causing pain and vomiting.'],['Dismiss the complaint because subjective constipation is unreliable','Underreporting makes proactive assessment more important; unreliable symptom reporting does not negate the observed distention, vomiting, and absent bowel movements.']],explanation:'Clozapine can cause substantial gastrointestinal hypomotility, sometimes progressing to obstruction, ischemia, perforation, or death. Abdominal pain, distention, vomiting, and prolonged absence of stool require urgent medical evaluation rather than routine dietary advice alone. Anticholinergic drugs can add to the motility burden and should be reviewed. Long-term care includes proactive bowel monitoring and an individualized preventive regimen, but acute red flags must be assessed first. A patient\'s limited or unreliable subjective complaint is not reassuring when objective symptoms and caregiver observations indicate deterioration.',objective:'Escalate clozapine-associated constipation with abdominal red flags for urgent medical assessment and medication review.',takeaways:['Bowel monitoring is part of clozapine safety.','Do not treat possible obstruction with generic fiber advice alone.'],references:[{label:'FDA Drug Safety Communication: clozapine constipation and serious bowel problems (indexed regulator source)',url:'https://www.fda.gov/drugs/drug-safety-and-availability/fda-strengthens-warning-untreated-constipation-caused-schizophrenia-medicine-clozapine-clozaril-can'}],evidenceNote,concerns:['Verify acute medication-holding decisions, laxative contraindications and local emergency assessment protocol.']},
{code:'op-s3-0397',category:'behavioral',subject:'Psychiatry',system:'Behavioral Health',topic:'Benzodiazepine deprescribing',subtopic:'Dependence and individualized taper',concept:'long-term regular benzodiazepines should not be abruptly stopped during routine deprescribing',task:'management',setting:'ambulatory',service:'geriatric primary care',ageGroup:'older-adult',nutrition:false,difficulty:3,difficultyRationale:'Balances ongoing adverse-effect risk against withdrawal harm during a planned change.',stem:'A 72-year-old woman has taken a prescribed benzodiazepine every night for six years. She reports morning sedation and has fallen twice, so she and her clinician agree to reduce it. She is currently medically stable, has no intoxication or overdose, and can attend follow-up with family help monitoring symptoms. Which approach is most appropriate for the medication change?',choices:[['Plan a gradual individualized taper with monitoring and treatment of the original sleep complaint','Long-term regular exposure can produce physical dependence; a monitored taper reduces withdrawal risk while addressing sleep symptoms and adjusting pace to the patient\'s response.'],['Stop the full dose immediately because continued use has risks','Abrupt cessation after prolonged regular use can cause severe withdrawal, including seizures, and is not justified as routine deprescribing in this stable patient.'],['Replace every dose with alcohol until sleep improves','Alcohol introduces additional sedation, falls, dependence, and interaction risks and is not a safe withdrawal-management or insomnia-treatment substitute for a planned taper.'],['Promise that one identical rapid schedule is safe for all patients','Taper tolerance varies with drug, dose, duration, comorbidity, and symptoms; rigid promises ignore the need for individualized adjustment and follow-up.']],explanation:'The benefit-risk balance can favor reducing long-term benzodiazepines in an older adult with sedation and falls, but physical dependence changes how discontinuation should occur. A gradual individualized taper, ongoing monitoring, and treatment of the original indication help reduce withdrawal-related harm and support success. Some patients need slower reductions or pauses, and severe withdrawal risk may require a higher level of care. Dependence does not automatically establish a substance use disorder. This case describes a stable planned deprescribing situation, not an acute overdose requiring emergency management.',objective:'Use a monitored individualized taper rather than abrupt cessation when deprescribing long-term regular benzodiazepines.',takeaways:['Physical dependence and substance use disorder are different concepts.','Adjust taper pace to symptoms and risk.'],references:[{label:'ASAM Joint Clinical Practice Guideline on Benzodiazepine Tapering (2025; indexed guideline)',url:'https://www.asam.org/quality-care/clinical-guidelines/benzodiazepine-tapering'}],evidenceNote,concerns:['Guideline notes limited comparative evidence for schedules; no fixed taper percentage or interval is asserted.']},
{code:'op-s3-0398',category:'behavioral',subject:'Psychiatry',system:'Behavioral Health',topic:'Complicated alcohol withdrawal',subtopic:'Withdrawal delirium treatment',concept:'alcohol withdrawal delirium requires monitored withdrawal-directed medication rather than antipsychotic monotherapy',task:'management',setting:'hospital',service:'addiction critical care',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Distinguishes a withdrawal physiology emergency from isolated hallucinations.',stem:'A 51-year-old man admitted for pancreatitis develops tremor, profuse sweating, disorientation, and visual hallucinations three days after his last heavy alcohol intake. Heart rate is 128/min and blood pressure is elevated. Glucose and oxygenation are normal. Thiamine and electrolyte assessment are being provided. Which medication strategy best addresses the underlying withdrawal emergency in a monitored setting?',choices:[['Benzodiazepine-based withdrawal treatment with close clinical monitoring','Withdrawal delirium requires medication that treats alcohol-withdrawal physiology and reduces seizure risk, with dosing and respiratory monitoring adapted to severity and comorbidity.'],['Antipsychotic monotherapy because hallucinations are the main danger','An antipsychotic alone does not adequately treat withdrawal physiology or prevent withdrawal seizures; an adjunct may sometimes be used under appropriate monitoring.'],['A beta blocker alone to normalize the heart rate','Autonomic symptom reduction can mask severity without treating the central withdrawal process or providing adequate protection against seizures and delirium.'],['An antidepressant alone with reassessment after several weeks','Antidepressants do not provide acute treatment of alcohol withdrawal delirium, which is a medical emergency requiring immediate monitored stabilization and withdrawal-directed therapy.']],explanation:'The timing after cessation, tremor, autonomic activation, hallucinations, and disorientation are concerning for alcohol withdrawal delirium. Benzodiazepines are a standard first-line treatment in monitored care, with an appropriate protocol and adjustment for clinical status. Other experienced-clinician regimens may be appropriate in selected settings, so the question does not claim that one drug class is the only possible treatment. Thiamine, electrolyte correction, hydration, and investigation of concurrent illness remain essential. Antipsychotics or autonomic agents may have adjunctive roles but do not replace adequate treatment of the withdrawal mechanism.',objective:'Treat alcohol withdrawal delirium with monitored withdrawal-directed therapy rather than isolated antipsychotic or autonomic symptom treatment.',takeaways:['Treat withdrawal physiology, not only visible agitation.','Supportive care and alternate-cause evaluation continue concurrently.'],references:[{label:'ASAM Clinical Practice Guideline on Alcohol Withdrawal Management (2020; indexed primary guideline)',url:'https://www.asam.org/quality-care/clinical-guidelines/alcohol-withdrawal-management-guideline'}],evidenceNote,concerns:['Confirm contemporary protocol, hepatic-disease drug selection and appropriate severity monitoring; no dose or scale is prescribed.']},
{code:'op-s3-0399',category:'behavioral',subject:'Psychiatry',system:'Behavioral Health',topic:'Antipsychotic metabolic follow-up',subtopic:'New dysglycemia and weight gain',concept:'metabolic adverse effects need coordinated assessment rather than abrupt unplanned antipsychotic cessation',task:'management',setting:'ambulatory',service:'psychiatry primary care coordination',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Balances relapse prevention with a newly measurable medical treatment burden.',stem:'A 38-year-old woman has remained free of psychotic relapse for a year on an antipsychotic. During that time she has gained substantial weight, and repeat testing confirms new diabetes. She wants help with the metabolic effects but fears another hospitalization if treatment is stopped. She has no hyperglycemic emergency. What is the most appropriate next step?',choices:[['Coordinate diabetes treatment and a shared psychiatric medication risk-benefit review','Confirmed metabolic harm requires active medical management and discussion of medication options while preserving relapse prevention and the patient\'s preferences through a coordinated plan.'],['Stop the antipsychotic immediately without psychiatric follow-up','Abrupt unplanned cessation can precipitate relapse and does not itself provide adequate diabetes assessment, monitoring, or a safe alternative psychiatric strategy.'],['Ignore diabetes because psychiatric stability makes all adverse effects acceptable','Psychiatric benefit does not erase clinically important metabolic harm; both conditions deserve treatment and a collaborative review of the overall benefit-risk balance.'],['Increase the antipsychotic dose to treat the weight gain','A dose increase is not a treatment for metabolic adverse effects and may worsen the burden depending on the drug without addressing diabetes care.']],explanation:'Antipsychotic-associated weight and metabolic changes require proactive monitoring and treatment. New diabetes warrants appropriate medical assessment and management, while psychiatric care reviews the current drug, prior response, alternative agents, relapse risk, and patient preferences. A switch may be reasonable in some circumstances but should be planned rather than assumed universally safe or necessary. Lifestyle and nutritional support can contribute without replacing indicated diabetes treatment. The question tests coordination of competing clinical priorities, avoiding both therapeutic abandonment of psychosis and dismissal of measurable physical harm.',objective:'Coordinate treatment of new metabolic disease with an individualized psychiatric medication review while preserving relapse-prevention planning.',takeaways:['Psychiatric benefit and physical adverse effects both matter.','Medication changes should be coordinated and monitored.'],references:[{label:'NIMH Mental Health Medications (indexed government overview)',url:'https://www.nimh.nih.gov/health/topics/mental-health-medications'}],evidenceNote,concerns:['Broad overview does not establish agent-specific metabolic risks or switching strategy; add current specialty guidance and exact drug context during review.']},
{code:'op-s3-0400',category:'behavioral',subject:'Psychiatry',system:'Behavioral Health',topic:'Lamotrigine serious rash warning',subtopic:'Mucosal and systemic features',concept:'new lamotrigine rash with mucosal involvement requires stopping the suspected drug and emergency assessment',task:'management',setting:'emergency',service:'psychiatry medication safety',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Recognizes high-risk features rather than treating all eruptions as a minor nuisance.',stem:'A 24-year-old woman began lamotrigine for bipolar maintenance three weeks ago. She now has fever, a spreading painful rash, and erosions inside her mouth. She is not taking an antiseizure regimen for epilepsy. There is no clearly established alternative cause. What is the most appropriate immediate action while arranging urgent evaluation of the systemic reaction?',choices:[['Stop lamotrigine and arrange emergency assessment for a severe cutaneous adverse reaction','A new rash with mucosal and systemic features during early lamotrigine treatment requires urgent assessment and drug discontinuation when a harmless alternative cause is not established.'],['Continue the same dose and add only an oral antihistamine','Antihistamine treatment alone is inadequate for possible severe cutaneous injury and continuing the suspected drug may allow a dangerous reaction to progress.'],['Increase lamotrigine because a rash proves the dose is too low','Rash is an adverse-effect warning rather than evidence of inadequate therapeutic dosing; increasing exposure could worsen an evolving serious reaction.'],['Wait until the entire skin surface blisters before changing therapy','Severe reactions should be assessed before extensive detachment occurs; mucosal involvement, skin pain, and fever already provide significant warning signs.']],explanation:'Lamotrigine carries a serious rash warning. Early eruptions can be difficult to classify, and mucosal erosions, fever, and painful spreading lesions raise concern for a severe cutaneous adverse reaction such as Stevens-Johnson syndrome. The suspected drug should be stopped and emergency medical assessment arranged rather than continuing it with symptomatic treatment alone. Further classification, supportive care, and future medication decisions require specialist input. The question does not claim every lamotrigine rash has the same diagnosis, and it avoids implying that unsupervised rechallenge is safe after a significant reaction.',objective:'Stop suspected lamotrigine exposure and escalate urgently when a new rash includes mucosal and systemic warning features.',takeaways:['Mucosal lesions and skin pain are major rash red flags.','Do not wait for extensive detachment before assessment.'],references:[{label:'DailyMed official lamotrigine tablets labeling (indexed fixed product label)',url:'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=474fb321-575c-4b97-9dbe-080061652ee4'}],evidenceNote,concerns:['Verify current boxed warning, product label and emergency skin-reaction guidance; no rechallenge recommendation is made.']},
{code:'op-s3-0351',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'PFO and stroke attribution',subtopic:'Excluding alternative embolic mechanisms',concept:'finding a PFO does not establish causation or justify closure before a complete stroke evaluation',task:'management',setting:'ambulatory',service:'secondary stroke prevention',ageGroup:'adult',nutrition:false,difficulty:4,difficultyRationale:'Distinguishes an incidental common finding from a potentially causal mechanism before an invasive preventive treatment.',stem:'A 49-year-old man is recovering from a small embolic-appearing cortical infarct. Echocardiography identifies a patent foramen ovale. Only one admission ECG has been obtained; no prolonged rhythm assessment or complete cervical vascular evaluation has occurred. He has hypertension and reports intermittent palpitations. A relative asks whether immediate closure will eliminate his stroke risk. What is the most appropriate next step?',choices:[['Complete an etiologic stroke evaluation before deciding whether PFO closure is appropriate','A PFO can be incidental; alternative mechanisms, including atrial arrhythmia and arterial disease, must be assessed before attributing the stroke to it and considering closure.'],['Schedule closure solely because the echocardiogram found a PFO','Detection alone does not demonstrate causation, and closure will not address an unrecognized competing mechanism such as atrial fibrillation or significant arterial disease.'],['Use a single normal admission ECG to exclude paroxysmal atrial fibrillation','An intermittent rhythm disorder may not appear on a brief tracing; the history and risk profile justify an appropriate assessment beyond one normal ECG.'],['Explain that closure guarantees prevention of all future strokes','No closure strategy eliminates every stroke mechanism, and counseling must include residual risk, procedural harms, alternatives, and the uncertainty of causal attribution.']],explanation:'PFOs are common and may be incidental findings during a stroke investigation. Before offering closure, clinicians should determine whether the infarct pattern and a sufficiently complete evaluation support a PFO-associated mechanism and whether another cause would change prevention. Intermittent palpitations and vascular risk make unrecognized atrial fibrillation or arterial disease relevant possibilities. Selected patients may benefit from closure after appropriate evaluation and shared decision-making, but the finding alone is not an indication. This decision preserves the distinction between identifying an anatomical pathway and proving that it caused the event.',objective:'Complete an appropriate stroke-cause evaluation before attributing an embolic infarct to a PFO and recommending closure.',takeaways:['A common anatomical finding may be incidental.','Closure decisions require competing-cause assessment and shared counseling.'],references:[{label:'AAN PFO and secondary stroke prevention practice advisory (2020; indexed primary guideline)',url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC7526671/'}],evidenceNote,concerns:['Verify current age, rhythm-monitoring and anatomical selection recommendations; no universal monitoring duration or closure indication is asserted.']},
{code:'op-s3-0352',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Retinal transient ischemia localization',subtopic:'Ipsilateral carotid embolic source',concept:'transient monocular curtain-like loss with ipsilateral severe carotid disease suggests retinal ischemia',task:'diagnosis',setting:'emergency',service:'vascular neuro-ophthalmology',ageGroup:'older-adult',nutrition:false,difficulty:3,difficultyRationale:'Localizes transient visual loss and connects the side of symptoms to a vascular source.',stem:'A 68-year-old man has three painless episodes in which a dark curtain covers the right eye for two minutes before vision returns completely. He has no scintillating lights or gradual visual spread. Examination between episodes is normal. Vascular imaging shows severe right internal carotid stenosis with an irregular plaque, while the left carotid is minimally narrowed. Which mechanism best explains the episodes?',choices:[['Transient embolic retinal ischemia from the right carotid circulation','The right ophthalmic circulation arises from the right internal carotid, and abrupt negative monocular episodes with an ipsilateral irregular plaque support retinal transient ischemia.'],['Left occipital cortex ischemia producing isolated right monocular blindness','A retrochiasmal cortical lesion generally produces a visual-field defect affecting both eyes rather than a strictly monocular curtain-like loss in one eye.'],['A typical gradually spreading migraine aura','Migraine aura often evolves over minutes with positive visual phenomena; abrupt negative monocular curtain-like events and ipsilateral plaque favor an ischemic mechanism here.'],['Chronic bilateral open-angle glaucoma','Glaucoma can damage visual fields over time but does not usually cause brief abrupt fully reversible curtain episodes linked to a single carotid circulation.']],explanation:'Abrupt transient monocular visual loss can represent retinal ischemia, sometimes termed amaurosis fugax. The ophthalmic artery typically arises from the ipsilateral internal carotid artery, so the symptomatic side and irregular severe plaque fit an embolic source. A normal interval eye examination does not exclude transient ischemia. The patient needs urgent vascular and stroke evaluation rather than reassurance based on recovery. Management of symptomatic carotid disease depends on severity, procedural risk, timing, and other factors; this question tests anatomical and clinical attribution rather than a fixed revascularization threshold.',objective:'Localize abrupt monocular curtain-like visual loss to retinal ischemia and assess the ipsilateral carotid as an embolic source.',takeaways:['Complete visual recovery does not make retinal ischemia benign.','Monocular and homonymous deficits localize differently.'],references:[{label:'AHA/ASA secondary stroke prevention guideline (2021; exact carotid and retinal claims require review)',url:'https://www.ahajournals.org/doi/10.1161/STR.0000000000000375'}],evidenceNote,concerns:['Source DOI and exact retinal-localization claims need direct verification; no procedural eligibility threshold is specified.']},
{code:'op-s3-0353',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Transient global amnesia',subtopic:'Isolated temporary encoding failure',concept:'hours of isolated anterograde amnesia with preserved identity and recovery suggest TGA after mimics are excluded',task:'diagnosis',setting:'emergency',service:'acute cognitive neurology',ageGroup:'older-adult',nutrition:false,difficulty:3,difficultyRationale:'Separates impaired new-memory formation from altered consciousness and focal deficits.',stem:'A 62-year-old woman abruptly begins asking repeatedly why she is at a family gathering. She recognizes relatives, knows her name, follows instructions, and has normal speech, strength, and attention, but cannot retain new information for more than a few minutes. Glucose is normal, and there is no head injury or seizure history. Symptoms resolve fully within six hours after evaluation excludes an acute alternative. Which syndrome best fits?',choices:[['Transient global amnesia','A witnessed episode of isolated new-memory encoding failure with preserved identity and other functions, followed by recovery within a day, supports transient global amnesia after appropriate exclusion of mimics.'],['Delirium as the best description of the entire episode','Delirium primarily involves impaired attention and awareness, often with broader fluctuating cognition; preserved attention and isolated memory encoding failure make this presentation less typical.'],['A progressive Alzheimer dementia established by the episode','A completely resolving hours-long isolated syndrome does not establish a progressive dementia, which requires a longitudinal pattern and appropriate functional and cognitive assessment.'],['Dissociative loss of autobiographical identity','Dissociative amnesia often involves autobiographical memory loss, whereas this patient retains personal identity and remote recognition but cannot encode new events during the episode.']],explanation:'Transient global amnesia is a clinical syndrome of temporary profound anterograde amnesia, often with repetitive questioning, while personal identity and many other neurological functions remain intact. Recovery within twenty-four hours is part of the expected syndrome description. Acute amnesia still requires evaluation for stroke, seizure, toxic or metabolic causes, trauma, and other mimics; the benign label should not be applied reflexively at presentation. The stem provides a witnessed isolated episode and completed exclusion of an acute alternative. Recurrent brief episodes or additional neurological features would change the differential.',objective:'Recognize the clinical pattern of transient global amnesia only after evaluating acute amnesia for dangerous or treatable mimics.',takeaways:['Encoding failure is different from loss of consciousness.','An acute benign syndrome label requires an appropriate exclusion process.'],references:[{label:'German Society of Neurology transient global amnesia guideline (2023; professional primary guideline, direct access pending)',url:'https://register.awmf.org/assets/guidelines/030-083l_S1_Transiente_globale_Amnesie_2023-01_01.pdf'}],evidenceNote,concerns:['Non-US guideline in German requires direct source and translation review; verify current diagnostic criteria and exclusion strategy.']},
{code:'op-s3-0354',category:'neurological',subject:'Pharmacology',system:'Nervous System',topic:'Eating-disorder seizure medication safety',subtopic:'Bupropion contraindication',concept:'bulimia history remains relevant to bupropion seizure risk even when current electrolytes are normal',task:'management',setting:'ambulatory',service:'psychiatry neurology safety',ageGroup:'adult',nutrition:true,difficulty:3,difficultyRationale:'Uses a nutritional-psychiatric history to identify a labeled medication risk despite reassuring current laboratory results.',stem:'A 28-year-old woman with depression requests bupropion because a friend found it helpful. During medication reconciliation she describes a prior diagnosis of bulimia nervosa with recurrent bingeing and purging. She says the behavior has stopped, and current sodium, potassium, and glucose are normal. She has never had a seizure. What is the most appropriate prescribing decision?',choices:[['Choose an alternative treatment after reviewing the bupropion contraindication associated with bulimia','Current or prior bulimia is a labeled contraindication because of seizure risk; normal electrolytes today do not remove the relevance of that history.'],['Prescribe bupropion because a normal potassium result eliminates its seizure risk','Electrolyte status is only part of seizure risk assessment, and a normal present result does not override the medication\'s eating-disorder contraindication.'],['Prescribe bupropion only if she promises not to purge again','A promise cannot remove a labeled risk associated with current or prior bulimia, and safe prescribing should use an appropriate alternative and supportive care.'],['Add an antiseizure drug routinely so bupropion can always be used','Routine prophylactic antiseizure treatment is not an established strategy for bypassing this contraindication and creates additional medication burden without resolving the prescribing concern.']],explanation:'Bupropion can lower the seizure threshold. Official labeling identifies current or prior anorexia nervosa or bulimia nervosa as a contraindication, so the history matters even when a single laboratory panel is normal and there has been no prior seizure. A clinician should discuss another appropriate depression treatment and assess ongoing nutritional and eating-disorder needs without stigmatizing the disclosure. The decision is not based simply on body weight or whether the patient appears well today. Medication safety requires integrating historical diagnoses, not only the immediate vital signs and electrolytes.',objective:'Avoid bupropion when a current or prior bulimia diagnosis creates a labeled seizure-risk contraindication.',takeaways:['A normal electrolyte panel does not erase relevant medication contraindications.','Ask about eating-disorder history before prescribing.'],references:[{label:'DailyMed bupropion hydrochloride XL official labeling (indexed fixed product label)',url:'https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=98d5977f-9b32-46db-bd36-a2c4d1b0710a'}],evidenceNote,concerns:['Verify current product-specific labeling; the reference is a particular XL product rather than a recommendation for its dose.']},
{code:'op-s3-0355',category:'neurological',subject:'Pediatrics',system:'Nervous System',topic:'Ketogenic epilepsy therapy oversight',subtopic:'Structured nutritional treatment',concept:'therapeutic ketogenic diets for drug-resistant epilepsy require supervised nutritional and metabolic monitoring',task:'management',setting:'ambulatory',service:'pediatric epilepsy nutrition',ageGroup:'pediatric',nutrition:true,difficulty:3,difficultyRationale:'Distinguishes an evidence-based dietary therapy from an unsupervised restrictive household diet.',stem:'A 6-year-old girl has persistent seizures despite two appropriately selected and tolerated antiseizure regimens. Her parents ask about a ketogenic diet and plan to remove nearly all carbohydrate from meals themselves. She is already falling behind on weight gain. Her neurologist considers dietary therapy potentially appropriate after further evaluation. What is the best next step before the family changes her diet?',choices:[['Refer to a specialist epilepsy dietary team for assessment, a complete prescription, and monitoring','Therapeutic ketogenic treatment requires individualized calories, nutrients, contraindication assessment, and metabolic monitoring, particularly when growth is already vulnerable.'],['Start unrestricted butter and oil while stopping all vitamin supplements','An unbalanced fat-only approach risks inadequate protein, energy distribution, micronutrients, and growth; ketogenic epilepsy therapy is a structured nutritional prescription rather than indiscriminate restriction.'],['Stop antiseizure medication abruptly once carbohydrate intake falls','Dietary therapy does not justify abrupt medication withdrawal, which can destabilize seizure control; any medication changes require the treating epilepsy team.'],['Reject all dietary treatment because epilepsy can never respond to nutrition','Selected drug-resistant epilepsies can respond to supervised dietary therapy, but potential benefit does not remove the need for appropriate patient selection and nutritional safety.']],explanation:'Ketogenic dietary therapy can help some children with drug-resistant epilepsy, but it is a medical nutrition intervention rather than a generic weight-loss diet. Specialist evaluation assesses suitability and contraindications, while a dietitian ensures adequate energy, protein, micronutrients, fluids, and growth monitoring. Follow-up also addresses metabolic and renal adverse effects and family feasibility. The child\'s poor weight gain increases the importance of a complete prescription. Dietary treatment is generally integrated with ongoing epilepsy care, and antiseizure drugs should not be abruptly discontinued when the diet begins.',objective:'Use specialist-supervised nutritional and metabolic planning when considering ketogenic therapy for a child with drug-resistant epilepsy.',takeaways:['Therapeutic restriction still requires nutritional completeness.','Monitor growth and metabolic effects during dietary epilepsy treatment.'],references:[{label:'International Ketogenic Diet Study Group updated recommendations (2018; primary consensus guideline, direct access pending)',url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC5983110/'}],evidenceNote,concerns:['Verify consensus document identity, current contraindications and monitoring; no fixed macronutrient ratio or initiation regimen is prescribed.']},
{code:'op-s3-0356',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Parkinson dysphagia nutrition assessment',subtopic:'Instrumental evaluation of suspected aspiration',concept:'meal-associated cough and weight loss in Parkinson disease require swallowing assessment rather than supplements alone',task:'management',setting:'ambulatory',service:'movement disorders speech nutrition',ageGroup:'older-adult',nutrition:true,difficulty:3,difficultyRationale:'Integrates nutritional decline and an airway clue when routine motor control appears acceptable.',stem:'A 74-year-old woman with Parkinson disease has lost weight despite apparently adequate meals prepared by her daughter. Her walking and tremor remain stable on medication. Meals take much longer, she coughs after thin liquids, and her voice sometimes sounds wet afterward. She has no fever or acute respiratory distress. Which next step best addresses the combined nutritional and respiratory concern?',choices:[['Arrange specialist swallowing evaluation, with instrumental assessment when indicated, and a coordinated nutrition plan','Meal-related cough, wet voice, prolonged eating, and weight loss suggest dysphagia with possible aspiration; assessment should guide safe intake and adequate nutrition.'],['Add unrestricted thin-liquid supplements without assessing swallowing','Extra calories may be needed, but an unsafe liquid consistency can worsen aspiration risk; the route and texture should follow an appropriate swallowing assessment.'],['Increase levodopa solely because weight has fallen','Motor stability and specific swallowing signs warrant targeted assessment; simply escalating dopaminergic therapy does not establish swallowing safety or ensure nutritional adequacy.'],['Assume weight loss is inevitable and offer no evaluation','Weight loss can reflect modifiable swallowing and feeding problems, so attributing it automatically to disease progression misses an opportunity to improve safety and intake.']],explanation:'Parkinson disease can impair oral and pharyngeal swallowing even when limb motor symptoms seem stable. Coughing, wet voice, prolonged meals, and weight loss justify specialist swallowing evaluation, with a suitable instrumental study when the assessment indicates it. Findings guide texture, posture, supervision, hydration, nutrition, and medication-formulation planning. Supplements alone are insufficient if their consistency or route is unsafe. The absence of pneumonia does not exclude aspiration risk, and some aspiration is silent. Care should preserve the patient\'s preferences while addressing both intake adequacy and airway protection.',objective:'Investigate Parkinson-associated dysphagia when meal-related airway symptoms accompany weight loss rather than treating calorie intake alone.',takeaways:['Stable limb symptoms do not establish safe swallowing.','Use assessment findings to guide both nutrition and airway precautions.'],references:[{label:'ASHA Adult Dysphagia professional practice portal (primary professional resource, direct access pending)',url:'https://www.asha.org/practice-portal/clinical-topics/adult-dysphagia/'}],evidenceNote,concerns:['Verify Parkinson-specific evidence, instrumental-test selection and individualized diet recommendations; no universal texture is prescribed.']},
{code:'op-s3-0357',category:'neurological',subject:'Geriatrics',system:'Nervous System',topic:'Dysphagia diet hydration follow-up',subtopic:'Reduced intake after texture modification',concept:'a prescribed swallowing texture still requires hydration monitoring and reassessment when intake falls',task:'management',setting:'ambulatory',service:'stroke rehabilitation geriatrics',ageGroup:'older-adult',nutrition:true,difficulty:4,difficultyRationale:'Balances aspiration precautions with a competing hydration harm after an intervention.',stem:'A 79-year-old man in stroke rehabilitation receives a prescribed thickened-liquid consistency after a swallowing study. Over the next week he drinks very little because he dislikes it. He becomes orthostatic, sodium rises to 149 mEq/L, and creatinine increases from baseline. There is no fever or pulmonary deterioration. What is the best response to the evolving problem?',choices:[['Treat the dehydration and reassess the swallowing and hydration plan with the multidisciplinary team','A texture prescription does not guarantee adequate intake; dehydration requires correction and individualized reassessment of safe, acceptable hydration options rather than blind continuation.'],['Continue the same plan without review because no pneumonia developed','Absence of pneumonia does not offset demonstrated volume depletion and hypernatremia; swallowing care must also provide adequate fluids and be reassessed when harms emerge.'],['Permit unrestricted thin liquids immediately without discussing swallowing risk','Hydration is urgent, but abandoning a documented safety plan without reassessment can introduce aspiration risk; alternatives should be coordinated while dehydration is treated appropriately.'],['Restrict fluids further to prevent any possible aspiration','Further restriction would worsen the established dehydration and does not constitute a balanced plan for airway safety, renal function, or nutritional recovery.']],explanation:'Texture modification may be appropriate for an individual swallowing pattern, but it can reduce acceptability and intake. Rising sodium, orthostasis, and kidney dysfunction demonstrate that this patient\'s current hydration plan is failing. Acute dehydration should be treated, while speech-language, dietary, nursing, and medical teams reassess consistency, assistance, preferences, and alternative routes or strategies. The answer neither declares all thickened fluids ineffective nor endorses unrestricted water for every patient. Monitoring real intake and physiological response is essential because a technically correct prescription can still cause a clinically important competing harm.',objective:'Recognize and correct dehydration during texture-modified dysphagia care and reassess the individualized hydration strategy.',takeaways:['Monitor actual intake after a diet intervention.','Balance aspiration precautions with hydration and patient acceptability.'],references:[{label:'ASHA Adult Dysphagia professional practice portal (primary professional resource, direct access pending)',url:'https://www.asha.org/practice-portal/clinical-topics/adult-dysphagia/'}],evidenceNote,concerns:['Verify evidence on texture-related intake and suitable reassessment options; no free-water protocol or universal fluid strategy is asserted.']},
{code:'op-s3-0358',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Huntington disease nutritional support',subtopic:'Weight loss despite meal availability',concept:'Huntington-associated weight loss warrants energy-intake and feeding-function assessment rather than automatic calorie restriction',task:'management',setting:'ambulatory',service:'neurogenetics nutrition',ageGroup:'adult',nutrition:true,difficulty:3,difficultyRationale:'Uses motor burden and measured weight loss to individualize an otherwise generic dietary recommendation.',stem:'A 46-year-old man with Huntington disease has lost 7 kg in six months. Chorea makes handling utensils difficult, and he often leaves meals unfinished despite wanting to gain weight. He has no polyuria, diarrhea, or acute illness. A generic handout recommends avoiding all calorie-dense foods because of long-term cardiometabolic risk. Which approach best addresses his current nutritional problem?',choices:[['Assess energy needs and feeding barriers and provide individualized energy-dense nutritional support','Progressive weight loss with motor-related feeding difficulty warrants tailored intake and practical assistance, rather than applying a generic restrictive diet without regard to current nutritional status.'],['Apply the restrictive handout unchanged despite continued weight loss','A broad prevention handout does not account for this patient\'s negative energy balance, functional feeding barriers, and immediate risk of worsening nutritional depletion.'],['Prescribe a high-dose single vitamin as the entire nutrition plan','A single supplement does not correct inadequate total energy and protein intake or the practical difficulty of eating caused by chorea.'],['Delay nutritional assessment until swallowing becomes completely impossible','Waiting for complete feeding failure allows further avoidable weight loss; assessment and support should begin while the patient can participate and use oral strategies.']],explanation:'Huntington disease can combine increased energy requirements, movement-related feeding difficulty, and later dysphagia. Documented weight loss should prompt assessment of actual intake, meal duration, utensils or caregiver support, swallowing symptoms, and other medical contributors. Energy-dense foods or supplements can help when selected within an individualized dietitian-guided plan. Recommendations should respond to current nutritional risk rather than reflexively imposing calorie restriction. The vignette does not imply that cardiometabolic health never matters; it emphasizes balancing that concern against clinically significant ongoing weight loss and functional barriers.',objective:'Individualize nutritional support for Huntington-associated weight loss by assessing energy needs and motor-related feeding barriers.',takeaways:['Functional eating difficulty can reduce intake despite available food.','Generic preventive diets may conflict with an undernourished patient\'s immediate needs.'],references:[{label:'GeneReviews Huntington Disease (NIH-hosted expert reference, indexed 2026)',url:'https://www.ncbi.nlm.nih.gov/books/NBK1305/'}],evidenceNote,concerns:['Expert reference is not a controlled dietary trial; verify disease-specific nutritional recommendations and avoid unsupported survival claims.']},
{code:'op-s3-0359',category:'neurological',subject:'Pediatrics',system:'Nervous System',topic:'Infant botulism treatment pathway',subtopic:'Human botulism immune globulin',concept:'suspected infant botulism needs urgent infant-specific immune globulin consultation without waiting for stool confirmation',task:'management',setting:'hospital',service:'pediatric neuromuscular critical care',ageGroup:'pediatric',nutrition:false,difficulty:3,difficultyRationale:'Selects the infant-specific pathway while respiratory and feeding support proceed.',stem:'A 4-month-old infant develops constipation, poor feeding, a weak cry, and progressive generalized hypotonia over several days. The infant is alert but has poor head control and a weak suck. The examination and specialist consultation strongly suggest infant botulism. Respiratory monitoring and feeding support are established, and stool testing is pending. What disease-specific action should occur next?',choices:[['Contact the infant botulism treatment program urgently to assess and obtain human botulism immune globulin','Suspected infant botulism warrants prompt consultation for the infant-specific immune globulin product based on the clinical syndrome, rather than waiting for laboratory confirmation.'],['Use adult equine antitoxin routinely without infant-specific consultation','Infants have a distinct recommended treatment pathway and product; adult foodborne botulism practice should not be substituted automatically without expert consultation.'],['Wait until the stool result is positive before requesting treatment','Confirmatory testing can be delayed, while progression may continue; the compatible syndrome warrants early treatment consultation and ongoing respiratory and nutritional support.'],['Give oral antibiotics alone to sterilize the bowel as definitive therapy','Antibiotics alone do not neutralize toxin already present and are not the definitive treatment strategy for routine intestinal infant botulism in this setting.']],explanation:'Infant botulism usually results from intestinal colonization by toxin-producing organisms rather than ingestion of preformed toxin as in typical adult foodborne disease. Constipation, weak suck and cry, poor head control, and descending generalized weakness raise concern. Respiratory and feeding support remain essential, and specialist consultation should promptly assess use of human botulism immune globulin without waiting for stool confirmation. The infant-specific treatment pathway differs from routine adult antitoxin practice. The question does not require a honey exposure, because its absence does not exclude infant botulism.',objective:'Use the infant-specific immune globulin consultation pathway promptly when infant botulism is clinically suspected.',takeaways:['Infant botulism does not require a reported honey exposure.','Support breathing and feeding while arranging disease-specific treatment.'],references:[{label:'CDC Clinical Overview of Infant Botulism (indexed government clinical guidance)',url:'https://www.cdc.gov/botulism/hcp/clinical-overview/infant-botulism.html'}],evidenceNote,concerns:['Verify current US consultation and product pathway, organism exceptions and antibiotic indications for concurrent infections.']},
{code:'op-s3-0360',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Miller Fisher syndrome',subtopic:'Ophthalmoplegia ataxia and areflexia',concept:'postinfectious ophthalmoplegia with ataxia and areflexia suggests a Guillain-Barre spectrum variant',task:'diagnosis',setting:'hospital',service:'neuromuscular neurology',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Integrates an unusual weakness-spectrum presentation using reflexes and sensory-motor context.',stem:'A 34-year-old man develops double vision and severe unsteadiness ten days after a respiratory illness. Examination shows bilateral external ophthalmoplegia, absent tendon reflexes, and marked gait ataxia despite nearly normal limb strength. He is alert and has no sensory level, focal cortical deficit, or fever. MRI excludes an acute brainstem infarct. Which syndrome best fits the combined findings?',choices:[['Miller Fisher syndrome','The postinfectious combination of ophthalmoplegia, ataxia, and areflexia is characteristic of a Guillain-Barre spectrum variant even when substantial limb weakness is absent.'],['Isolated ocular myasthenia gravis','Myasthenia can cause ophthalmoplegia, but preserved reflexes and absence of a sensory ataxia are more typical; it does not explain the complete triad here.'],['Acute unilateral vestibular neuritis','Vestibular neuritis may cause unsteadiness and nystagmus but does not ordinarily produce bilateral external ophthalmoplegia with generalized tendon areflexia.'],['A compressive thoracic myelopathy','A thoracic cord lesion does not explain bilateral ocular motor dysfunction, and it would be expected to produce a sensory level or long-tract pattern rather than this triad.']],explanation:'Miller Fisher syndrome is a Guillain-Barre spectrum disorder classically involving ophthalmoplegia, ataxia, and areflexia. Limb strength may initially be relatively preserved, so absence of classic ascending paralysis does not rule it out. A compatible recent infection and exclusion of a central structural mimic strengthen the interpretation; specialist assessment may include relevant antibody testing and monitoring for overlap or progression. Respiratory or bulbar involvement must still be assessed rather than assuming that an ophthalmic presentation is always benign. The triad is more discriminating than diplopia or ataxia alone.',objective:'Recognize a Miller Fisher pattern from the combined postinfectious triad of ophthalmoplegia, ataxia, and areflexia.',takeaways:['Guillain-Barre spectrum disease can present without major limb weakness.','Assess for progression and bulbar or respiratory overlap.'],references:[{label:'NINDS Guillain-Barre Syndrome (indexed source; direct page access previously returned403)',url:'https://www.ninds.nih.gov/health-information/disorders/guillain-barre-syndrome'}],evidenceNote,concerns:['Verify variant-specific diagnostic evidence and monitoring recommendations; the broad source does not establish every antibody or treatment claim.']},
{code:'op-s3-0361',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Chronic demyelinating neuropathy',subtopic:'Progression beyond an acute monophasic course',concept:'progressive proximal and distal areflexic sensorimotor weakness over months suggests CIDP',task:'diagnosis',setting:'ambulatory',service:'neuromuscular medicine',ageGroup:'adult',nutrition:false,difficulty:3,difficultyRationale:'Uses the prolonged trajectory and demyelinating physiology to distinguish chronic from acute neuropathy.',stem:'A 54-year-old man has gradually worsening difficulty climbing stairs and fastening buttons over four months. Numbness affects both hands and feet, and tendon reflexes are absent. Nerve conduction studies show marked slowing, conduction block, and prolonged distal latencies in several nerves. There is no sensory level, diabetes, or known family neuropathy. Which diagnosis best fits the time course and electrophysiology?',choices:[['Chronic inflammatory demyelinating polyradiculoneuropathy','A progressive months-long proximal and distal sensorimotor syndrome with areflexia and acquired demyelinating features supports CIDP rather than a brief monophasic acute neuropathy.'],['Typical acute monophasic Guillain-Barre syndrome','Guillain-Barre syndrome generally reaches its nadir within an acute interval; ongoing progression for months requires reconsideration of a chronic inflammatory process or another mimic.'],['Amyotrophic lateral sclerosis','ALS can cause weakness but does not characteristically produce this combination of prominent sensory loss and acquired demyelinating nerve-conduction abnormalities with conduction block.'],['An isolated cervical radiculopathy','One root lesion does not explain symmetric involvement of multiple limbs, generalized areflexia, distal sensory loss, and demyelinating findings across several peripheral nerves.']],explanation:'CIDP is an acquired immune-mediated demyelinating peripheral neuropathy that may progress or relapse over a chronic interval. Proximal as well as distal weakness, sensory involvement, reduced reflexes, and supportive electrodiagnostic findings strengthen the diagnosis. Time course helps distinguish it from typical acute Guillain-Barre syndrome, but diagnosis requires formal criteria and exclusion of mimics, not duration alone. Paraproteinemic disease, hereditary neuropathy, diabetes, and other causes may need evaluation. Recognition matters because appropriate specialist-directed treatment can differ from management of irreversible axonal or hereditary conditions.',objective:'Consider CIDP when an acquired areflexic demyelinating sensorimotor neuropathy progresses over months rather than an acute monophasic interval.',takeaways:['Use the full longitudinal course in neuropathy diagnosis.','Demyelinating findings require formal interpretation and mimic exclusion.'],references:[{label:'NIH MedlinePlus Chronic Inflammatory Demyelinating Polyneuropathy (indexed government expert reference)',url:'https://medlineplus.gov/ency/article/000777.htm'}],evidenceNote,concerns:['Verify current EAN/PNS electrodiagnostic criteria and duration definitions; a broad reference does not establish formal diagnostic eligibility.']},
{code:'op-s3-0362',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'ICU-acquired axonal neuropathy',subtopic:'Weakness during recovery from sepsis',concept:'new diffuse weakness with reduced sensory and motor amplitudes after critical illness supports critical illness polyneuropathy',task:'diagnosis',setting:'hospital',service:'critical care rehabilitation',ageGroup:'adult',nutrition:false,difficulty:4,difficultyRationale:'Interprets electrophysiology to separate peripheral axonal injury from muscle or junction dysfunction.',stem:'A 60-year-old man survives septic shock after two weeks of mechanical ventilation. Sedation has cleared, but he has diffuse flaccid limb weakness and difficulty weaning despite improving lungs. Reflexes are reduced, and distal sensation is impaired. Nerve conduction studies show low sensory and motor response amplitudes with relatively preserved conduction velocities. No significant decrement appears with repetitive stimulation. Which process best explains the findings?',choices:[['Critical illness polyneuropathy','Critical illness can cause a diffuse axonal sensorimotor neuropathy, producing low response amplitudes, sensory abnormalities, areflexic weakness, and difficulty weaning during systemic recovery.'],['Isolated critical illness myopathy without nerve involvement','Myopathy can coexist and cause weakness, but reduced sensory nerve amplitudes and distal sensory loss specifically support a neuropathic component rather than muscle disease alone.'],['Myasthenia gravis as the best electrophysiological match','Myasthenia usually preserves sensation and sensory nerve responses; this diffuse axonal sensorimotor pattern is not the typical junctional transmission abnormality.'],['Acute cervical spinal cord compression','A cord lesion requires consideration if indicated, but diffuse peripheral sensory and motor amplitude loss with preserved relative velocity supports an axonal peripheral process instead.']],explanation:'ICU-acquired weakness can reflect neuropathy, myopathy, or both. In critical illness polyneuropathy, axonal sensorimotor injury reduces motor and sensory response amplitudes, often with relatively preserved velocities compared with a primary demyelinating disorder. Sensory abnormalities help distinguish this from an isolated myopathy or myasthenia. Diagnosis still requires assessment for ongoing sedation, metabolic disturbances, central lesions, and other causes of weakness. The case provides a characteristic recovery setting plus supportive physiology; it does not imply that every failed ventilator wean after sepsis is neurological.',objective:'Identify a neuropathic component of ICU-acquired weakness using sensory loss and axonal sensorimotor conduction findings.',takeaways:['ICU neuropathy and myopathy can coexist.','Sensory nerve findings help distinguish nerve from isolated muscle disease.'],references:[{label:'ATS Clinical Practice Guideline: Diagnosis of ICU-Acquired Weakness in Adults (2014; indexed primary guideline)',url:'https://pubmed.ncbi.nlm.nih.gov/25496103/'}],evidenceNote,concerns:['Historical guideline and indexed abstract require full electrodiagnostic claim review and confirmation of contemporary terminology.']},
{code:'op-s3-0363',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Glucocorticoid-associated weakness',subtopic:'Painless proximal myopathy',concept:'painless proximal weakness with normal CK during prolonged glucocorticoids suggests steroid myopathy',task:'diagnosis',setting:'ambulatory',service:'rheumatology neuromuscular consultation',ageGroup:'older-adult',nutrition:false,difficulty:3,difficultyRationale:'Distinguishes treatment toxicity from inflammatory disease recurrence using examination and laboratory context.',stem:'A 67-year-old woman has received high-dose prednisone for several months for a systemic inflammatory disorder now clinically quiet. She develops difficulty rising from a low chair and lifting groceries. Weakness is symmetric and proximal; sensation and tendon reflexes are preserved. She has no muscle pain, rash, dysphagia, or dark urine. CK and inflammatory markers are normal. Which diagnosis is most consistent?',choices:[['Glucocorticoid-induced myopathy','Prolonged glucocorticoid exposure with painless symmetric proximal weakness and often normal CK supports a treatment-associated myopathy when inflammatory disease activity is otherwise quiet.'],['Active inflammatory myositis as the best overall explanation','Inflammatory myositis remains a differential consideration, but the exposure, painless course, normal CK, and absence of other activity favor steroid toxicity in this vignette.'],['A length-dependent peripheral polyneuropathy','Polyneuropathy more often produces distal weakness, sensory abnormalities, or reflex changes, none of which matches the predominantly proximal pure motor pattern described.'],['Recurrent rhabdomyolysis','Rhabdomyolysis generally produces substantial CK elevation and may include pain or pigmenturia, rather than months of painless proximal weakness with a normal CK.']],explanation:'Chronic glucocorticoid myopathy commonly causes painless proximal weakness, often involving pelvic girdle muscles, with normal or minimally abnormal muscle enzymes. The medication history and quiet underlying disease help separate this from an inflammatory flare, although normal CK alone does not exclude every muscle disorder. The response should include a supervised benefit-risk review of steroid exposure, rehabilitation, and assessment for additional contributors. Steroids should not be stopped abruptly after prolonged use because adrenal suppression may be present. This question asks for the likely cause rather than a fixed taper regimen.',objective:'Recognize chronic glucocorticoid myopathy from painless proximal weakness with preserved sensation and normal CK during prolonged exposure.',takeaways:['Treatment toxicity can mimic worsening underlying disease.','Avoid abrupt unsupervised withdrawal after prolonged steroids.'],references:[{label:'DailyMed prednisone official label search; exact product-specific adverse-effect evidence pending',url:'https://dailymed.nlm.nih.gov/dailymed/search.cfm?query=prednisone'}],evidenceNote,concerns:['Replace broad labeling search with a fixed verified product label and a current neuromuscular reference for phenotype and CK interpretation.']},
{code:'op-s3-0364',category:'neurological',subject:'Neurology',system:'Nervous System',topic:'Traumatic central cord syndrome',subtopic:'Disproportionate upper-limb weakness',concept:'cervical hyperextension in a stenotic spine can produce arm-predominant incomplete cord injury',task:'diagnosis',setting:'emergency',service:'trauma spine neurology',ageGroup:'older-adult',nutrition:false,difficulty:3,difficultyRationale:'Integrates mechanism and distribution rather than relying on fracture detection alone.',stem:'A 76-year-old man falls forward, striking his forehead and extending his neck. He has known cervical stenosis. After the fall, hand and arm strength is markedly reduced, while leg strength is only mildly impaired. There is patchy sensory loss and urinary retention. CT shows no major fracture, but MRI demonstrates cervical cord edema. Which spinal cord syndrome best fits this pattern?',choices:[['Central cord syndrome','Hyperextension in a stenotic cervical spine with greater arm than leg weakness is a characteristic incomplete central cord injury pattern, even without a major fracture.'],['Anterior cord syndrome with complete dorsal-column sparing as the defining pattern','Anterior cord injury more typically emphasizes motor and pain-temperature loss below the lesion; disproportionate upper-limb weakness after hyperextension favors central cord syndrome.'],['Brown-Sequard syndrome','Hemisection classically produces an asymmetric combination of ipsilateral motor-proprioceptive and contralateral pain-temperature deficits, unlike the bilateral arm-predominant weakness described here.'],['An isolated bilateral carpal tunnel syndrome','Median nerve compression cannot account for acute whole-arm weakness, leg involvement, bladder dysfunction, and an intramedullary cervical MRI abnormality after trauma.']],explanation:'Central cord syndrome is an incomplete cervical spinal cord injury classically associated with greater motor impairment in the upper than lower limbs. It can occur after hyperextension in an older person with degenerative canal narrowing, without a conspicuous fracture on CT. MRI evaluates cord and soft-tissue injury, while spinal precautions and specialist trauma assessment remain necessary. The syndrome is recognized by the clinical distribution; simplified historical tract maps should not be treated as a complete explanation of its pathophysiology. Other deficits and severity vary among patients.',objective:'Recognize an arm-predominant incomplete cervical cord injury after hyperextension in a stenotic spine despite no major CT fracture.',takeaways:['Absence of a major fracture does not exclude cord injury.','Compare upper- and lower-limb motor severity after cervical trauma.'],references:[{label:'NSW Emergency Care Institute Back and Neck Injuries clinical tool (indexed government clinical resource)',url:'https://aci.health.nsw.gov.au/networks/eci/clinical/tools/back-neck'}],evidenceNote,concerns:['Australian resource requires current US trauma-guidance correlation; verify imaging, immobilization and definitive management separately.']},
{code:'op-s3-0365',category:'neurological',subject:'Surgery',system:'Nervous System',topic:'Postneuraxial compressive emergency',subtopic:'Spinal epidural hematoma',concept:'new severe back pain and motor deficit after neuraxial procedure require urgent imaging and decompression assessment',task:'management',setting:'hospital',service:'anesthesia neurosurgery',ageGroup:'older-adult',nutrition:false,difficulty:4,difficultyRationale:'Recognizes a time-sensitive compressive complication rather than expected anesthetic recovery.',stem:'A 70-year-old woman recently treated with a neuraxial catheter after abdominal surgery develops severe lumbar pain and rapidly worsening bilateral leg weakness several hours after catheter removal. Her prior examination had normalized. She has new urinary retention and is receiving anticoagulant prophylaxis. What is the most appropriate response while the surgical and anesthesia teams review the medication timing?',choices:[['Arrange emergency spinal MRI and immediate neurosurgical evaluation for a compressive hematoma','New pain, weakness, and bladder dysfunction after neuraxial instrumentation raise concern for spinal bleeding with compression, requiring urgent imaging and decompression assessment rather than delayed observation.'],['Observe until morning because recurrent weakness is always residual anesthesia','The examination had normalized before new severe pain and progressive deficits emerged; assuming a residual block risks missing a time-sensitive compressive lesion.'],['Give the next anticoagulant dose and reassess only if weakness persists','Possible neuraxial bleeding requires urgent evaluation and medication review; automatically continuing exposure without reassessment can worsen a potentially dangerous compressive process.'],['Arrange outpatient electrodiagnostic testing before spinal imaging','Peripheral testing does not rapidly identify a compressive spinal hematoma, and delaying imaging during progressive weakness risks permanent neurological injury.']],explanation:'An evolving motor or bladder deficit with severe back pain after neuraxial instrumentation warrants emergency consideration of an epidural hematoma or another compressive lesion. Prior recovery from the block makes a new progressive deficit particularly concerning. Urgent MRI and neurosurgical involvement should proceed alongside review of coagulation and anticoagulant exposure. Definitive decisions depend on the imaging, deficit, and clinical course, but should not wait for a routine next-day assessment. This is a procedural complication question, not a blanket statement that prophylactic anticoagulation is always incompatible with neuraxial care.',objective:'Escalate a new painful progressive neurological deficit after neuraxial instrumentation for emergency spinal imaging and neurosurgical assessment.',takeaways:['New deterioration after block recovery is a warning sign.','Review anticoagulant timing without delaying assessment of compression.'],references:[{label:'ASRA Practice Advisory on Neurologic Complications in Regional Anesthesia and Pain Medicine (primary advisory, direct access pending)',url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC2869280/'}],evidenceNote,concerns:['Verify advisory identity, currency and current anticoagulation guidance; no fixed timing or reversal regimen is asserted.']},
{code:'op-s3-0366',category:'neurological',subject:'Medicine',system:'Nervous System',topic:'Malignant spinal cord compression',subtopic:'Neurological symptoms before definitive imaging',concept:'cancer with new cord symptoms warrants urgent MSCC pathway and corticosteroid assessment',task:'management',setting:'emergency',service:'oncology spine emergency',ageGroup:'older-adult',nutrition:false,difficulty:4,difficultyRationale:'Coordinates time-sensitive stabilization, imaging and specialist treatment before diagnostic delay.',stem:'A 64-year-old man with metastatic prostate cancer reports worsening mid-thoracic pain and new difficulty walking. Examination shows bilateral leg weakness, brisk reflexes, and a sensory level. He has no fever or recent trauma. Metastatic spinal cord compression is strongly suspected, but definitive MRI and spine-team assessment are still being arranged. Which additional action is appropriate within an urgent coordinated care pathway?',choices:[['Promptly assess for dexamethasone treatment while arranging emergency MRI and definitive specialist care','Suspected malignant compression with neurological signs warrants urgent corticosteroid consideration and imaging while spine and oncology teams plan definitive treatment; steroids do not replace decompression or radiotherapy.'],['Delay all treatment until the next scheduled cancer clinic visit','New cord dysfunction can progress to irreversible disability, and a routine follow-up interval is inappropriate when malignant compression is strongly suspected.'],['Treat pain alone and allow unrestricted walking until imaging is completed','Analgesia is needed but does not address compression, and mobility should be assessed with spinal stability and neurological safety rather than assumed unrestricted.'],['Perform lumbar puncture as the first test before spinal imaging','CSF sampling does not adequately evaluate suspected extradural malignant compression and should not delay urgent MRI or specialist management of the cord syndrome.']],explanation:'Cancer, focal spinal pain, and a new upper motor cord syndrome raise concern for metastatic spinal cord compression. Urgent MRI and specialist coordination are central, with spinal stability and safe movement assessed. Corticosteroids are commonly recommended promptly when neurological symptoms support malignant compression, after considering contraindications and the diagnostic context. They provide temporary reduction of edema and do not replace definitive surgery or radiation when indicated. Certain suspected hematologic malignancies raise additional diagnostic issues, so treatment should be coordinated rather than extrapolated indiscriminately to every spinal mass.',objective:'Initiate an urgent coordinated malignant cord-compression pathway, including corticosteroid assessment, when cancer-related spinal pain is accompanied by neurological signs.',takeaways:['Neurological change makes cancer-related back pain an emergency.','Steroids support but do not replace definitive treatment.'],references:[{label:'NICE NG234 Spinal Metastases and Metastatic Spinal Cord Compression (2023; indexed primary guideline)',url:'https://www.nice.org.uk/guidance/ng234'}],evidenceNote,concerns:['UK guidance requires US/local protocol correlation and contraindication review; no dexamethasone dose or universal mobility instruction is specified.']},
{code:'op-s3-0367',category:'neurological',subject:'Medicine',system:'Nervous System',topic:'Cerebral metastasis pattern',subtopic:'Multiple junctional lesions with edema',concept:'multiple gray-white junction lesions in a patient with lung cancer favor hematogenous brain metastases',task:'diagnosis',setting:'hospital',service:'neuro-oncology',ageGroup:'older-adult',nutrition:false,difficulty:3,difficultyRationale:'Combines systemic cancer and lesion distribution while preserving imaging uncertainty.',stem:'A 66-year-old woman with newly diagnosed lung adenocarcinoma develops progressive headache and left hand clumsiness. She is afebrile and not neutropenic. MRI shows three enhancing lesions near the cerebral gray-white junction, each with substantial surrounding vasogenic edema. She has no history of cranial radiation. Which diagnosis is the leading explanation requiring neuro-oncology assessment?',choices:[['Hematogenous brain metastases','A known systemic cancer and multiple enhancing junctional lesions with vasogenic edema strongly support metastatic spread, although confirmation and management depend on the overall oncologic context.'],['A single primary low-grade infiltrating glioma','A low-grade glioma more often forms an infiltrative lesion rather than several discrete enhancing junctional masses in a patient with a known metastatic-capable cancer.'],['Radiation necrosis','Radiation injury can mimic tumor after treatment, but this patient has not received cranial radiation, making that explanation incompatible with the supplied history.'],['Typical progressive multifocal leukoencephalopathy','PML is usually a white-matter demyelinating process in immunosuppression and does not typically produce this pattern of multiple discrete enhancing masses with marked edema.']],explanation:'Hematogenous metastases often lodge near vascular junctions and can cause substantial vasogenic edema relative to lesion size. In a patient with lung cancer, multiple enhancing gray-white junction lesions are highly concerning for brain metastases. Imaging is not perfectly specific, and infection or other tumors may require consideration when clinical features differ. Neuro-oncology evaluation addresses diagnosis, systemic disease, symptoms, local therapy options, and supportive care. Absence of prior radiation helps exclude a common treatment-related mimic. The question identifies the leading explanation without asserting that MRI alone proves histology.',objective:'Recognize a likely brain-metastasis pattern by integrating known systemic cancer, multiplicity, junctional distribution, and vasogenic edema.',takeaways:['Cancer context changes the interpretation of intracranial lesions.','Imaging patterns support rather than universally prove histology.'],references:[{label:'Society for Neuro-Oncology consensus review on brain metastases (2022; indexed professional consensus)',url:'https://academic.oup.com/neuro-oncology/article/24/10/1613/6618874'}],evidenceNote,concerns:['Verify exact imaging claims and indications for tissue diagnosis; no imaging pattern definitively excludes infection.']},
{code:'op-s3-0368',category:'neurological',subject:'Medicine',system:'Nervous System',topic:'Pituitary apoplexy endocrine rescue',subtopic:'Suspected acute cortisol deficiency',concept:'hemodynamic instability during pituitary apoplexy warrants immediate glucocorticoid replacement',task:'management',setting:'emergency',service:'endocrine neurosurgical critical care',ageGroup:'adult',nutrition:false,difficulty:4,difficultyRationale:'Recognizes endocrine resuscitation needs within an acute neurological and visual syndrome.',stem:'A 53-year-old man with a known pituitary macroadenoma develops abrupt severe headache, vomiting, visual-field loss, and confusion. Blood pressure is 82/48 mm Hg despite initial fluid resuscitation, and sodium is low. MRI shows hemorrhage into the pituitary mass. Cortisol and other endocrine samples are drawn, but results will not return promptly. What treatment should be given while urgent endocrine and neurosurgical evaluation continues?',choices:[['Immediate stress-dose parenteral hydrocortisone','Pituitary apoplexy can cause acute ACTH-cortisol deficiency, and hemodynamic instability warrants urgent glucocorticoid replacement without waiting for a delayed cortisol result.'],['Levothyroxine alone before glucocorticoid coverage','Thyroid replacement does not treat the immediate cortisol deficit and can worsen an unprotected adrenal crisis; glucocorticoid support takes priority in this unstable presentation.'],['Fluid restriction as the only treatment because sodium is low','Hyponatremia does not explain away shock or remove the need for resuscitation and cortisol replacement in an unstable patient with pituitary apoplexy.'],['Withhold steroids until a formal stimulation test is completed','Waiting for dynamic confirmation in a clinically unstable suspected cortisol-deficient emergency risks preventable deterioration and should not delay appropriate replacement after feasible samples are obtained.']],explanation:'Pituitary apoplexy is an acute hemorrhagic or ischemic pituitary event that can combine headache, visual compromise, altered consciousness, and acute pituitary hormone failure. Cortisol deficiency is a potentially fatal component, so an unstable patient should receive prompt parenteral hydrocortisone while resuscitation and specialist management proceed. Blood samples can be obtained first if this causes no meaningful delay. Definitive neuro-ophthalmic and neurosurgical decisions depend on severity and evolution. The question emphasizes endocrine rescue rather than implying that every radiographic pituitary hemorrhage requires identical surgery.',objective:'Treat suspected acute cortisol deficiency immediately in hemodynamically unstable pituitary apoplexy while coordinating definitive specialist care.',takeaways:['Neurological emergencies can include an endocrine resuscitation problem.','Do not delay lifesaving cortisol replacement for formal testing.'],references:[{label:'Society for Endocrinology emergency guidance: Pituitary Apoplexy (2016; indexed primary guidance)',url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC5314810/'}],evidenceNote,concerns:['Historical UK guidance requires contemporary local regimen review; no exact dose or surgical threshold is specified.']},
{code:'op-s3-0369',category:'neurological',subject:'Biochemistry',system:'Nervous System',topic:'Refeeding neuromuscular failure',subtopic:'Phosphate and cellular energy',concept:'rapid phosphate depletion during refeeding can impair ATP dependent respiratory muscle function',task:'foundational-science',setting:'hospital',service:'nutrition critical care',ageGroup:'adult',nutrition:true,difficulty:3,difficultyRationale:'Connects a feeding-related electrolyte shift to a new neuromuscular complication.',stem:'A severely undernourished 48-year-old man begins nutritional rehabilitation after prolonged minimal intake. Within two days he develops generalized weakness and a shallow cough. Serum phosphate falls from 2.8 to 0.7 mg/dL, with concurrent declines in potassium and magnesium. Chest imaging shows no new infiltrate. Which biochemical consequence most directly contributes to the new respiratory muscle weakness?',choices:[['Reduced availability of phosphate for ATP-dependent cellular processes','Severe phosphate depletion can impair cellular energy availability, weakening skeletal and respiratory muscle during refeeding-associated intracellular electrolyte shifts in an undernourished patient.'],['Excess ATP production that permanently contracts the diaphragm','Phosphate depletion limits rather than increases available high-energy phosphate, and the described weakness is not explained by an excess-energy fixed diaphragm contraction.'],['Increased extracellular phosphate causing calcium-phosphate precipitation in nerves','The measured phosphate is profoundly low, not elevated; the relevant acute problem is depletion during feeding rather than hyperphosphatemic tissue deposition.'],['Selective failure of vitamin B12 absorption as the immediate two-day mechanism','B12 disorders generally do not explain an abrupt phosphate-linked respiratory decline within two days of feeding; the measured electrolyte shift supplies the immediate mechanism.']],explanation:'Refeeding stimulates insulin-driven uptake and utilization of phosphate, potassium, and magnesium in a patient whose total-body stores may already be depleted. Severe hypophosphatemia can impair ATP-dependent muscle function and contribute to diaphragmatic weakness, respiratory failure, and other organ dysfunction. The patient requires urgent clinical management, electrolyte correction, and reassessment of feeding intensity and thiamine support. Normal or near-normal initial serum values do not establish adequate total-body stores. This question asks for a biochemical contributor and does not imply that phosphate is the only possible cause of weakness during nutritional rehabilitation.',objective:'Explain refeeding-associated respiratory muscle weakness through severe phosphate depletion and impaired cellular energy availability.',takeaways:['Serum values can initially mask depleted total-body stores.','Refeeding monitoring includes phosphate, potassium, magnesium, and clinical function.'],references:[{label:'ASPEN Consensus Recommendations for Refeeding Syndrome (2020; indexed primary consensus)',url:'https://doi.org/10.1002/ncp.10474'}],evidenceNote,concerns:['Verify phosphate units, mechanism wording and current refeeding management; no universal starting calorie or replacement dose is prescribed.']},
{code:'op-s3-0370',category:'neurological',subject:'Physiology',system:'Nervous System',topic:'Water excess and cerebral edema',subtopic:'Acute exercise-associated hyponatremia',concept:'acute hypotonic extracellular fluid drives osmotic water movement into brain cells',task:'foundational-science',setting:'emergency',service:'sports emergency neurology',ageGroup:'adult',nutrition:true,difficulty:3,difficultyRationale:'Interprets fluid history and sodium to identify a cerebral osmotic mechanism rather than assuming dehydration.',stem:'A 33-year-old runner becomes confused and has a seizure after a prolonged event. She drank large amounts of water at every station and gained weight during the race. Temperature and glucose are normal. Serum sodium is 118 mEq/L, and measured serum osmolality is low. Emergency treatment is initiated. Which mechanism most directly explains the neurological deterioration?',choices:[['Water movement into brain cells in response to acute extracellular hypotonicity','Rapid reduction in extracellular effective osmolality drives water into brain cells, contributing to cerebral edema and severe neurological symptoms in acute exercise-associated hyponatremia.'],['Water loss from brain cells because extracellular sodium is high','The sodium is markedly low rather than high, so the immediate osmotic direction is toward intracellular swelling rather than brain-cell dehydration.'],['A direct toxic effect of dietary sodium overload','The history and laboratory data indicate excess hypotonic fluid relative to sodium, not a measured sodium overload causing hypertonic neurological injury.'],['Isolated lactate accumulation from normal exercise as a sufficient explanation','Exercise can raise lactate, but severe hypotonic hyponatremia with weight gain provides a more direct explanation for seizure and confusion requiring targeted emergency care.']],explanation:'Acute severe hyponatremia lowers extracellular tonicity before the brain can fully adapt, promoting intracellular water movement and cerebral edema. Weight gain despite prolonged exercise and heavy water intake argue against assuming simple dehydration. Exercise-associated nonosmotic vasopressin release can limit water excretion and contribute. Severe neurological symptoms demand emergency management with careful sodium monitoring according to the applicable protocol. The mechanism differs from chronic osmotic adaptation and does not justify rapid indiscriminate correction of every hyponatremia case. Prevention counseling should address excessive forced fluid intake rather than a universal fixed drinking volume.',objective:'Explain neurological symptoms of acute hypotonic exercise-associated hyponatremia through osmotic brain-cell swelling.',takeaways:['Collapsed athletes are not necessarily dehydrated.','Acute and chronic hyponatremia have different adaptation and correction considerations.'],references:[{label:'International Exercise-Associated Hyponatremia Consensus Statement (2015; indexed primary consensus)',url:'https://doi.org/10.1136/bjsports-2015-095004'}],evidenceNote,concerns:['Verify current sports-emergency guidance, tonicity interpretation and correction safety; no saline dose or correction target is asserted.']},
];
